/** Deterministic stand-in for the source game's weighted random roll. Replay must be
 * identical on client and server, so hash the independent action counter into a stable
 * unit interval and then apply the recovered cumulative-frequency selection rule. */
function weightedPick<T extends { weight: number }>(items: readonly T[], count: number, salt: number): T | null {
  if (!items.length) return null;
  const weighted = items
    .filter((item) => Number.isFinite(item.weight) && item.weight > 0)
    .sort((a, b) => a.weight - b.weight);
  if (!weighted.length) return items[count % items.length] ?? items[0];
  const total = weighted.reduce((sum, item) => sum + item.weight, 0);
  let x = (count + 1 + salt) | 0;
  x = Math.imul(x ^ (x >>> 16), 0x21f0aaad);
  x = Math.imul(x ^ (x >>> 15), 0x735a2d97);
  const roll = (((x ^ (x >>> 15)) >>> 0) / 0x1_0000_0000) * total;
  let cumulative = 0;
  for (const item of weighted) {
    cumulative += item.weight;
    if (roll < cumulative) return item;
  }
  return weighted[weighted.length - 1];
}

function toSim(u: CombatUnit, i: number): SimUnit {
  const mult = u.attacks[0]?.mult ?? 1;
  const isPlayer = u.team === "player";
  const home = isPlayer ? clusterHome(i) : { x: ENEMY_SPAWN_X, y: CENTER_Y };
  // Enemies are authored with `abilities: []` everywhere in the raid catalog, so
  // passing the list through is byte-identical for raids — and it is what lets a PvP
  // formation defender keep the passives that run themselves (a healer that heals).
  const abilities = u.abilities ?? [];
  return {
    id: u.id,
    sourceKey: u.sourceKey,
    mutation: u.mutation ?? 0,
    team: u.team,
    name: u.name,
    group: u.group,
    className: u.className,
    color: u.color,
    isBoss: u.isBoss,
    isGarden: u.isGarden,
    isHeadless: u.isHeadless,
    x: home.x,
    y: home.y,
    // Epic Boss attempts can begin with damage retained from an earlier escape.
    // Preserve the supplied combat HP instead of silently healing every unit to
    // max while translating it into simulation state.
    hp: Math.max(0, Math.min(u.maxHp, u.hp)),
    maxHp: u.maxHp,
    damageReduction: u.damageReduction ?? 0,
    teamAuraStats: u.teamAuraStats ? { ...u.teamAuraStats } : null,
    attackMultiplier: mult,
    walkingSpeedMult: u.walkingSpeedMult ?? 1,
    alive: true,
    oneShotProtectionUsed: false,
    state: isPlayer ? "waiting" : "queued",
    charge: 0,
    focus: u.focus ?? 0,
    distracted: false,
    awaitRelease: false,
    distractStep: 0,
    distractSeed: i,
    bubbleMs: 0,
    struckThisTick: false,
    walkingThisTick: false,
    vx: 0,
    vy: 0,
    prevX: home.x,
    prevY: home.y,
    // Ground-truth per-swing damage BEFORE the lineup band: finalPower(str×10) × attackMult.
    // Enemies use this as-is (band always 1.0); a player zombie's normal swing multiplies it by
    // lineupDamageBand(lineupIndex) at hit time (activated specials use the unbanded value).
    damage: Math.max(1, Math.round(deriveHitDamage(u.str * POWER_PER_STR, mult))),
    attackName: u.attacks[0]?.name ?? "",
    cooldownMs: u.attackCooldownMs,
    timerMs: u.attackCooldownMs,
    moveSpeed: isPlayer ? advanceSpeed(u.dex) * (u.walkingSpeedMult ?? 1) : EMERGE_SPEED,
    power: u.str * POWER_PER_STR,
    homeX: home.x,
    homeY: home.y,
    mill: hash(i * 3 + 2) * Math.PI * 2,
    formOrder: 0,
    frontPriority: isPlayer && !!u.isHeadless,
    inLine: false,
    lineupIndex: 0,
    slotX: home.x,
    slotY: home.y,
    abilities,
    windupKey: null,
    windupMs: 0,
    windupTotal: 0,
    abilityCdMs: 0,
    blockMs: 0,
    buddyId: null,
    buddyCarrierId: null,
    buddyMountMs: 0,
    healTimerMs: 0,
    healAoeTimerMs: abilities.includes("healAOE") ? 20_000 : 0,
    damageFxTaken: 0,
    healFxSeq: 0,
    healCastSeq: 0,
    laserTimerMs: laserInterval(abilities, u.attackCooldownMs),
    laserFxSeq: 0,
    laserTargetId: null,
    explodeFxSeq: 0,
    abilityRollSeq: 0,
    usedAbilities: [],
    resurrectUsed: false,
    unwrapUsed: false,
    unwrapFxSeq: 0,
    lastLaughFxSeq: 0,
    shield: 0,
    phaseUsed: false,
    phaseMs: 0,
    phaseFxSeq: 0,
    teleportPending: false,
    teleportFxSeq: 0,
    stunMs: 0,
    knockBackToX: 0,
    knockBackSpeed: 0,
    blastAirMs: 0,
    blastAirTotalMs: 0,
    blastAirHeight: 0,
    blastSpin: 0,
    knockBack: !isPlayer && !!u.knockBack,
    // Absent chance = "every swing carries it", but only where the effect exists at
    // all: defaulting a unit with no stun to stunChance 1 would open the shared roll
    // below for it and hand back the every-hit knockback this replaced.
    knockBackChance: isPlayer ? 0 : u.knockBackChance ?? (u.knockBack ? 1 : 0),
    stunInflictMs: isPlayer ? 0 : u.stunMs ?? 0,
    stunChance: isPlayer ? 0 : u.stunChance ?? ((u.stunMs ?? 0) > 0 ? 1 : 0),
    deathExplosion: isPlayer ? null : u.deathExplosion ?? null,
    knockBackHeadlessOnly: !isPlayer && !!u.knockBackHeadlessOnly,
    curseStunChance: isPlayer ? 0 : u.curseStun?.chance ?? 0,
    curseStunMs: isPlayer ? 0 : u.curseStun?.durationMs ?? 0,
    curseShoveChance: isPlayer ? 0 : u.curseShoveHeadless ?? 0,
    attackDamageTiming: u.attackDamageTiming ?? 0.5,
    isWall: false,
    isSummon: false,
    isFlanker: false,
    smokeWindupMs: 0,
    flankMs: 0,
    isBlocker: false,
    stationX: u.stationX ?? null,
    stationY: u.stationY ?? null,
    deployAtMs: u.deployAtMs ?? null,
    deployAtWaveFrac: u.deployAtWaveFrac ?? null,
    waveBody: false,
    deployWithBoss: u.deployWithBoss ?? false,
    defenseRole: u.defenseRole ?? null,
    anchorsLine: u.anchorsLine ?? true,
    // One level's pool is the unit's OWN built hit points — not `deriveMaxHp(con)`, which
    // skips the level ramp and the tier profile that `maxHp` already carries and would
    // leave the tower's height measured against the wrong yardstick.
    stackBaseHp: u.stack ? Math.max(1, u.maxHp) : 0,
    stackMax: 1,
    stackTimerMs: u.stack?.growMs ?? 0,
    stackGrowMs: u.stack?.growMs ?? 0,
    stackCeiling: u.stack?.maxHeight ?? 1,
    stackSeen: 1,
    stackToppleSeq: 0,
    swapped: false,
    isBozoStack: false,
    burnWalk: false,
    isBubbleRobot: false,
    isTurned: false,
    turnedFromId: null,
    burnMs: 0,
    burnDir: 1,
    burnAnchorX: home.x,
    passedBlockers: [],
    taken: false,
    chargeCfg: u.charge ?? null,
    stunResist: u.stunResist ?? 0,
    chargeTapScale: 1,
    stoneMs: 0,
    gazeReady: false,
    chargeMs: 0,
    poise: 0,
    chargeRestMs: 0,
    chargeFrac: 0,
    chargeBreakSeq: 0,
    chargeSlamSeq: 0,
    staggerMs: 0,
    chargeLockMs: 0,
    dotMs: 0,
    dotPerMs: 0,
    magicCfg: u.magic ?? null,
    magicCdMs: 0,
    magicCastMs: 0,
    magicKind: 0,
    magicCount: 0,
    magicSweepMs: 0,
    magicHit: [],
    magicSeq: 0,
    mirrorsOpponentSpeed: !isPlayer && !!u.mirrorsOpponentSpeed,
    mirrorPace: u.mirrorPace ?? 1,
    loaned: isPlayer && !!u.loaned,
    healMult: u.healMult ?? 1,
    speciesCycleMs: u.speciesCycleMs ?? u.attackCooldownMs,
  };
}

export class BattleSim {
  readonly units: SimUnit[];
  /** This fight's clock, in simulated ms. */
  readonly timeLimitMs: number;
  /** Overtime played once `timeLimitMs` runs out (DO_OR_DIE_HASTE); 0 = none. */
  private _doOrDieMs = 0;
  readonly projectiles: SimProjectile[] = [];
  /** Presentation-only count; reset at the start of every fixed simulation step. */
  projectileImpactsThisTick = 0;
  /** Presentation-only: the `sprite` of the last projectile to connect this step, so the
   *  renderer can pick the authored impact cue (the alien bolt plays stun.wav, not the
   *  generic splat). Cleared with the count above. */
  lastProjectileImpactSprite = "";
  /** Minimum gap between rescue-hazard taps that register (Trapeze Artist, Beach crab).
   *  Defaults to the authored touch pace; the live scene lowers it for a mouse, which
   *  clicks two to three times faster than the gate allows and had most of those clicks
   *  silently discarded. Safe to vary because BOTH hazards are client-only and neither
   *  one's taps are transcribed — the verifier never calls tapCrab/tapGrabber at all, so
   *  it keeps this default forever. See src/raid/hazardTaps.ts. */
  hazardTapCooldownMs = RESCUE_TAP_CD_MS;
  private players: SimUnit[];
  private enemies: SimUnit[];
  private boss: SimUnit | null;
  private bossThrow: BossThrowConfig | null;
  private throwCount = 0;
  private releaseSeq = 0;
  private projSeq = 0;
  private elapsed = 0;
  private emergeCooldown = 0;
  private attacksLanded = 0;
  private playerDamage = 0;
  /** Technique record for achievement quests — see RaidFeats. Part of the snapshot so
   *  a sim restored mid-fight keeps what it has already witnessed. */
  private feats: RaidFeats = emptyRaidFeats();
  /** GROUND TRUTH (`-[ZombieActor fightUpdate:]` 0x4d406): a zombie that dies is appended
   *  to `ZFFightMan.defeatedZombies` and removed from `zombies`. Nothing ever drains that
   *  list except a revival, so it is a BACKLOG that accumulates for the whole fight —
   *  Resurrect is polled against it (`canRez`), not fired at the instant of a death. That
   *  is why a Garden zombie deployed AFTER a casualty can still bring that casualty back.
   *  Ids, not references, so the list survives snapshot/restore intact. */
  private fallen: string[] = [];
  /** The PvP DEFENDERS' corpse backlog, which a defending Resurrect draws on. */
  private fallenDefenders: string[] = [];
  finished = false;
  // ---- round timer + enrage ----
  private roundLeft: number;
  private _enraged = false;
  escaped = false;
  /** The fight clock ran out with both sides still standing. A loss, but a DIFFERENT loss
   *  from being wiped out, and the only one the player can still be holding an army in —
   *  so the result panel names it rather than reporting a defeat that never happened. */
  outOfTime = false;
  /** The fight ended because nothing left on the army's side could hurt the enemy — only
   *  station Gardens standing (see `healersOnly`). An ordinary loss, and the Gardens come
   *  home like any survivor. */
  healersOnlyEnd = false;
  // ---- boss actions (throws AND specials share ONE budget — see stepBossActions) ----
  private specials: BossSpecial[];
  private actions: BossActionChoice[] = []; // the merged weighted roll table
  private nextAction: BossActionChoice | null = null; // pre-rolled, so the renderer can telegraph
  private actionCd = 0; // ms until `nextAction` resolves
  private actionCount = 0; // deterministic roll counter
  private specialCast = 0; // wind-up left on the pending special
  private pendingSpecial: BossSpecial | null = null;
  /** Medusa: the perched boss stands frozen for this long, whatever it was doing. */
  private bossFreezeMs = 0;
  /** Medusa: time until the boss can be frozen again, so a line of them cannot lock it. */
  private bossFreezeLockMs = 0;
  private bossSpecialEffects: { name: string; x: number; y: number }[] = [];
  // ---- the saucer's bubble (raid 15; see dualInvasion.ts) ----
  /** Where in the cycle the saucer is, how much charge is left on the thing it is doing,
   *  and how long it stays quiet before starting the next one. */
  private bubbleIndex = 0;
  private bubbleCastMs = 0;
  private bubbleGapMs = 0;
  /** Cancels the player has left. Seeded from the rung's budget at construction. */
  private cancels = 0;
  /** How many activations have resolved (fired or cancelled). The t9 lockout compares the
   *  activation the last cancel went on against this. */
  private bubbleActivation = 0;
  /** Which of the current dual cast the player cancelled, or null. */
  private bubbleCancelledSlot: number | null = null;
  private lastCancelActivation = -2;
  /** Bumped when a cast lands, when one is cancelled, and when the portal actually moves
   *  somebody — three things the renderer wants to react to and cannot infer. */
  private bubbleFireSeq = 0;
  private bubbleCancelSeq = 0;
  private portalSeq = 0;
  // ---- the big top (raid 14; see dualInvasion.ts) ----
  /** Ms to the next trapeze, bozo conversion, pixel fire and hammer. */
  private trapezeTimerMs = 0;
  private convertTimerMs = 0;
  private fireTimerMs = 0;
  private hammerTimerMs = 0;
  /** The zombies standing in the bozo stack, in the order they were converted. */
  private bozoIds: string[] = [];
  // ---- the duel (raid 13; see dualInvasion.ts) ----
  /** Ms to the next smoke swap, whether the ninja is the one on the ground right now, where
   *  the swap puts whoever comes down, and whether the ninja has retreated for good. */
  private swapTimerMs = 0;
  private ninjaDown = false;
  private duelGroundX = 0;
  private ninjaRetreated = false;
  /** Bumped on every smoke bomb (the captain's entrance and every swap), for the scene. */
  smokeSeq = 0;
  // ---- the Lawyer boss's objection (raid 12; see dualInvasion.ts) ----
  /** Which bubble was taken for each RESOLVED slot, oldest first. Its LENGTH is the index
   *  of the offer currently on the table, which is why nothing else stores that. */
  private signResolved: number[] = [];
  /** The player's committed pick for the offer on the table, or null while they have not
   *  chosen. Cleared when the slot resolves. */
  private signPending: number | null = null;
  /** The rulings in force and what they add up to — DERIVED each tick from the resolved
   *  picks (see refreshRulings), so neither is in the snapshot. */
  private rulings: Ruling[] = [];
  private rulingFx: {
    slow: number; weaken: number; embolden: number; immune: boolean; noHeal: boolean;
    overruled: Set<string>; barred: string[];
  } = { slow: 1, weaken: 1, embolden: 1, immune: false, noHeal: false, overruled: new Set(), barred: [] };
  // ---- carried-grab hazard (Trapeze Artist) ----
  readonly grabbers: SimGrabber[] = [];
  private grabberCfg: GrabberConfig | null;
  private grabberTimer: number; // ms until the next trapeze sweeps in
  private grabSeq = 0;
  // ---- Beach crab hazard (client-only; see the ctor param) ----
  readonly crabs: SimCrab[] = [];
  private crabCfg: CrabConfig | null;
  private crabTimer: number; // ms until the next crab scuttles in
  private crabSeq = 0;
  // ---- Mega-Robot hazard (client-only; see the ctor param) ----
  /** The robot, or null on every raid that has none. Read by the renderer. */
  megaBot: SimMegaBot | null;
  /** The round clock's full length, so the robot can read time ELAPSED on it. */
  private roundTotalMs: number;
  // ---- summon / wall specials ----
  private summonCfg: SummonConfig | null;
  /** `bossSummonList`, by source key. Popped from the front, pushed on the back. */
  private summonQueue: string[] = [];
  private wallTemplate: CombatUnit | null;
  /** The pixel zombie `turnZombie` stands up (null = this boss can't turn anyone). */
  private turnedTemplate: CombatUnit | null;
  private spawnSeq = 0;
  private endlessMechanicTimers: Record<string, number> = {};
  private endlessMechanicCount = 0;
  // ---- wave cadence (see types.WaveCadence) ----
  private cadence: WaveCadence;
  private dripLeft: number;
  /** Enemies allowed on the field right now. Starts at 1 and climbs by one per drip up
   *  to `cadence.maxActive`, which is how the source's swarm actually builds: the drip
   *  can only ever fill ONE free `enemySlots` entry per tick. */
  private activeTarget = 1;
  /** Endless deployment boon; normal fights retain the authored focus duration. */
  private focusChargeMs = CHARGE_MS;
  /** Head Start (Endless): how many more of the army leave with its first deploy. Config, so
   *  a snapshot needs nothing; "first" is read off `releaseSeq`, which it carries. */
  private openingEscort = 0;
  private engageDistance: number;
  private rowXFit = 1; // fraction of the recovered in-row depth that fits inside contact
  private frontX: number;
  /** Any defender carries an authored station (PvP formation defense). Absent in every
   *  raid, which is what keeps the dynamic front line below off their transcripts. */
  private authoredStations = false;
  private supportX: number;
  /** Distinct ACTIVATED moves present in the army (fixed) — the tappable strip. */
  readonly activatedKeys: string[];
  /** The same moves grouped into the BUTTONS that show them (fixed): Explode and
   *  Explode Ver.2 share one, everything else — Bash and Smash included — stands
   *  alone. Derived from `activatedKeys`, so it needs no snapshot slot. See
   *  ACTIVATED_STACKS for why that pair is the only one worth collapsing. */
  readonly activatedGroups: string[][];
  /** Distinct TEAM-passive abilities present (fixed) — the strip's info icons. */
  readonly teamKeys: string[];

  constructor(
    playerUnits: CombatUnit[],
    enemyUnits: CombatUnit[],
    bossThrow: BossThrowConfig | null = null,
    /** Concentration boost spent: skip the focus-bubble minigame (no distractions,
     *  auto-release at full), matching the boost's "fight at full focus" effect. */
    private concentration = false,
    /** Boss special (non-throw) actions to schedule. */
    bossSpecials: BossSpecial[] = [],
    /** Round length before the boss enrages (ms). */
    roundMs: number = DEFAULT_ROUND_MS,
    /** The alien boss's abductee queue (null = this boss can't summon). */
    summonCfg: SummonConfig | null = null,
    /** Blocker the boss's `wall` action spawns (null = don't). */
    wallTemplate: CombatUnit | null = null,
    /** Epic Boss: no butterflies, but the full brain bubble still gates release. */
    private noDistractions = false,
    /** Epic Boss: reaching zero ends the attempt instead of triggering enrage. */
    private escapeOnRoundEnd = false,
    /** Epic Boss presentation: fall from above and land on the combat line instead
     *  of walking in from the right or occupying the normal raid perch. */
    private bossFallsFromSky = false,
    /** Larger bosses need a wider melee line so their art does not swallow zombies. */
    engageDistance = ENGAGE,
    /** Carried-grab hazard (Circus Trapeze Artist) for this raid (null = none). */
    grabber: GrabberConfig | null = null,
    /** Beach crab hazard (null = none). CLIENT-ONLY by design: the server verifier
     *  omits it, so the authoritative replay is the un-harassed run and a crab can only
     *  ever make the player's own result WORSE. See RaidManager.crabOf. */
    crab: CrabConfig | null = null,
    /** How this stage feeds its wave in. Only Zombies vs Aliens departs from the
     *  one-at-a-time default; see types.WaveCadence. */
    cadence: WaveCadence = SOLO_WAVE,
    /** The pixel zombie the Video Games boss's `turnZombie` converts a zombie INTO
     *  (null = this boss can't turn anyone). See raid/videoGameStage.ts. */
    turnedTemplate: CombatUnit | null = null,
    /** The Lawyer boss's placard rotation (null = this invasion has no sign). See
     *  raid/dualInvasion.ts. */
    private signCfg: SignConfig | null = null,
    /** The duel's fight-wide rules (raid 13; null everywhere else): the smoke and the
     *  stand-down around the captain, the dex tax, the counter, the stunning throws and
     *  the smoke swap. See raid/dualInvasion.ts. */
    private duel: DuelConfig | null = null,
    /** The big top's rules (raid 14; null everywhere else): the ringmaster's whip, the
     *  trapeze drop, the bozos and the walking fire. See raid/dualInvasion.ts. */
    private bigTop: BigTopConfig | null = null,
    /** Ms at which this invasion's boss abandons its perch whatever the wave is doing
     *  (the raid-14 ringmaster from rung 5; null everywhere else), and the ground station
     *  it fights from once it is down. */
    private bossDropAtMs: number | null = null,
    private bossGroundStationX: number | null = null,
    /** The saucer's five-action bubble (raid 15; null = this invasion has none). */
    private bubbleCfg: BubbleConfig | null = null,
    /** The blocker the bubble's `wall` action drops. Separate from `wallTemplate` because
     *  that one belongs to a BOSS ACTION and the saucer has no `wall` in its list — raid
     *  15 borrows the JunkBot's (see fightConfig.bubbleWallFor). */
    private bubbleWall: CombatUnit | null = null,
    /** The Mega-Robot (raid 5; null = none). CLIENT-ONLY, like the crab: the verifier
     *  builds without it. See types.MegaBotConfig. */
    megaBot: MegaBotConfig | null = null,
    /** THIS fight's clock (see RAID_TIME_LIMIT_MS): four minutes for every ordinary fight,
     *  six for the dual invasions. Part of the pinned config, so both sides stop on the same
     *  tick. */
    timeLimitMs: number = RAID_TIME_LIMIT_MS,
    private endlessMechanics: EndlessStageMechanics | null = null
  ) {
    this.timeLimitMs = Math.max(1, Math.min(RAID_MAX_TIME_LIMIT_MS, Math.round(timeLimitMs)));
    this.engageDistance = Math.max(ENGAGE, Math.min(300, engageDistance));
    this.grabberCfg = grabber;
    this.grabberTimer = grabber?.spawnDelayMs ?? Infinity;
    this.crabCfg = crab;
    this.crabTimer = crab?.spawnMs ?? Infinity;
    this.roundTotalMs = roundMs;
    this.megaBot = megaBot
      ? {
          phase: "hidden", phaseMs: 0, chargeMs: MEGA_CHARGE_MS, restless: 0,
          eyeHp: megaBot.eyeHp, eyeMaxHp: megaBot.eyeHp, tapDamage: megaBot.tapDamage,
          tapCdMs: 0, eyeHits: 0, targetX: 0, targetY: 0,
          shotSeq: 0, blastSeq: 0, shots: 0,
        }
      : null;
    const enemyHoldX = this.bossFallsFromSky ? EPIC_BOSS_HOLD_X : ENEMY_HOLD_X;
    this.frontX = enemyHoldX - this.engageDistance;
    // A formation defense does not stand at the shared doorway, so the army's line
    // cannot be a constant derived from it — see refreshFrontLine, which runs once the
    // rosters below exist and again every step.
    this.cancels = this.bubbleCfg?.cancels ?? 0;
    // The saucer thinks for a beat before its first idea, so the fight does not open on a
    // cast the player has not been shown the field for yet.
    this.bubbleGapMs = this.bubbleCfg?.gapMs ?? 0;
    this.authoredStations = enemyUnits.some((u) => u.stationX !== undefined && u.stationX !== null);
    // How much of the recovered row depth actually fits. The source's row spans ~90 of its
    // own points and its enemies reach that far; ours reach `engageDistance`, which is less
    // than half that, so the standoff/fan is compressed to fit inside contact. The ORDER is
    // untouched — only the absolute gaps shrink — and this is the one place the recovered
    // formation does not survive at the source's own scale. Raising `ENGAGE` to the
    // source's melee gap would let it, at the cost of re-balancing every raid.
    this.rowXFit = Math.min(1, Math.max(0, this.engageDistance - 8) / BAND_ROW_DEPTH);
    this.supportX = CHARGE_X + (this.frontX - CHARGE_X) * 0.5;
    // Boss always resolves last, after the normal enemies.
    const ordered = [...enemyUnits].sort((a, b) => Number(a.isBoss) - Number(b.isBoss));
    this.players = playerUnits.map((u, i) => toSim(u, i));
    this.enemies = ordered.map((u, i) => toSim(u, i));
    // Endless's deployment boons cut the charge time, never by more than 80% (owner, 2026-11-08).
    this.focusChargeMs = CHARGE_MS *
      (1 - Math.min(MAX_DEPLOY_REDUCTION, Math.max(0, endlessMechanics?.deploymentSpeedBonus ?? 0)));
    // Head Start no longer pushes zombies out at the bell (owner, 2026-11-11): its extras walk
    // on WITH the army's first deploy (releaseCharger), so the opening charge still leaves time
    // for abilities, a Mini climbing onto a Large first above all.
    this.openingEscort = Math.max(0, Math.min(MAX_OPENING_ESCORT, Math.floor(endlessMechanics?.openingDeploy ?? 0)));
    for (const e of this.enemies) {
      e.waveBody = !e.isBoss && e.deployAtMs === null && e.deployAtWaveFrac === null && !e.deployWithBoss;
    }
    this.units = [...this.players, ...this.enemies];
    this.refreshFrontLine();

    this.boss = this.enemies.find((e) => e.isBoss) ?? null;
    if (this.boss) {
      if (this.bossFallsFromSky) {
        this.boss.state = "falling";
        this.boss.x = EPIC_BOSS_HOLD_X;
        this.boss.y = EPIC_BOSS_FALL_Y;
      } else {
        this.boss.state = "structure";
        // An authored perch (PvP formation defense) wins over the shared structure
        // position, which is tuned for a boss SPRITE rather than a zombie rig.
        this.boss.x = this.boss.stationX ?? BOSS_STRUCT_X;
        this.boss.y = this.boss.stationY ?? BOSS_STRUCT_Y;
      }
    }
    // Own it: enrage halves `intervalMs` IN PLACE (see applyEnrage), and the verifier is
    // handed the same pinned config object every time it builds a sim. Sharing it meant a
    // second sim off one config started with an already-enraged boss — the replay silently
    // stopped being a pure function of (config, transcript).
    this.bossThrow = bossThrow ? { ...bossThrow } : null;
    this.specials = this.boss ? bossSpecials : [];
    this.actions = this.buildActionBudget();
    this.rollNextAction();
    // `bossActionCooldownTimer` is only ever written by bossUpdate:, so it starts at
    // ObjC's zero — the boss's first action resolves as soon as it becomes active.
    this.actionCd = 0;
    this.roundLeft = roundMs;
    this.summonCfg = this.boss ? summonCfg : null;
    this.summonQueue = this.summonCfg ? this.summonCfg.queue.map((u) => u.sourceKey) : [];
    this.wallTemplate = this.boss || this.endlessMechanics ? (this.endlessMechanics?.wallTemplate ?? wallTemplate) : null;
    this.turnedTemplate = this.boss || this.endlessMechanics ? (this.endlessMechanics?.turnedTemplate ?? turnedTemplate) : null;
    for (const [key, cooldown] of Object.entries(this.endlessMechanics?.cooldownsMs ?? {})) {
      this.endlessMechanicTimers[key] = Math.max(1_000, Math.round(cooldown));
    }
    this.cadence = {
      maxActive: Math.max(1, Math.round(cadence.maxActive)),
      dripMs: Math.max(0, Math.round(cadence.dripMs)),
      openingActive: Math.max(1, Math.min(Math.round(cadence.maxActive), Math.round(cadence.openingActive ?? 1))),
    };
    this.activeTarget = this.cadence.openingActive ?? 1;
    this.dripLeft = this.cadence.dripMs;
    // Keep every activated move represented. In particular, Mini Buddy remains
    // available on a veteran Large zombie even when it also owns Bash/Smash.
    this.activatedKeys = [
      ...new Set(this.players.flatMap((p) => p.abilities.filter((k) => !!ACTIVATED_ABILITY[k]))),
    ];
    this.activatedGroups = activatedGroupsOf(this.activatedKeys);
    this.teamKeys = [...new Set(this.players.flatMap((p) => teamAbilitiesIn(p.abilities)))];
    this.refreshTeamAuras();
  }

  snapshot(): BattleSimSnapshot {
    return {
      units: this.units.map((u) => ({
        ...u,
        abilities: [...u.abilities],
        passedBlockers: [...u.passedBlockers],
        teamAuraStats: u.teamAuraStats ? { ...u.teamAuraStats } : null,
      })),
      projectiles: this.projectiles.map((p) => ({ ...p })),
      bossId: this.boss?.id ?? null,
      actionCd: this.actionCd,
      nextAction: this.nextAction ? { ...this.nextAction } : null,
      actionCount: this.actionCount,
      throwCount: this.throwCount,
      releaseSeq: this.releaseSeq,
      projSeq: this.projSeq,
      elapsed: this.elapsed,
      emergeCooldown: this.emergeCooldown,
      attacksLanded: this.attacksLanded,
      playerDamage: this.playerDamage,
      feats: {
        abilityKills: this.feats.abilityKills.map((kill) => ({ ...kill })),
        resurrections: this.feats.resurrections.map((rez) => ({ ...rez })),
      },
      fallen: [...this.fallen],
      fallenDefenders: [...this.fallenDefenders],
      roundLeft: this.roundLeft,
      enraged: this._enraged,
      specialCast: this.specialCast,
      pendingSpecial: this.pendingSpecial ? { ...this.pendingSpecial } : null,
      bossFreezeMs: this.bossFreezeMs,
      bossFreezeLockMs: this.bossFreezeLockMs,
      summonQueue: [...this.summonQueue],
      dripLeft: this.dripLeft,
      activeTarget: this.activeTarget,
      spawnSeq: this.spawnSeq,
      activatedKeys: [...this.activatedKeys],
      signResolved: [...this.signResolved],
      signPending: this.signPending,
      swapTimerMs: this.swapTimerMs,
      trapezeTimerMs: this.trapezeTimerMs,
      convertTimerMs: this.convertTimerMs,
      fireTimerMs: this.fireTimerMs,
      hammerTimerMs: this.hammerTimerMs,
      bozoIds: [...this.bozoIds],
      ninjaDown: this.ninjaDown,
      duelGroundX: this.duelGroundX,
      ninjaRetreated: this.ninjaRetreated,
      smokeSeq: this.smokeSeq,
      bubbleIndex: this.bubbleIndex,
      bubbleCastMs: this.bubbleCastMs,
      bubbleGapMs: this.bubbleGapMs,
      cancels: this.cancels,
      bubbleActivation: this.bubbleActivation,
      bubbleCancelledSlot: this.bubbleCancelledSlot,
      lastCancelActivation: this.lastCancelActivation,
      grabbers: this.grabbers.map((g) => ({ ...g })),
      grabberTimer: this.grabberTimer,
      grabSeq: this.grabSeq,
      crabs: this.crabs.map((c) => ({ ...c })),
      crabTimer: this.crabTimer,
      crabSeq: this.crabSeq,
      megaBot: this.megaBot ? { ...this.megaBot } : null,
      endlessMechanicTimers: { ...this.endlessMechanicTimers },
      endlessMechanicCount: this.endlessMechanicCount,
    };
  }

  restore(snapshot: BattleSimSnapshot): void {
    this.units.splice(0, this.units.length, ...snapshot.units.map((u) => ({
      ...u,
      abilities: [...u.abilities],
      teamAuraStats: u.teamAuraStats ? { ...u.teamAuraStats } : null,
      attackMultiplier: u.attackMultiplier ?? Math.max(0.1, u.power ? u.damage / u.power : 1),
      walkingSpeedMult: u.walkingSpeedMult ?? 1,
      damageFxTaken: u.damageFxTaken ?? 0,
      healCastSeq: u.healCastSeq ?? 0,
      healAoeTimerMs: u.healAoeTimerMs ??
        (u.abilities.includes("healAOE") ? HEAL_AOE_MS : 0),
      laserTimerMs: u.laserTimerMs ?? laserInterval(u.abilities, u.cooldownMs),
      laserFxSeq: u.laserFxSeq ?? 0,
      laserTargetId: u.laserTargetId ?? null,
      walkingThisTick: u.walkingThisTick ?? false,
      abilityRollSeq: u.abilityRollSeq ?? 0,
      blockMs: u.blockMs ?? 0,
      blastAirMs: u.blastAirMs ?? 0,
      blastAirTotalMs: u.blastAirTotalMs ?? 0,
      blastAirHeight: u.blastAirHeight ?? 0,
      blastSpin: u.blastSpin ?? 0,
      usedAbilities: [...(u.usedAbilities ?? [])],
      resurrectUsed: u.resurrectUsed ?? false,
      unwrapUsed: u.unwrapUsed ?? false,
      unwrapFxSeq: u.unwrapFxSeq ?? 0,
      lastLaughFxSeq: u.lastLaughFxSeq ?? 0,
      shield: u.shield ?? 0,
      phaseUsed: u.phaseUsed ?? false,
      phaseMs: u.phaseMs ?? 0,
      phaseFxSeq: u.phaseFxSeq ?? 0,
      teleportPending: u.teleportPending ?? false,
      teleportFxSeq: u.teleportFxSeq ?? 0,
      power: u.power ?? u.damage,
      // An old checkpoint parked at the 1-HP floor has necessarily consumed
      // its protection. New checkpoints persist the explicit latch.
      oneShotProtectionUsed: u.oneShotProtectionUsed ?? (u.team === "player" && u.hp <= 1),
      frontPriority: u.frontPriority ?? false,
      inLine: u.inLine ?? false,
      knockBackToX: u.knockBackToX ?? 0,
      knockBackSpeed: u.knockBackSpeed ?? 0,
      passedBlockers: [...(u.passedBlockers ?? [])],
      chargeCfg: u.chargeCfg ?? null,
      stunResist: u.stunResist ?? 0,
      chargeTapScale: u.chargeTapScale ?? 1,
      stoneMs: u.stoneMs ?? 0,
      gazeReady: u.gazeReady ?? false,
      chargeMs: u.chargeMs ?? 0,
      poise: u.poise ?? 0,
      chargeRestMs: u.chargeRestMs ?? 0,
      chargeFrac: u.chargeFrac ?? 0,
      chargeBreakSeq: u.chargeBreakSeq ?? 0,
      chargeSlamSeq: u.chargeSlamSeq ?? 0,
      staggerMs: u.staggerMs ?? 0,
      chargeLockMs: u.chargeLockMs ?? 0,
      dotMs: u.dotMs ?? 0,
      dotPerMs: u.dotPerMs ?? 0,
      magicCfg: u.magicCfg ?? null,
      magicCdMs: u.magicCdMs ?? 0,
      magicCastMs: u.magicCastMs ?? 0,
      magicKind: u.magicKind ?? 0,
      magicCount: u.magicCount ?? 0,
      magicSweepMs: u.magicSweepMs ?? 0,
      magicHit: [...(u.magicHit ?? [])],
      magicSeq: u.magicSeq ?? 0,
      isSummon: u.isSummon ?? false,
      // A checkpoint written before the split cannot reach here — the session handshake
      // rejects its ruleset — so this is the same belt-and-braces default as isTurned
      // below: a restored fight in which nothing is standing in the lane.
      isBlocker: u.isBlocker ?? false,
      stationX: u.stationX ?? null,
      stationY: u.stationY ?? null,
      deployAtMs: u.deployAtMs ?? null,
      deployAtWaveFrac: u.deployAtWaveFrac ?? null,
      waveBody: u.waveBody ?? false,
    deployWithBoss: u.deployWithBoss ?? false,
      defenseRole: u.defenseRole ?? null,
      anchorsLine: u.anchorsLine ?? true,
      stackBaseHp: u.stackBaseHp ?? 0,
      stackMax: u.stackMax ?? 1,
      stackTimerMs: u.stackTimerMs ?? 0,
      stackGrowMs: u.stackGrowMs ?? 0,
      stackCeiling: u.stackCeiling ?? 1,
      stackSeen: u.stackSeen ?? 1,
      stackToppleSeq: u.stackToppleSeq ?? 0,
      swapped: u.swapped ?? false,
      isBozoStack: u.isBozoStack ?? false,
      burnWalk: u.burnWalk ?? false,
      isBubbleRobot: u.isBubbleRobot ?? false,
      // A checkpoint from before the conversion / burn can only exist on a ruleset the
      // session handshake already rejects, so these defaults are belt-and-braces: they
      // restore a fight in which nobody is on fire and nobody has been turned, which is
      // exactly what such a snapshot described.
      isTurned: u.isTurned ?? false,
      isFlanker: u.isFlanker ?? false,
      smokeWindupMs: u.smokeWindupMs ?? 0,
      flankMs: u.flankMs ?? 0,
      turnedFromId: u.turnedFromId ?? null,
      burnMs: u.burnMs ?? 0,
      burnDir: u.burnDir ?? 1,
      burnAnchorX: u.burnAnchorX ?? u.x,
      knockBackChance: u.knockBackChance ?? (u.knockBack ? 1 : 0),
      stunChance: u.stunChance ?? (u.stunInflictMs > 0 ? 1 : 0),
      curseStunChance: u.curseStunChance ?? 0,
      curseStunMs: u.curseStunMs ?? 0,
      curseShoveChance: u.curseShoveChance ?? 0,
      mirrorsOpponentSpeed: u.mirrorsOpponentSpeed ?? false,
      mirrorPace: u.mirrorPace ?? 1,
      loaned: !!u.loaned,
      healMult: u.healMult ?? 1,
    })));
    this.players = this.units.filter((u) => u.team === "player");
    this.enemies = this.units.filter((u) => u.team === "enemy");
    this.boss = snapshot.bossId ? this.units.find((u) => u.id === snapshot.bossId) ?? null : null;
    this.projectiles.splice(0, this.projectiles.length, ...snapshot.projectiles.map((p) => ({ ...p })));
    this.actionCd = snapshot.actionCd ?? 0;
    this.nextAction = snapshot.nextAction ? { ...snapshot.nextAction } : null;
    this.actionCount = snapshot.actionCount ?? 0;
    this.throwCount = snapshot.throwCount;
    this.releaseSeq = snapshot.releaseSeq;
    this.projSeq = snapshot.projSeq;
    this.elapsed = snapshot.elapsed;
    this.emergeCooldown = snapshot.emergeCooldown;
    this.attacksLanded = snapshot.attacksLanded;
    this.playerDamage = snapshot.playerDamage;
    this.feats = {
      abilityKills: (snapshot.feats?.abilityKills ?? []).map((kill) => ({ ...kill })),
      resurrections: (snapshot.feats?.resurrections ?? []).map((rez) => ({ ...rez })),
    };
    // A snapshot with no explicit backlog is reconstructed from the units themselves: every
    // player zombie already down is a corpse Resurrect could still claim. Deployment order
    // is the best available stand-in for the order they fell in.
    this.fallen = snapshot.fallen
      ? [...snapshot.fallen]
      : this.players.filter((p) => !p.alive && !p.taken).map((p) => p.id);
    this.fallenDefenders = [...(snapshot.fallenDefenders ?? [])];
    this.roundLeft = snapshot.roundLeft;
    this._enraged = snapshot.enraged;
    this.specialCast = snapshot.specialCast;
    this.pendingSpecial = snapshot.pendingSpecial ? { ...snapshot.pendingSpecial } : null;
    this.bossFreezeMs = snapshot.bossFreezeMs ?? 0;
    this.bossFreezeLockMs = snapshot.bossFreezeLockMs ?? 0;
    // A checkpoint that predates the abductee queue restores the ctor's seed order, which
    // is the same thing a fresh sim would hold — such a snapshot can only exist on a
    // ruleset the session handshake already rejects, so it never reaches a live fight.
    this.summonQueue = snapshot.summonQueue
      ? [...snapshot.summonQueue]
      : this.summonCfg?.queue.map((u) => u.sourceKey) ?? [];
    this.dripLeft = snapshot.dripLeft ?? this.cadence.dripMs;
    this.activeTarget = snapshot.activeTarget ?? 1;
    this.spawnSeq = snapshot.spawnSeq;
    this.activatedKeys.splice(0, this.activatedKeys.length, ...snapshot.activatedKeys);
    // Purely derived, so it is not in the snapshot — re-derive it from the keys that are.
    this.activatedGroups.splice(0, this.activatedGroups.length, ...activatedGroupsOf(this.activatedKeys));
    this.signResolved = [...(snapshot.signResolved ?? [])];
    this.signPending = snapshot.signPending ?? null;
    this.swapTimerMs = snapshot.swapTimerMs ?? 0;
    this.trapezeTimerMs = snapshot.trapezeTimerMs ?? 0;
    this.convertTimerMs = snapshot.convertTimerMs ?? 0;
    this.fireTimerMs = snapshot.fireTimerMs ?? 0;
    this.hammerTimerMs = snapshot.hammerTimerMs ?? 0;
    this.bozoIds = [...(snapshot.bozoIds ?? [])];
    this.ninjaDown = snapshot.ninjaDown ?? false;
    this.duelGroundX = snapshot.duelGroundX ?? 0;
    this.ninjaRetreated = snapshot.ninjaRetreated ?? false;
    this.smokeSeq = snapshot.smokeSeq ?? 0;
    this.bubbleIndex = snapshot.bubbleIndex ?? 0;
    this.bubbleCastMs = snapshot.bubbleCastMs ?? 0;
    this.bubbleGapMs = snapshot.bubbleGapMs ?? this.bubbleCfg?.gapMs ?? 0;
    this.cancels = snapshot.cancels ?? this.bubbleCfg?.cancels ?? 0;
    this.bubbleActivation = snapshot.bubbleActivation ?? 0;
    this.bubbleCancelledSlot = snapshot.bubbleCancelledSlot ?? null;
    this.lastCancelActivation = snapshot.lastCancelActivation ?? -2;
    this.grabbers.splice(
      0,
      this.grabbers.length,
      ...(snapshot.grabbers ?? []).map((g) => ({
        ...g,
        swingStartDeg: g.swingStartDeg ?? g.rot,
        contactDeg: g.contactDeg ?? GRABBER_CONTACT_DEG,
        swingTotalMs: g.swingTotalMs ?? Math.max(1, g.pauseMs),
        targetId: g.targetId ?? null,
        swingMs: g.swingMs ?? 0,
      }))
    );
    this.grabberTimer = snapshot.grabberTimer ?? this.grabberTimer;
    this.grabSeq = snapshot.grabSeq ?? this.grabSeq;
    // Crab fields are absent from server-built snapshots (the verifier omits the hazard),
    // in which case the local crab state simply carries on unchanged.
    this.crabs.splice(0, this.crabs.length, ...(snapshot.crabs ?? []).map((c) => ({ ...c })));
    this.crabTimer = snapshot.crabTimer ?? this.crabTimer;
    this.crabSeq = snapshot.crabSeq ?? this.crabSeq;
    // Absent (a server-built snapshot) → the local robot carries on unchanged.
    if (snapshot.megaBot && this.megaBot) this.megaBot = { ...snapshot.megaBot };
    this.endlessMechanicTimers = { ...(snapshot.endlessMechanicTimers ?? {}) };
    this.endlessMechanicCount = snapshot.endlessMechanicCount ?? 0;
    // Derived from the resolved picks, so re-derived rather than restored.
    this.refreshRulings();
  }

  // ---- activated abilities (player-triggered from the battle strip) ----

  private isLarge(p: SimUnit): boolean {
    return p.group === "Large" || /^ZombieActorLarge/i.test(p.sourceKey);
  }

  private isSmall(p: SimUnit): boolean {
    return p.group === "Small" || /^ZombieActorSmall/i.test(p.sourceKey);
  }

  private isHealer(p: SimUnit): boolean {
    return p.abilities.includes("heal") || p.abilities.includes("healAOE");
  }

  /** Is this healer's cast HELD this instant — i.e. is it busy swinging?
   *
   *  The holder is whoever carries the ability, not the Garden body — the same move
   *  `canResurrect` made in v51. `isHealer` used to demand `p.isGarden`, which was a fact
   *  about which ladder shipped heals, not a rule about bodies; with the Forest Zombie
   *  carrying `heal` and Old McZombie carrying `healAOE` (docs/ABILITY_IDEAS.md) that gate
   *  would have made both abilities silently do nothing.
   *
   *  What replaces it is a rule about WORK, not about species: a healer heals in the gaps
   *  between its swings and on its walk-in, never while it is actually fighting. "fight" is
   *  precisely that state on both sides — a zombie enters it on reaching its slot with an
   *  enemy in front (stepZombies) and an enemy/PvP defender enters it on `playerInRange`,
   *  so the rule is symmetric for an attacking army and a defending one.
   *
   *  THIS IS A NO-OP FOR EVERY GARDEN, which is the point — and the `isGarden` term is
   *  what makes that true rather than nearly true. `isGarden` is the SUPPORT flag (see
   *  CombatEngine `supportsFromRear`): a station-holder heals for a living, a line-fighter
   *  heals between swings. On the ATTACKING side the term is redundant, because a Garden
   *  pinned at GARDEN_STATION_X closes on nothing and so never enters "fight" anyway (the
   *  same fact `laserTarget` documents). It is load-bearing on the DEFENDING side: a PvP
   *  defender stands in a formation and the enemy loop flips it to "fight" the moment
   *  `playerInRange` finds an attacker, so without the term a defending Garden would stop
   *  healing mid-assault — a silent nerf to every formation defense already in the wild,
   *  which measurably moved the pvp.test.ts balance band when it was tried.
   *
   *  Do NOT rewrite this as `!this.targetEnemy(p)`. `targetEnemy` has no range cap — it
   *  returns the nearest living enemy at ANY distance — so it answers "yes, there is a
   *  target" for a Garden parked at x=250 and would stop every healer in the game. */
  private healSuppressed(p: SimUnit): boolean {
    // An attacking Garden now fights back against an enemy on top of it (ruleset 83,
    // owner 2026-11-10), and while it does it holds its heals like any line healer. A
    // DEFENDING Garden keeps the old exemption, for the reason above.
    return p.state === "fight" && (!p.isGarden || p.team === "player");
  }

  /** An enemy close enough to hit this Garden zombie where it stands: a smoke-bomb ninja
   *  landed on it, or anything else that reached the back. Null when none is in reach. */
  private gardenAttacker(p: SimUnit): SimUnit | null {
    let best: SimUnit | null = null;
    for (const e of this.enemies) {
      if (!e.alive || e.isWall || e.isTurned || (e.state !== "hold" && e.state !== "fight")) continue;
      const d = Math.abs(e.x - p.x);
      if (d <= this.engageDistance + 2 && (!best || d < Math.abs(best.x - p.x))) best = e;
    }
    return best;
  }

  /** Is another of this zombie's own side deployed AHEAD of it — walking in or fighting?
   *  The gate on a support zombie's laser (v50): a Garden never makes the approach the
   *  walking laser belongs to, so it fires from its station instead, but only while it
   *  has a line to shoot over. Alone on the field it is a healer with nobody to heal, not
   *  an artillery piece. `taken` zombies are off the field (see armyOrder). */
  private zombieAhead(p: SimUnit): boolean {
    return this.players.some((q) =>
      q !== p && q.alive && !q.taken &&
      (q.state === "advance" || q.state === "fight") && q.x > p.x
    );
  }

  /** Where an un-deployed zombie sits in the queue to go out. `promote()` releases the
   *  first "waiting" unit in roster order, so the roster index IS the deploy order — and
   *  whoever is already "charging" is ahead of every one of them. Only meaningful for a
   *  unit that has not deployed; the callers all filter for that first. */
  private deployRank(p: SimUnit): number {
    const i = this.players.indexOf(p);
    return p.state === "charging" ? i : this.players.length + i;
  }

  /** A Mini that has not deployed yet, and so is still available to be picked up.
   *  One that has been released is out on the field on its own feet — there is
   *  nothing left to mount.
   *
   *  Picked in DEPLOY ORDER (v37). Nothing ever re-enters the queue, so it is only
   *  ever drained from the front and deploy order and roster order coincide — this
   *  ranks the same mini the old `find` did. It is written this way so both halves of
   *  the pairing state the same rule, and so it stays true if anything ever does put a
   *  zombie back in line. The CARRIER half is the one that actually moved. */
  private availableMini(): SimUnit | null {
    let best: SimUnit | null = null;
    for (const p of this.players) {
      if (!p.alive || !this.isSmall(p) || p.buddyCarrierId) continue;
      if (p.state !== "waiting" && p.state !== "charging") continue;
      if (!best || this.deployRank(p) < this.deployRank(best)) best = p;
    }
    return best;
  }

  /** Mini Buddy's whole window, in one place because the button's look and the tap
   *  it accepts must agree exactly (they did not: see `readyToActivate`).
   *
   *  The move loads onto a Large ANY TIME BEFORE IT HAS DEPLOYED — still queued at
   *  the back ("waiting"), or out being deployed ("charging": the walk to the slot
   *  and the focus fill both). The window was narrowed for a while to the instant
   *  the Large stood in the charge slot, on the theory that a tap should only land
   *  on the zombie the player is looking at — but that made it a few seconds per
   *  fight, easy to miss outright, and a Large that deployed un-mounted had spent
   *  the army's one shot at the move. Deliberately reverted (v36): anywhere short
   *  of deployed, the mount is an order the pair carries out when the carrier goes. */
  private canTakeMini(p: SimUnit): boolean {
    return (
      p.alive && this.isLarge(p) && p.abilities.includes("attachMini") &&
      !p.buddyId && !p.usedAbilities.includes("attachMini") &&
      (p.state === "waiting" || p.state === "charging") && !!this.availableMini()
    );
  }

  /** A player unit is READY for an activated move when it's alive, in the thick of
   *  the fight, off cooldown, and not already charging one.
   *
   *  A SUICIDE move (Explode) reads "in the thick of the fight" as position alone —
   *  the same test the button's own display window uses — rather than demanding an
   *  enemy be standing there this instant. It is a fuse the player lights on their own
   *  timing: waiting for a target defeats the purpose, and `state` flips out of "fight"
   *  in every gap between one enemy dying and the next walking on, which made the one
   *  move you most want to pre-time the one move you could not. */
  private readyToActivate(p: SimUnit, key: string): boolean {
    if (p.usedAbilities.includes(key)) return false;
    // Overruled (raid 12): the move is off the table while the ruling stands. Here rather
    // than at the tap so the strip's button goes dark with it.
    if (this.rulingFx.overruled.has(key)) return false;
    // A benched zombie offers no button. Checked here rather than at the tap so the strip's
    // ready-count drops with it — a button that lights up and then refuses is worse than a
    // button that visibly goes away.
    if (this.isSigned(p)) return false;
    // Mini Buddy is the one move performed OFF the field, so it does not go through
    // the in-position test below at all — see `canTakeMini` for its window (any
    // time before the carrier has deployed).
    if (key === "attachMini") return this.canTakeMini(p);
    // Strictly a WIDENING for suicide moves: everything that could be lit before still
    // can, plus the standing-in-position-with-nothing-to-hit case.
    const engaged = p.state === "fight" ||
      (!!ACTIVATED_ABILITY[key]?.suicide && this.inAttackPosition(p));
    return (
      p.alive &&
      p.team === "player" &&
      p.abilities.includes(key) &&
      engaged &&
      !p.windupKey &&
      p.abilityCdMs <= 0
    );
  }

  /** A deployed zombie that has reached striking range — IN POSITION to attack,
   *  whether or not an enemy happens to be standing in front of it this instant.
   *
   *  This is the sim's own attack gate (see the advance step: `inCombatZone ||
   *  atBlockingWall`) with the enemy-arrived clause dropped. That clause is what
   *  flips `state` back to "advance" in every gap between one enemy dying and the
   *  next walking on, so a button driven off `state === "fight"` strobed on and off
   *  and left the player nothing steady to time a wind-up into. Position alone only
   *  moves forward, so it holds still. */
  private inAttackPosition(p: SimUnit): boolean {
    if (!p.alive || p.team !== "player") return false;
    if (p.state !== "advance" && p.state !== "fight") return false;
    const wall = this.wallInWay(p);
    if (wall) return Math.abs(wall.x - p.x) <= this.blockerGap(wall) + 2;
    return p.x >= this.frontX - COMBAT_ZONE_DEPTH;
  }

  /** Whether a move has any carrier inside its DISPLAY window — the span over which
   *  the battle strip keeps its button on screen. Wider than `readyToActivate`
   *  (which also demands off-cooldown and not-already-winding-up) precisely so the
   *  button stays put while its zombie charges and recharges.
   *
   *  Mini Buddy is the exception: its window is "an un-mounted Large short of
   *  deployment, with a Mini still behind it" — and it has no cooldown to wait out,
   *  so "on screen" and "a tap lands" are the same instant. Same predicate as
   *  `readyToActivate`, deliberately. */
  private abilityPresent(key: string): boolean {
    if (key === "attachMini") return this.players.some((p) => this.canTakeMini(p));
    return this.players.some(
      (p) => this.inAttackPosition(p) &&
        p.abilities.includes(key) && !p.usedAbilities.includes(key)
    );
  }

  /** Per activated move: how many zombies could perform it this instant (`ready`,
   *  the badge count) and whether the strip should be showing it at all
   *  (`present`). A present move with nothing ready is a button on cooldown. */
  activatedStatus(): { key: string; ready: number; present: boolean }[] {
    return this.activatedKeys.map((key) => ({
      key,
      ready: this.players.filter((p) => this.readyToActivate(p, key)).length,
      present: this.abilityPresent(key),
    }));
  }

  /** Which move a tap on a STACKED button fires right now (see ACTIVATED_STACKS).
   *
   *  Highest tier first: the group's keys are already in that order, so the answer is
   *  the first one with a ready carrier anywhere in the army. That deliberately makes
   *  the upgrade the move a tap spends — Explode Ver.2 is the only one of the pair that
   *  can touch a boss, so a rule that could leave it unreachable would cost the player
   *  a capability rather than a preference. The explode pair is now the ONLY stack, and
   *  that is exactly the reason: where the two tiers are a genuine trade rather than an
   *  upgrade (Bash/Smash), the choice belongs to the player and they get a button each.
   *
   *  Nothing about `activate` changes: this only decides WHICH key the tap sends, and
   *  the key it sends is one `activate` will accept, so the recorded transcript still
   *  names a concrete move and the server's replay is unaffected.
   *
   *  Falls back to the highest tier merely PRESENT (a recharging button keeps a stable
   *  face rather than flickering to its stackmate), then to the group's top key. */
  nextInGroup(group: string[]): string {
    for (const key of group) if (this.players.some((p) => this.readyToActivate(p, key))) return key;
    for (const key of group) if (this.abilityPresent(key)) return key;
    return group[0];
  }

  /** Per activated BUTTON, the strip's version of `activatedStatus`: the move a tap
   *  fires now (`key`), how many zombies could perform ANY move in the group (`ready`,
   *  the badge count), and whether the group has a carrier on screen (`present`).
   *
   *  `ready` counts ZOMBIES, not key-hits — a Silver Small carries both Explode and
   *  Explode Ver.2 but is one tap's worth of exploder, and summing per-key readiness
   *  would have advertised it as two. */
  activatedGroupStatus(): { keys: string[]; key: string; ready: number; present: boolean }[] {
    return this.activatedGroups.map((keys) => ({
      keys,
      key: this.nextInGroup(keys),
      ready: this.players.filter((p) => keys.some((k) => this.readyToActivate(p, k))).length,
      present: keys.some((k) => this.abilityPresent(k)),
    }));
  }

  /** Active deployed-holder count per team ability. Waiting, dead, grabbed, and
   *  carried zombies do not project team effects.
   *
   *  Resurrect is the one ability whose holders can run out while still standing there,
   *  so its count is REVIVES LEFT rather than holders present — a Garden zombie that has
   *  already spent its revive contributes an aura of nothing and should not read as if it
   *  still has one banked. At zero the icon drops off the strip entirely, which is the
   *  honest signal that the army's safety net is gone. */
  teamAbilityStatus(): { key: string; count: number }[] {
    const deployed = this.players.filter(
      (p) => p.alive && (p.state === "advance" || p.state === "fight")
    );
    return this.teamKeys.map((key) => ({
      key,
      count: key === "ressurect"
        ? this.resurrectsLeft()
        : deployed.filter((p) => p.abilities.includes(key)).length,
    }));
  }

  /** Totals behind the two top-HUD team bars.
   *
   *  NUMERATOR AND DENOMINATOR MUST COME FROM THE SAME UNITS. The scene used to divide the
   *  live HP sum by a constant captured from the roster `buildPlayerUnits` handed over, and
   *  that roster's con — so its maxHp — already carries the FULL team aura (chivalry / grace
   *  / fortitude), while `refreshTeamAuras` only pays the aura to zombies that have actually
   *  DEPLOYED. Before the first zombie marched in, every carrier's maxHp therefore sat below
   *  the number the bar divided by, and an army holding aura carriers opened the fight with a
   *  partly dark bar while every zombie in it was at full health. Summing maxHp here tracks
   *  the aura in lockstep. Dead units keep their maxHp, so a loss stays visible as a loss.
   *
   *  Walls and summons are left out of the ENEMY total: they are transient obstacles the boss
   *  conjures mid-fight, and adding their HP to a numerator whose denominator never heard of
   *  them pinned the bar at full for as long as one stood. Both keep their own on-field bars.
   *  The head COUNT still includes them — that is a tally of what is on the field. */
  teamTotals(): {
    playerHp: number; playerMax: number; playerAlive: number;
    enemyHp: number; enemyMax: number; enemyAlive: number;
  } {
    let playerHp = 0, playerMax = 0, playerAlive = 0;
    let enemyHp = 0, enemyMax = 0, enemyAlive = 0;
    for (const u of this.units) {
      // Totals count every unit, including a zombie still waiting to charge and an
      // enemy still queued off-screen.
      if (u.team === "player") {
        playerHp += Math.max(0, u.hp);
        playerMax += u.maxHp;
        if (u.alive) playerAlive++;
      } else {
        if (u.alive) enemyAlive++;
        if (u.isWall || u.isSummon) continue;
        enemyHp += Math.max(0, u.hp);
        enemyMax += u.maxHp;
      }
    }
    return {
      playerHp, playerMax: Math.max(1, playerMax), playerAlive,
      enemyHp, enemyMax: Math.max(1, enemyMax), enemyAlive,
    };
  }

  /** Recompute type auras from currently deployed carriers. Their source behavior
   *  adds percentages, so two holders contribute +20%, three +30%, and so on. */
  private refreshTeamAuras(): void {
    const counts = new Map(this.teamAbilityStatus().map(({ key, count }) => [key, count]));
    const chivalry = counts.get("chivalry") ?? 0;
    const grace = counts.get("grace") ?? 0;
    const protect = counts.get("protect") ?? 0;
    const fortitude = counts.get("tankHitPointsBuff") ?? 0;
    for (const p of this.players) {
      const stats = p.teamAuraStats;
      p.damageReduction = protectReduction(protect, p.abilities.includes("protect"));
      if (!stats) continue;
      const statCarriers = p.group === "Female" ? chivalry : p.group === "Regular" ? grace : 0;
      const lifeCarriers = statCarriers + (p.group === "Headless" ? fortitude : 0);
      const oldMaxHp = p.maxHp;
      const oldCooldown = p.cooldownMs;
      const str = stats.baseStr + stats.strPerCarrier * statCarriers;
      const dex = stats.baseDex + stats.dexPerCarrier * statCarriers;
      const con = stats.baseCon + stats.conPerCarrier * lifeCarriers;
      p.maxHp = Math.max(1, Math.round(deriveMaxHp(con)));
      // The dead stay at 0: a Fortitude carrier arriving used to hand every fallen Headless the
      // Life difference, which the army bar (teamTotals) then counted as ghost health. The
      // living keep at least 1: a carrier FALLING takes the bonus back, and that could leave a
      // zombie standing at 0 Life (alive, and fighting) until the next hit of any size.
      if (p.alive) p.hp = Math.max(1, Math.min(p.maxHp, p.hp + (p.maxHp - oldMaxHp)));
      p.power = str * POWER_PER_STR;
      p.damage = Math.max(1, Math.round(deriveHitDamage(p.power, p.attackMultiplier)));
      p.cooldownMs = deriveAttackIntervalMs(dex, "player");
      if (oldCooldown > 0 && p.timerMs > 0) p.timerMs *= p.cooldownMs / oldCooldown;
      p.moveSpeed = advanceSpeed(dex) * p.walkingSpeedMult;
    }
  }

  /** Which of two eligible zombies performs an activated move: the front-most, since it
   *  is nearest the enemy and already in the thick of it. There is no revived-exploder
   *  tiebreak to make — a revived zombie comes back with its one-use moves already spent
   *  (see `resurrect`), so it never re-enters this queue at all.
   *
   *  MINI BUDDY IS THE EXCEPTION (v37). It is the one move performed OFF the field, by a
   *  pair that has not deployed, and a waiting zombie's x is where it happens to be
   *  milling in the back group — `clusterHome` scatter plus a shuffle that re-rolls every
   *  few seconds. Ranking those by x hands the mount to an arbitrary Large that also
   *  changes with the clock. Take the carrier in the order it will DEPLOY instead: the
   *  brute going out next gets the mini going out next, which is the pairing the player
   *  is looking at when they tap. */
  private outranks(candidate: SimUnit, current: SimUnit, key: string): boolean {
    if (key === "attachMini") return this.deployRank(candidate) < this.deployRank(current);
    return candidate.x > current.x;
  }

  /** Trigger an activated move on ONE eligible zombie. Returns false if none is ready.
   *  Starts the wind-up; the payoff lands when it fills. */
  activate(key: string): boolean {
    if (this.finished) return false;
    const ab = ACTIVATED_ABILITY[key];
    if (!ab) return false;
    let pick: SimUnit | null = null;
    for (const p of this.players) {
      if (!this.readyToActivate(p, key)) continue;
      if (!pick || this.outranks(p, pick, key)) pick = p;
    }
    if (!pick) return false;
    if (key === "attachMini") {
      const mini = this.availableMini();
      if (!mini) return false;
      pick.buddyId = mini.id;
      mini.buddyCarrierId = pick.id;
      mini.buddyMountMs = MINI_MOUNT_MS;
      mini.state = "carried";
      mini.distracted = false;
      mini.awaitRelease = false;
      pick.usedAbilities.push(key);
      return true;
    }
    if (key === "block") {
      pick.blockMs = 1000;
      pick.abilityCdMs = ab.cooldownMs;
      return true;
    }
    pick.windupKey = key;
    const windup = Math.max(1, pick.cooldownMs * ab.speedMultiplier * ab.damageTiming);
    pick.windupMs = windup;
    pick.windupTotal = windup;
    pick.abilityCdMs = ab.cooldownMs;
    // A one-use move is spent when the player COMMITS it, not when it pays off. The
    // wind-up is cancellable — knockback, pixelFire, and the two client-only grabs all
    // clear `windupKey` — and Explode carries no cooldown to cover the gap, so marking
    // it at the payoff handed the move straight back every time its charge was
    // interrupted. On a hazard raid only the CLIENT interrupts, so only the client
    // re-armed, and the server refused the second tap as `illegal_ability`.
    if (ab.useOnce) pick.usedAbilities.push(key);
    return true;
  }

  /** Advance a charging zombie; on completion deliver the payoff blow. While it
   *  charges it makes no normal attacks (the wind-up is the trade-off) — the
   *  else-branch in the advance step is the only place `tryAttack` runs, so a unit
   *  holding a `windupKey` cannot land an ordinary swing at all.
   *
   *  `foe` is null when a suicide fuse burns down with nothing in front of the zombie.
   *  That is not an error case: the blast still goes off on schedule, and an area hit
   *  over an empty field simply damages nobody. Only a single-target payoff needs a
   *  target, and no suicide move has one. */
  private stepWindup(p: SimUnit, foe: SimUnit | null, dtMs: number) {
    p.windupMs -= dtMs;
    if (p.windupMs > 0) return;
    const key = p.windupKey!;
    const ab = ACTIVATED_ABILITY[key]!;
    const dmg = Math.max(1, Math.round(p.damage * ab.damageFactor));
    if (ab.aoe) {
      for (const e of this.enemies) {
        if (!e.alive || e.state === "queued" || e.state === "structure" || e.state === "descending") continue;
        // A converted pixel zombie is not a target for the army's damage, by blast any
        // more than by melee (see targetEnemy). It is one of YOUR zombies with a million
        // hit points, answerable only to taps; letting a blast chip it would put ability
        // kills and `playerDamage` against a unit the army is not supposed to be fighting.
        if (e.isTurned) continue;
        if (e.isBoss && !ab.hitBoss && (key === "explode" || key === "explodeV2")) continue;
        this.recordAbilityKill(key, e, () => this.dealDamage(e, dmg, true));
        if (ab.stunMs) this.stunEnemy(e, ab.stunMs, key, p);
        this.playerDamage += dmg;
      }
    } else if (foe) {
      this.recordAbilityKill(key, foe, () => this.dealDamage(foe, dmg, true));
      if (ab.stunMs) this.stunEnemy(foe, ab.stunMs, key, p);
      this.playerDamage += dmg;
    }
    p.struckThisTick = true;
    this.attacksLanded++;
    p.windupKey = null;
    p.windupMs = 0;
    // `useOnce` was already spent at activate() — a cancelled charge must not refund it.
    p.timerMs = this.cycleMs(p, null); // resume normal attacks after a beat
    // Explode is a SUICIDE move: the zombie goes up with the blast and is a casualty of
    // the raid. Killed AFTER the payoff so the blast it just delivered still counts, and
    // through `dealDamage` rather than around it, so a Garden holder's Resurrect gets its
    // shot at the exploder exactly as it would at any other casualty.
    if (ab.suicide) {
      p.explodeFxSeq++;
      this.dealDamage(p, p.hp, false);
    }
  }

  /** Run `deal` and note it if it was the blow that finished `target`.
   *
   *  Attribution is deliberately "was alive before, dead after" rather than anything
   *  the damage numbers imply: an area blast can land on an enemy already burning or
   *  mid-cascade, and only the transition actually identifies the killer. */
  private recordAbilityKill(key: string, target: SimUnit, deal: () => void): void {
    const wasAlive = target.alive;
    deal();
    if (wasAlive && !target.alive) {
      this.feats.abilityKills.push({ ability: key, boss: target.isBoss });
    }
  }

  /** What a Mini Buddy carrier is CHARGING AT: the nearest enemy that has actually come
   *  out and is standing on the field. Null when there is nothing to ram yet, in which
   *  case the carrier walks to its formation slot as usual and waits — it should not go
   *  and stand on the doorway a queued enemy has yet to walk through.
   *
   *  A blocker in the lane (a boss wall, an alien abductee) is a legitimate ram target;
   *  the caller clamps the destination to it anyway. A converted pixel zombie is NOT —
   *  `targetEnemy` refuses it, and this uses the same rule so the pair never charge a
   *  hazard the army is not supposed to be fighting. */
  private ramTargetFor(carrier: SimUnit): SimUnit | null {
    const foe = this.targetEnemy(carrier);
    if (!foe || (foe.state !== "hold" && foe.state !== "fight")) return null;
    return foe;
  }

  /** Dismount a Mini Buddy at the line. The shipped ram stuns the enemy for two
   *  seconds and the carrier for one; both zombies then remain in combat. */
  private deployMiniBuddy(carrier: SimUnit, foe: SimUnit | null) {
    if (!carrier.buddyId) return;
    const mini = this.players.find((p) => p.id === carrier.buddyId);
    carrier.buddyId = null;
    carrier.abilityCdMs = 0;
    carrier.stunMs = Math.max(carrier.stunMs, MINI_CARRIER_STUN_MS);
    if (foe) this.stunEnemy(foe, MINI_ENEMY_STUN_MS, "attachMini", carrier);
    if (!mini || !mini.alive) return;
    mini.buddyCarrierId = null;
    mini.buddyMountMs = 0;
    mini.x = carrier.x - 10;
    mini.y = carrier.y;
    mini.prevX = mini.x;
    mini.prevY = mini.y;
    mini.charge = 1;
    mini.formOrder = carrier.formOrder + 0.25;
    mini.inLine = carrier.inLine; // put down beside its carrier: in line if the carrier is
    mini.state = "advance";
    mini.timerMs = this.cycleMs(mini, null);
  }

  /** Deployed holders that still have their one revive banked — the count the battle
   *  strip shows the player. A holder that is dead, waiting at the back, or carried off
   *  projects nothing, exactly like every other team ability. */
  resurrectsLeft(): number {
    return this.players.filter((p) => this.canResurrect(p)).length;
  }

  /** GROUND TRUTH (`-[ZombieActorGarden canRez]` 0x7c745): the ability must be `active`
   *  and `unlocked`, which is the source game's way of spelling "carried and not yet
   *  spent" — `ressurectZombie:` sets `setConsumed:YES` / `setActive:NO` on tag 29 the
   *  moment it fires, so each holder revives exactly once per fight.
   *
   *  The holder is whoever CARRIES the ability, not the Garden body (v51): the source
   *  only ever handed Resurrect to Gardens, so `canRez` living on ZombieActorGarden was
   *  a fact about its ladder, not a rule about bodies. Since the Minis Proto Zombie and
   *  Zombug carry it at tier 3, a holder standing in the LINE polls the corpse backlog
   *  from there — same window (deployed, alive, unspent), same most-recent-corpse pick —
   *  and it stays a fighter: no support station, no deploy-last (CombatEngine's
   *  `supportsFromRear` is still Garden-only on purpose). */
  private canResurrect(p: SimUnit): boolean {
    return (
      p.alive && !p.taken &&
      (p.state === "advance" || p.state === "fight") &&
      p.abilities.includes("ressurect") && !p.resurrectUsed
    );
  }

  /** Poll Resurrect against the corpse backlog, the way `-[ZombieActorGarden fightUpdate:]`
   *  (0x7bf39) does: every holder in a position to cast checks `canRez` each frame rather
   *  than reacting to a death event. Two consequences the instant-on-death model missed —
   *  a holder deployed after a casualty still brings that casualty back, and the target is
   *  the MOST RECENT corpse at cast time (`ressurectZombie:` reads the last element of
   *  `defeatedZombies` and ignores its own argument), not whoever happened to die last tick.
   *
   *  Returns the holders that cast this step. The source game gives Resurrect and Heal ONE
   *  shared cast slot and checks `canRez` first (0x7c0a8, before the `canHeal` branch), so
   *  a holder that revives does not also heal on the same beat. */
  private stepResurrect(): Set<string> {
    const cast = new Set<string>();
    if (!this.fallen.length) return cast;
    for (const healer of this.players) {
      if (!this.fallen.length) break;
      if (!this.canResurrect(healer) || this.wallInWay(healer)) continue;
      if (this.isSigned(healer)) continue; // benched: it is walking away, not reviving
      const corpseId = this.fallen[this.fallen.length - 1];
      const corpse = this.players.find((p) => p.id === corpseId);
      if (!corpse) {
        this.fallen.pop(); // unreachable in practice; never let a bad id wedge the backlog
        continue;
      }
      this.resurrect(healer, corpse);
      cast.add(healer.id);
    }
    return cast;
  }

  /** A PvP DEFENDER's Resurrect: a living defending holder brings back the most recent
   *  fallen defender at full Life. It walks back in from the edge to its station (or
   *  Teleports there), with its one-use moves spent, exactly like a revived attacker. */
  private stepDefenderResurrect(): Set<string> {
    const cast = new Set<string>();
    if (!this.fallenDefenders.length) return cast;
    for (const healer of this.enemies) {
      if (!this.fallenDefenders.length) break;
      if (!healer.alive || healer.resurrectUsed || !healer.abilities.includes("ressurect")) continue;
      if (healer.state !== "hold" && healer.state !== "fight") continue;
      const corpseId = this.fallenDefenders.pop()!;
      const corpse = this.enemies.find((e) => e.id === corpseId);
      if (!corpse || corpse.alive) continue;
      healer.resurrectUsed = true;
      corpse.alive = true;
      corpse.hp = corpse.maxHp;
      corpse.state = "emerging";
      corpse.x = ENEMY_SPAWN_X;
      corpse.y = corpse.stationY ?? CENTER_Y;
      corpse.prevX = corpse.x;
      corpse.prevY = corpse.y;
      corpse.stunMs = 0;
      corpse.shield = 0;
      for (const key of corpse.abilities) {
        if (ACTIVATED_ABILITY[key]?.useOnce && !corpse.usedAbilities.includes(key)) corpse.usedAbilities.push(key);
      }
      if (corpse.abilities.includes("ressurect")) corpse.resurrectUsed = true;
      corpse.healFxSeq++;
      cast.add(healer.id);
    }
    return cast;
  }

  /** Authentic Garden support, now carried by whoever holds the ability. Heal selects
   *  the most injured OTHER deployed zombie with missing Life and restores 50% of the
   *  healer's Power. Heal All independently fires every 20 seconds for the same amount.
   *  An off-Garden holder is held back while it is swinging — see healSuppressed. */
  private stepHealing(dtMs: number, rezCast: ReadonlySet<string>, roster: SimUnit[] = this.players) {
    // Order in Court (raid 12): no healing lands on the army while the ruling stands.
    // Resurrect is stepped separately and is untouched — the ruling is about healing.
    if (roster === this.players && this.rulingFx.noHeal) return;
    const deployed = roster.filter(
      (p) => p.alive &&
        // "hold" is the enemy side's standing state; no player is ever in it, so this
        // is byte-identical for raids and for the attacking army.
        (p.state === "advance" || p.state === "fight" || p.state === "hold")
    );
    for (const healer of deployed) {
      if (!this.isHealer(healer)) continue;
      // Benched by the placard. This is the half of "no abilities" the walk-off branch
      // cannot cover: healing is stepped from here over the whole roster, not from the
      // unit's own march, so a sad Garden zombie would otherwise keep topping the line up
      // from the back — which is exactly the support the sign is supposed to remove.
      if (this.isSigned(healer)) continue;
      if (rezCast.has(healer.id)) continue; // spent this beat's cast on the revive
      // A lane blocker takes priority over Garden support work. Note that `wallInWay` no
      // longer counts a blocker a healer was never marching past (see there): at its
      // station a Garden zombie keeps healing straight through an abductee or a wall, and
      // this gate only trips if one ever ends up close enough to be fighting one.
      if (this.wallInWay(healer)) {
        healer.healTimerMs = Math.max(healer.healTimerMs, 250);
        continue;
      }
      const amount = Math.max(1, Math.round(healer.power * HEAL_POWER_MULT * healer.healMult));
      // A held cast is BANKED, not dropped: the timer still runs down, then parks at zero
      // until the first gap and fires the moment one opens. Resetting it instead would all
      // but silence a front-line carrier — Heal All is a flat 20-second timer, so it would
      // only ever land when its expiry happened to coincide with a gap. Parking at exactly
      // zero (rather than letting it run negative) keeps the held state a single value, so
      // a checkpoint taken mid-hold replays identically however long the hold ran.
      const held = this.healSuppressed(healer);

      if (healer.abilities.includes("heal")) {
        healer.healTimerMs -= dtMs;
        if (healer.healTimerMs <= 0 && held) healer.healTimerMs = 0;
        else if (healer.healTimerMs <= 0) {
          const candidates = deployed.filter(
            (p) => p.id !== healer.id && p.hp > 0 && p.hp < p.maxHp
          );
          if (candidates.length) {
            const target = candidates.reduce(
              (a, b) => b.hp / b.maxHp < a.hp / a.maxHp ? b : a
            );
            target.hp = Math.min(target.maxHp, target.hp + amount);
            target.healFxSeq++;
            healer.healCastSeq++;
            healer.healTimerMs = healer.cooldownMs;
          } else {
            healer.healTimerMs = 250;
          }
        }
      }

      if (healer.abilities.includes("healAOE")) {
        healer.healAoeTimerMs -= dtMs;
        if (healer.healAoeTimerMs <= 0 && held) healer.healAoeTimerMs = 0;
        else if (healer.healAoeTimerMs <= 0) {
          const damaged = deployed.filter((p) => p.hp > 0 && p.hp < p.maxHp);
          for (const target of damaged) {
            target.hp = Math.min(target.maxHp, target.hp + amount);
            target.healFxSeq++;
          }
          if (damaged.length) healer.healCastSeq++;
          healer.healAoeTimerMs += HEAL_AOE_MS;
        }
      }
    }
  }

  /** Nearest enemy a zombie can reach (on the ground, not queued/perched). */
  private targetEnemy(u: SimUnit): SimUnit | null {
    // A Ninja smoke bomb sends a basic enemy into the Garden line. Ordinary zombies
    // turn to intercept it before resuming the enemy wave.
    const flanker = this.enemies.find((e) => e.alive && e.isFlanker);
    if (flanker && !u.isGarden) return flanker;
    if (u.isGarden && u.team === "player") {
      const close = this.gardenAttacker(u);
      if (close) return close;
    }
    const wall = this.wallInWay(u);
    if (wall) return wall;
    let best: SimUnit | null = null;
    let bestD = Infinity;
    for (const e of this.enemies) {
      if (!e.alive || e.state === "queued" || e.state === "structure" || e.state === "descending" ||
          e.state === "falling" || e.state === "landing" || e.isWall || e.isTurned) continue;
      if (this.standsDown(e)) continue;
      const d = Math.abs(e.x - u.x);
      if (d < bestD) {
        bestD = d;
        best = e;
      }
    }
    return best;
  }

  /** A stationary blocker ahead of this zombie: a boss WALL, or an abductee beamed into
   *  the middle of the lane (see SUMMON_SPAWN_X / SUMMON_MELEE_GAP — both stand still
   *  mid-field rather than holding at the wave's doorway). The latch keeps zombies which
   *  were already beyond the spawn point from turning around to attack it.
   *
   *  Until the dual invasions the two could never be on the field together — only the Ninja
   *  and Robot bosses build walls and only the alien boss summons — and the code leaned on
   *  it twice: one shared latch for "I am past it", and a `.find()` that took whichever
   *  blocker happened to be EARLIER IN THE ARRAY rather than the nearer one. With two
   *  standing, array order is spawn order, so a zombie between a wall and an abductee could
   *  fix on the far one and walk through the near one. Both are fixed below: the nearest
   *  blocker ahead wins, and the latch is per blocker.
   *
   *  A converted PIXEL ZOMBIE is pointedly NOT one of these, even though it rides the same
   *  `isSummon` flag for spawning and budget. It is not a blocker and not a melee target
   *  (see targetEnemy): the army walks straight past it and ignores it. It has to be that
   *  way round. Its body is a million hit points, so a lane it barred would be barred for
   *  the whole fight and every conversion would be an automatic loss — measured, exactly
   *  that: with it blocking, a MAXED roster could not clear the Video Games invasion at
   *  all. Making it a target instead of a blocker is no better; the army would simply pour
   *  four minutes of damage into it. So it is a hazard rather than an enemy: it stands
   *  where it lands, swings at whatever files past, and answers only to taps. */
  /** The army's total ATTACK SPEED on the field, expressed as equivalent dex. The ninja's
   *  throw rate is a function of it (see dualInvasion.dexTaxedInterval).
   *
   *  Derived from each zombie's LIVE attack interval rather than from a stored dex, which
   *  is both what the sim actually has and the truer reading of "total attack speed": a
   *  zombie sped up by an ability is swinging faster, so it should cost more sky. The
   *  conversion is the player-side cadence rule inverted (interval = 2 s / dex). */
  private deployedDex(): number {
    let total = 0;
    for (const p of this.players) {
      if (!p.alive || p.taken) continue;
      if (p.state === "waiting" || p.state === "charging" || p.state === "dead") continue;
      if (p.cooldownMs > 0) total += (ATTACK_INTERVAL_SEC.player * 1000) / p.cooldownMs;
    }
    return total;
  }

  /** Stun an enemy — the ONE way the player's side does it, so the pirate captain's poise
   *  bar can intercept every source with the value that source is worth.
   *
   *  `source` is the ability key behind the stun (POISE_CONTRIBUTION). While he is winding
   *  up a charge the stun does NOT land: it goes into the bar instead, and filling the bar
   *  is what stops him. That swap is the whole mechanic — a stun that both froze him and
   *  filled the bar would be the off switch poise exists to remove. */
  private stunEnemy(foe: SimUnit, ms: number, source: string, by: SimUnit | null = null) {
    if (!foe.alive) return;
    // Immunity (raid 12): no stun lands, and none feeds a bar either.
    if (this.rulingFx.immune) return;
    // Endless: fully resistant is the same immunity, partly resistant shortens it below.
    const resisted = 1 - foe.stunResist;
    if (resisted <= 0) return;
    // The counter (raid 13, t5+): the ninja boss turns a stun round, doubled, onto the zombie
    // that threw it. Passive procs included — that is the tax on a stun army hitting him.
    const counter = this.duel?.counterStunMult ?? 0;
    if (counter > 0 && foe.isBoss && by && by.alive) {
      by.stunMs = Math.max(by.stunMs, ms * counter);
      by.struckThisTick = true;
      return;
    }
    if (foe.chargeMs > 0 && foe.chargeCfg?.interruptible) {
      // Video Games moves (ruleset 92): a stun mid-wind-up STOPS the move outright and then
      // lands as an ordinary stun. The next wind-up waits out the full rest.
      foe.chargeMs = 0;
      foe.chargeFrac = 0;
      foe.poise = 0;
      foe.chargeRestMs = foe.chargeCfg.recoveryMs;
      foe.chargeBreakSeq++;
    } else if (foe.chargeMs > 0) {
      const gain = poiseFor(source) * resisted;
      if (gain > 0) {
        const threshold = foe.chargeCfg?.poiseThreshold ?? POISE_THRESHOLD;
        foe.poise = Math.min(threshold, foe.poise + gain);
        if (foe.poise >= threshold) this.breakCharge(foe);
      }
      return;
    }
    foe.stunMs = Math.max(foe.stunMs, ms * resisted);
  }

  /** The pirate captain (raid 13), or null on every other fight. */
  private captain(): SimUnit | null {
    if (!this.duel) return null;
    return this.enemies.find((e) => !!e.chargeCfg) ?? null;
  }

  /** The captain has walked on and is still standing: the duel is on. */
  private captainOut(): boolean {
    const c = this.captain();
    return !!c && c.alive && c.state !== "queued";
  }

  /** Whether this enemy is standing down for the duel: an ordinary wave body while the
   *  captain is out. Never the captain, the boss, a wall or anything summoned. */
  private standsDown(e: SimUnit): boolean {
    if (!this.duel || e.chargeCfg || e.isBoss || e.isWall || e.isSummon || e.isTurned) return false;
    return this.captainOut();
  }

  /** The smoke bomb: every deployed zombie out on the lane is pushed back, clear of the
   *  doorway. Healers at the rear station and zombies still filing out of the queue are
   *  left where they are — this is room for a duel, not a rout. */
  private smokeBomb() {
    const push = this.duel?.smokePushX ?? 0;
    this.smokeSeq++;
    if (push <= 0) return;
    for (const p of this.players) {
      if (!p.alive || p.taken || (p.state !== "advance" && p.state !== "fight")) continue;
      if (p.x <= this.supportX + 0.5) continue;
      p.x = Math.max(this.supportX, p.x - push);
      p.prevX = p.x;
      p.vx = 0;
      p.inLine = false;
      p.state = "advance";
      p.windupKey = null;
      p.windupMs = 0;
    }
  }

  /** The smoke swap (raid 13, t9+): while the captain is out, he and the ninja trade places
   *  every `swapMs`. The ninja comes down to the captain's spot and fights; the captain goes
   *  up to the perch, where nothing can reach him and his charge waits. */
  private stepDuel(dtMs: number) {
    const cfg = this.duel;
    const boss = this.boss;
    if (!cfg || !boss) return;
    const cap = this.captain();
    const capOnDuty = !!cap && cap.alive && (cap.state === "hold" || cap.state === "fight" || cap.state === "structure");
    // The captain gone: the ninja does not stay down in his place.
    if (!capOnDuty) {
      if (this.ninjaDown) this.duelSwap(false);
      return;
    }
    if (!cfg.swapMs || this.ninjaRetreated || !boss.alive) return;
    if (this.swapTimerMs <= 0) this.swapTimerMs = cfg.swapMs;
    this.swapTimerMs -= dtMs;
    if (this.swapTimerMs > 0) return;
    this.swapTimerMs = cfg.swapMs;
    this.duelSwap(!this.ninjaDown);
  }

  /** Put the ninja on the ground (`down`) or back on his perch, and the captain in the
   *  other place. */
  private duelSwap(down: boolean) {
    const boss = this.boss;
    const cap = this.captain();
    if (!boss || down === this.ninjaDown) return;
    this.smokeSeq++;
    if (down) {
      if (!cap || !cap.alive) return;
      this.duelGroundX = cap.x;
      cap.state = "structure";
      cap.x = BOSS_STRUCT_X;
      cap.y = BOSS_STRUCT_Y;
      boss.state = "hold";
      boss.x = this.duelGroundX;
      boss.y = CENTER_Y;
      this.ninjaDown = true;
    } else {
      boss.state = "structure";
      boss.x = boss.stationX ?? BOSS_STRUCT_X;
      boss.y = boss.stationY ?? BOSS_STRUCT_Y;
      if (cap && cap.alive && cap.state === "structure") {
        cap.state = "hold";
        cap.x = this.duelGroundX || this.holdXOf(cap);
        cap.y = CENTER_Y;
      }
      this.ninjaDown = false;
    }
    for (const u of [boss, cap]) {
      if (!u) continue;
      u.prevX = u.x;
      u.prevY = u.y;
      u.vx = 0;
      u.vy = 0;
      u.timerMs = this.cycleMs(u, null);
    }
  }

  /** A filled bar: the wind-up is abandoned and he has to start again, after a rest. */
  private breakCharge(u: SimUnit) {
    u.chargeMs = 0;
    u.poise = 0;
    u.chargeFrac = 0;
    u.chargeRestMs = u.chargeCfg?.recoveryMs ?? 0;
    // A broken charge STAGGERS him: the window the duel is built around (raid 13).
    u.staggerMs = u.chargeCfg?.staggerMs ?? 0;
    u.chargeBreakSeq++;
  }

  /** Advance the pirate captain's slam charge by one tick. Named apart from `stepCharge`,
   *  which is the ZOMBIE side's focus bar and an unrelated thing that shares the word.
   *
   *  He only winds up while ENGAGED — a charge that ran while he was still walking in would
   *  land its slam on a line that had not met him yet, and the player would have had no
   *  window in which to answer it. */
  private stepSlamCharge(u: SimUnit, dtMs: number) {
    const cfg = u.chargeCfg;
    if (!cfg || !u.alive) return;
    if (u.staggerMs > 0) u.staggerMs = Math.max(0, u.staggerMs - dtMs);
    if (u.chargeLockMs > 0) u.chargeLockMs = Math.max(0, u.chargeLockMs - dtMs);
    if (u.chargeRestMs > 0) {
      u.chargeRestMs = Math.max(0, u.chargeRestMs - dtMs);
      return;
    }
    if (u.stunMs > 0) return; // an ordinary stun landed between charges: he is not winding up
    if (u.chargeMs <= 0) {
      if (u.state !== "fight" && u.state !== "hold") return;
      // A front-area move (the Video Games gout and shield slam, ruleset 92) waits for a zombie
      // to be in reach: an enemy standing ready with nobody in front of it would otherwise
      // spend its opening gout, or a slam, on empty ground.
      if (cfg.target === "front-area" &&
          this.frontAreaPlayers(u, this.engageDistance + DEATH_BLAST_REACH).length === 0) return;
      u.chargeMs = cfg.windupMs;
      u.poise = 0;
    }
    u.chargeMs = Math.max(0, u.chargeMs - dtMs);
    u.chargeFrac = cfg.windupMs > 0 ? 1 - u.chargeMs / cfg.windupMs : 0;
    // Iron will (raid 13, t10): the bar drains unless it keeps being filled, so the stuns
    // that break it have to land together.
    if (cfg.poiseDrainPerSec > 0 && u.poise > 0) {
      u.poise = Math.max(0, u.poise - (cfg.poiseDrainPerSec * dtMs) / 1000);
    }
    if (u.chargeMs > 0) return;
    if (cfg.target === "front-area") {
      // The Video Games gout and shield slam (ruleset 92): every deployed zombie within reach
      // of the front, the same reach the Volatile Remains blast uses (the front line and the
      // band behind it). A flat part, a share of each zombie's OWN hit points, a stun, and
      // a burn left behind, each optional (ChargeConfig).
      const reach = this.engageDistance + DEATH_BLAST_REACH;
      for (const p of this.frontAreaPlayers(u, reach)) {
        const dmg = cfg.damage * u.chargeTapScale + (cfg.burstPct ?? 0) * p.maxHp;
        if (dmg > 0) this.dealEnemyDamage(p, dmg);
        p.struckThisTick = true;
        if (!p.alive) continue;
        if (cfg.stunMs && !this.uninterruptible(p)) p.stunMs = Math.max(p.stunMs, cfg.stunMs);
        if (cfg.burnPct && cfg.burnMs) {
          // A fresh gout re-lights the burn rather than stacking a second one.
          p.dotMs = cfg.burnMs;
          p.dotPerMs = (cfg.burnPct * p.maxHp) / cfg.burnMs;
        }
      }
      u.chargeLockMs = cfg.lockoutMs ?? 0;
    } else if (cfg.target === "front-deployed") {
      const target = this.players
        .filter((p) => p.alive && !p.taken && this.onField(p))
        .sort((a, b) => b.x - a.x)[0];
      if (target) this.dealEnemyDamage(target, cfg.damage * u.chargeTapScale);
    } else {
      // Pirate's standard slam hits every deployed zombie; Endless bruisers can opt into
      // a telegraphed single-target hit to produce focused casualties instead of a wipe.
      for (const p of this.players) {
        if (!p.alive || p.taken) continue;
        if (!this.onField(p)) continue;
        this.dealEnemyDamage(p, cfg.damage);
      }
    }
    u.chargeFrac = 0;
    u.poise = 0;
    u.chargeTapScale = 1;
    u.chargeRestMs = cfg.recoveryMs;
    u.chargeSlamSeq++;
  }

  /** How tall a circus stack is FIGHTING at right now: how many of its own hit-point
   *  pools are still standing, capped by how far it has climbed. 1 for everything that is
   *  not a stack, so every caller can multiply by it unconditionally.
   *
   *  Derived rather than stored, which is what makes toppling free: damage lands on one
   *  pool and the height follows it down in the same tick, with nothing to keep in step. */
  stackHeight(u: SimUnit): number {
    if (u.stackBaseHp <= 0) return 1;
    return Math.max(1, Math.min(u.stackMax, Math.ceil(u.hp / u.stackBaseHp)));
  }

  /** Grow the towers, and record a topple when one has lost a level since last tick.
   *
   *  A stack only climbs while it is STANDING ON THE FIELD — a tower still queued at the
   *  doorway that grew on the clock would walk on at full height, which removes the whole
   *  race the mechanic is: the player is supposed to be able to reach it before it tops
   *  out. */
  private stepStacks(dtMs: number) {
    for (const e of this.enemies) {
      if (e.stackBaseHp <= 0) continue;
      const height = this.stackHeight(e);
      if (height < e.stackSeen) {
        e.stackToppleSeq++;
        // A bozo knocked off the stack is one of yours coming back (raid 14).
        if (e.isBozoStack) this.freeBozos(e, height);
      }
      e.stackSeen = height;
      if (!e.alive || e.state === "queued" || e.stackGrowMs <= 0) continue;
      if (e.stackMax >= e.stackCeiling) continue;
      e.stackTimerMs -= dtMs;
      if (e.stackTimerMs > 0) continue;
      e.stackTimerMs += e.stackGrowMs;
      e.stackMax++;
      // Another midget climbs on: the tower gains a whole pool, both in what it can lose
      // and in what it currently has. A stack the player has already knocked down to one
      // level therefore rebuilds from where it stands rather than from full.
      e.maxHp += e.stackBaseHp;
      e.hp += e.stackBaseHp;
      e.stackSeen = this.stackHeight(e);
    }
  }

  // ---------------------------------------------------------------------------
  // THE SAUCER'S BUBBLE (raid 15) — see dualInvasion.ts
  // ---------------------------------------------------------------------------

  /** What the saucer is charging right now — one action, or two under the t10 dual cast —
   *  and which of the pair has been cancelled. Null when nothing is up. The one read the
   *  scene, the pilot and `bubbleAction` all go through. */
  bubbleCast(): { actions: BubbleAction[]; cancelled: number | null } | null {
    const cfg = this.bubbleCfg;
    if (!cfg || !cfg.cycle.length || this.bubbleCastMs <= 0) return null;
    if (!this.boss || !this.boss.alive) return null;
    const n = cfg.dualCast ? 2 : 1;
    const actions: BubbleAction[] = [];
    for (let k = 0; k < n; k++) actions.push(cfg.cycle[(this.bubbleIndex + k) % cfg.cycle.length]);
    return { actions, cancelled: this.bubbleCancelledSlot };
  }

  /** The first action still coming, or null when nothing is up (or everything is cancelled). */
  bubbleAction(): BubbleAction | null {
    const cast = this.bubbleCast();
    if (!cast) return null;
    const i = cast.actions.findIndex((_, k) => k !== cast.cancelled);
    return i < 0 ? null : cast.actions[i];
  }

  /** How far the charge has filled, 0..1. Presentation only; 0 when nothing is charging. */
  bubbleProgress(): number {
    const cfg = this.bubbleCfg;
    if (!cfg || !this.bubbleCast() || cfg.castMs <= 0) return 0;
    return Math.max(0, Math.min(1, 1 - this.bubbleCastMs / cfg.castMs));
  }

  /** Cancels the player has left. */
  cancelsLeft(): number {
    return this.bubbleCfg ? this.cancels : 0;
  }

  /** Presentation: the giant bot stands at the back (raid 15, t5+). */
  bubbleGiantBot(): boolean {
    return !!this.bubbleCfg?.giantBot;
  }

  /** The t9 lockout is holding this activation: the one before it was cancelled. */
  cancelLocked(): boolean {
    const cfg = this.bubbleCfg;
    return !!cfg && cfg.lockout && this.lastCancelActivation === this.bubbleActivation - 1;
  }

  /** The charge the pirate captain is winding up, or null when nobody is (raid 13).
   *
   *  A PURE READ of state the sim already keeps on the unit, added because nothing public
   *  exposed it and so nothing outside the renderer could tell a wind-up was happening.
   *  That was not merely inconvenient: the harness pilot decides from public observers
   *  only, so a fight whose whole question is "which slams do you stop" was being measured
   *  by a player who could not see a slam coming — 63 slams against 3 broken charges, and
   *  every one of those three an accident of something being off cooldown at the time.
   *
   *  `poise` and `threshold` are both reported rather than a fraction, because the caller
   *  has to decide WHICH answer to spend and the answers are priced in absolute poise
   *  (dualInvasion.POISE_CONTRIBUTION: Smash is half a bar and comes back, the fuse is a
   *  whole one and costs a zombie). A fraction would throw away the arithmetic that makes
   *  that a decision.
   *
   *  Null while he is resting between charges, so a caller polling this sees exactly the
   *  window in which an interrupt does anything. */
  chargeStatus(): {
    id: string;
    windupMsLeft: number;
    windupTotalMs: number;
    poise: number;
    threshold: number;
  } | null {
    for (const e of this.enemies) {
      if (!e.chargeCfg || e.chargeCfg.interruptible || !e.alive || e.chargeMs <= 0) continue;
      return {
        id: e.id,
        windupMsLeft: e.chargeMs,
        windupTotalMs: e.chargeCfg.windupMs,
        poise: e.poise,
        threshold: e.chargeCfg.poiseThreshold ?? POISE_THRESHOLD,
      };
    }
    return null;
  }

  /** Whether this fight has a charging enemy AT ALL, wound up or resting.
   *
   *  Separate from `chargeStatus` because a pilot banking its interrupts needs to know
   *  the fight is one worth banking for BEFORE the first wind-up — holding Smash back on
   *  a raid that never charges is pure loss. */
  hasCharge(): boolean {
    return this.enemies.some((e) => !!e.chargeCfg && !e.chargeCfg.interruptible && e.alive);
  }

  /** Whether the charging enemy has actually WALKED ON (raid 13's captain arrives at the
   *  midpoint). A player holding their stuns for him has no reason to hold them before. */
  chargerOnField(): boolean {
    return this.enemies.some((e) => !!e.chargeCfg && !e.chargeCfg.interruptible && e.alive && e.state !== "queued");
  }

  /** Stop a cast that is charging. `slot` picks which of a dual cast (0 or 1); a single
   *  cast only has slot 0. Returns false — a REFUSAL the transcript records — when nothing
   *  is charging, the budget is spent, the lockout holds this activation, or that slot is
   *  not there to cancel.
   *
   *  A cancel stops the ACTION, not the clock: the saucer waits its ordinary gap and goes
   *  on to the next thing in the cycle. Under the dual cast one cancel stops one of the
   *  pair and the other still lands when the charge fills. */
  cancelCast(slot = 0): boolean {
    const cfg = this.bubbleCfg;
    if (!cfg || this.finished) return false;
    const cast = this.bubbleCast();
    if (!cast || this.cancels <= 0 || this.cancelLocked()) return false;
    if (!Number.isInteger(slot) || slot < 0 || slot >= cast.actions.length) return false;
    if (cast.cancelled !== null) return false; // one cancel per activation
    this.cancels--;
    this.lastCancelActivation = this.bubbleActivation;
    this.bubbleCancelSeq++;
    if (cast.actions.length > 1) {
      this.bubbleCancelledSlot = slot;
      return true;
    }
    this.endActivation(cfg);
    return true;
  }

  /** Close the activation on the table: the cycle moves past it and the quiet begins. */
  private endActivation(cfg: BubbleConfig) {
    this.bubbleCastMs = 0;
    this.bubbleIndex += cfg.dualCast ? 2 : 1;
    this.bubbleActivation++;
    this.bubbleCancelledSlot = null;
    this.bubbleGapMs = cfg.gapMs;
  }

  /** Run the bubble's clock: quiet, then a charge, then the thing happens.
   *
   *  Gated on a LIVE BOSS rather than on its perch, unlike every other boss action. The
   *  saucer never comes down — it is a sky perch — and a bubble is something it is
   *  thinking, not something it is standing up to do. */
  private stepBubble(dtMs: number) {
    const cfg = this.bubbleCfg;
    if (!cfg || !cfg.cycle.length) return;
    if (!this.boss || !this.boss.alive) return;
    if (this.bubbleGapMs > 0) {
      this.bubbleGapMs -= dtMs;
      if (this.bubbleGapMs <= 0) this.bubbleCastMs = cfg.castMs;
      return;
    }
    if (this.bubbleCastMs <= 0) { this.bubbleCastMs = cfg.castMs; return; }
    this.bubbleCastMs -= dtMs;
    if (this.bubbleCastMs > 0) return;
    const n = cfg.dualCast ? 2 : 1;
    for (let k = 0; k < n; k++) {
      if (k === this.bubbleCancelledSlot) continue;
      this.fireBubble(cfg, cfg.cycle[(this.bubbleIndex + k) % cfg.cycle.length]);
    }
    this.endActivation(cfg);
    this.bubbleFireSeq++;
  }

  /** What each cast does. Each one is deliberately modest — the fight's difficulty is in
   *  choosing which to eat, not in any single one being unanswerable. */
  private fireBubble(cfg: BubbleConfig, action: BubbleAction) {
    switch (action) {
      case "wall": {
        // The same blocker the boss specials drop, at the same place and with the same
        // "already past it" latch — see the `wall` case in runSpecial. It lands at
        // `supportX`, INSIDE the player's half, so it cuts reinforcements off rather than
        // barring the line that has already gone by.
        const wt = this.bubbleWall;
        if (!wt || this.enemies.some((e) => e.alive && e.isWall)) break;
        const wall = this.spawnEnemy(wt);
        wall.isWall = true;
        wall.isBlocker = true;
        wall.state = "hold";
        wall.x = this.supportX;
        wall.y = CENTER_Y;
        wall.prevX = wall.x;
        wall.prevY = wall.y;
        wall.vx = 0;
        wall.vy = 0;
        for (const p of this.players) {
          if (p.alive && p.x > wall.x + 0.5) p.passedBlockers.push(wall.id);
        }
        break;
      }
      case "aoe": {
        // Everything that has left the staging area, at once. Through `dealDamage` so the
        // one-shot floor still applies: this is meant to hurt an army, not delete one.
        // `onField`, not a hand-written state list: that one let a Mini riding a queued
        // Large ("carried") take the full blast before it ever deployed.
        for (const p of this.players) {
          if (!p.alive || p.taken || !this.onField(p)) continue;
          this.dealDamage(p, cfg.aoeDamage, false);
        }
        break;
      }
      case "robot": {
        // A JunkBot beamed down at the doorway. It walks on at once (its own `deployAtMs`,
        // like the farmer squad), and it is a real minion: it holds the saucer's wave open
        // until it is killed. Capped, because every one is hit points outside the settle
        // budget.
        const template = cfg.robot;
        if (!template) break;
        const alive = this.enemies.filter((e) => e.alive && e.isBubbleRobot).length;
        if (alive >= cfg.robotMaxAlive) break;
        const bot = this.spawnEnemy(template);
        bot.isBubbleRobot = true;
        bot.deployAtMs = this.elapsed;
        break;
      }
      case "stunAll": {
        // Nothing on its own. Everything when a wall is standing, or when the portal just
        // put half the army at the back — which is the overlap the design asked for.
        // Deployed zombies only. A queued zombie's stun never counts down (only the
        // deployed branch ticks it), so it used to walk on and serve the whole stun then.
        for (const p of this.players) {
          if (!p.alive || p.taken || !this.onField(p)) continue;
          p.stunMs = Math.max(p.stunMs, cfg.stunMs);
        }
        break;
      }
      case "portal": {
        // Half the deployed line, back to the staging slot. Taken from the FRONT, because
        // the front is what the player spent the fight building — and because sending the
        // back half backwards would do nothing at all.
        //
        // They keep their place in the queue (`inLine` goes, `formOrder` stays), so they
        // walk back up rather than re-charging: the cost is the walk, and the wall that is
        // now between them and the fight.
        const out = this.players
          .filter((p) => p.alive && !p.taken && (p.state === "advance" || p.state === "fight"))
          .sort((a, b) => b.x - a.x);
        const take = Math.floor(out.length * PORTAL_FRACTION);
        for (const p of out.slice(0, take)) {
          p.x = CHARGE_X;
          p.y = CENTER_Y;
          p.prevX = p.x;
          p.prevY = p.y;
          p.vx = 0;
          p.vy = 0;
          p.inLine = false;
          p.state = "advance";
          // Everything it had walked past is behind it again — including the wall this
          // action exists to make matter.
          p.passedBlockers.length = 0;
        }
        if (take > 0) this.portalSeq++;
        break;
      }
    }
  }

  /** Whether the rulings are running at all: a raid that has them, with its lawyer still on
   *  the perch. THEY COME DOWN WITH THE BOSS — boss actions are perch-gated, and this is the
   *  Lawyer boss's: once its wave is cleared and it climbs down to fight, the bubbles stop
   *  and every ruling lifts. That is the intended finale, the pressure lifting at exactly the
   *  moment the last thing standing is the lawyer. */
  private signRunning(): boolean {
    const cfg = this.signCfg;
    if (!cfg || !cfg.offers.length || cfg.dwellMs <= 0) return false;
    const boss = this.boss;
    return !!boss && boss.alive && boss.state === "structure";
  }

  /** Close every slot the clock has run past, taking the player's pick where they made
   *  one and the pinned auto-pick (both bubbles, under contempt) where they did not — then
   *  re-derive what is in force.
   *
   *  Driven off `elapsed` and NOT off the boss's perch: the offers keep turning over
   *  underneath a descended lawyer even though nothing is in force. A `while` rather than an
   *  `if` because nothing promises a step is shorter than a dwell. */
  private stepSign(): void {
    const cfg = this.signCfg;
    if (!cfg || !cfg.offers.length || cfg.dwellMs <= 0) return;
    const slot = Math.floor(this.elapsed / cfg.dwellMs);
    while (this.signResolved.length < slot) {
      this.signResolved.push(this.signPending ?? autoPickFor(cfg, this.signResolved.length));
      this.signPending = null;
    }
    this.refreshRulings();
  }

  /** The two bubbles on the table right now, or null when the rulings are not running.
   *  Presentation and input both read this, so there is one answer to "what is being
   *  asked" rather than one per caller. */
  signOffer(): SignOffer | null {
    const cfg = this.signCfg;
    if (!cfg || !this.signRunning()) return null;
    return signOfferAt(cfg, this.signResolved.length);
  }

  /** Which offer is on the table, or null when the rulings are not running. The number a
   *  `signPick` input has to carry, so the pick can only answer the question it was shown. */
  signOfferIndex(): number | null {
    return this.signOffer() ? this.signResolved.length : null;
  }

  /** Which bubble the player has committed to for the offer on the table, or null while
   *  they have not chosen. A pick is final — see `pickSign`. */
  signPick(): number | null {
    return this.signOffer() ? this.signPending : null;
  }

  /** Whether this fight has rulings at all (raid 12), whatever the lawyer is doing. */
  hasSign(): boolean {
    return !!this.signCfg && this.signCfg.offers.length > 0;
  }

  /** Ignoring this offer applies both bubbles (contempt, t7+). Presentation reads it. */
  signContempt(): boolean {
    return !!this.signCfg?.contempt;
  }

  /** Ms left to choose. Zero when nothing is being asked. */
  signChooseMsLeft(): number {
    const cfg = this.signCfg;
    if (!cfg || !this.signOffer()) return 0;
    return Math.max(0, cfg.dwellMs - (this.elapsed % cfg.dwellMs));
  }

  /** The same countdown as a fraction (1 just posted → 0 about to resolve), so the HUD
   *  draws the clock the sim is actually keeping rather than one of its own. */
  signChooseFrac(): number {
    const cfg = this.signCfg;
    if (!cfg || cfg.dwellMs <= 0) return 0;
    return Math.max(0, Math.min(1, this.signChooseMsLeft() / cfg.dwellMs));
  }

  /** Commit the player's choice. Returns false — a REFUSAL the transcript records — when
   *  there is nothing to choose, when the offer named is not the one on the table, or when
   *  this offer has already been answered.
   *
   *  NO TAKE-BACKS, on purpose. A changeable pick would be a dial the player spins to the
   *  last possible tick rather than a decision, and it would let one offer write an
   *  unbounded number of transcript entries. */
  pickSign(offer: number, option: number): boolean {
    if (!this.signOffer()) return false;
    if (!Number.isInteger(offer) || offer !== this.signResolved.length) return false;
    if (option !== 0 && option !== 1) return false;
    if (this.signPending !== null) return false;
    this.signPending = option;
    return true;
  }

  /** The rulings in force right now, deduplicated — a ruling in force twice (precedent, or
   *  contempt handing over both bubbles) REFRESHES rather than stacking. [] when nothing is.
   *
   *  What is in force during slot s is what RESOLVED at the end of slot s-1 (and s-2 under
   *  precedent), so slot 0 has nothing in force: the fight opens with the first two bubbles
   *  up and a free dwell to read them in. See the TIMING note in dualInvasion.ts. */
  activeRulings(): readonly Ruling[] {
    return this.rulings;
  }

  /** Re-derive `rulings` and the effects they add up to. Pure function of the resolved
   *  picks, the clock and the lawyer's perch, so it needs no snapshot slot of its own. */
  private refreshRulings(): void {
    const cfg = this.signCfg;
    const out: Ruling[] = [];
    if (cfg && this.signRunning()) {
      const slot = this.signResolved.length;
      for (let back = 1; back <= Math.max(1, cfg.inForce) && slot - back >= 0; back++) {
        const resolved = slot - back;
        for (const r of rulingsFor(signOfferAt(cfg, resolved), this.signResolved[resolved])) {
          if (!out.some((o) => rulingKey(o) === rulingKey(r))) out.push(r);
        }
      }
    }
    this.rulings = out;
    const severe = !!cfg?.severe;
    const has = (kind: string) => out.some((r) => r.kind === kind);
    this.rulingFx = {
      slow: has("slowed") ? (severe ? RULING_SLOW.severe : RULING_SLOW.normal) : 1,
      weaken: has("weakened") ? (severe ? RULING_WEAKEN.severe : RULING_WEAKEN.normal) : 1,
      embolden: has("emboldened") ? (severe ? RULING_EMBOLDEN.severe : RULING_EMBOLDEN.normal) : 1,
      immune: has("immunity"),
      noHeal: has("orderInCourt"),
      overruled: new Set(out.filter((r) => r.kind === "overruled")
        .flatMap((r) => OVERRULED_ABILITIES[r.ability ?? ""] ?? [])),
      barred: out.filter((r) => r.kind === "barred").map((r) => r.group!),
    };
  }

  /** The classes benched right now, or [] when nothing is. */
  signedGroups(): readonly string[] {
    return this.rulingFx.barred;
  }

  /** Whether this zombie is currently benched by a Barred ruling. Enemies never are. */
  private isSigned(u: SimUnit): boolean {
    if (u.team !== "player" || !u.group) return false;
    const groups = this.rulingFx.barred;
    return groups.length > 0 && groups.includes(u.group);
  }

  /** A benched zombie's walk-off: it gives up its place in the line and trudges back
   *  toward the staging slot.
   *
   *  It RETREATS rather than standing still, which is the difference between "this class
   *  is disabled" and "this class has left", and it is the whole read of the mechanic —
   *  the hole in the line is visible from across the field. Bounded at CHARGE_X so nobody
   *  walks off the map, and slow (SIGN_RETREAT_SPEED) so a five-second bench does not
   *  teleport the front rank to the back and cost more than it is meant to. */
  private walkOffSigned(u: SimUnit, dtMs: number) {
    u.inLine = false;
    u.walkingThisTick = true;
    const step = (SIGN_RETREAT_SPEED * dtMs) / 1000;
    u.x = Math.max(CHARGE_X, u.x - step);
    const dy = u.homeY - u.y;
    if (Math.abs(dy) > 1) u.y += Math.sign(dy) * Math.min(Math.abs(dy), step);
  }

  private wallInWay(u: SimUnit): SimUnit | null {
    // NEAREST blocker ahead, not the first one spawned: with two standing, the one behind
    // the other must not be what this zombie fixes on. Ties keep array order, so a single
    // blocker resolves exactly as it always did.
    let blocker: SimUnit | null = null;
    for (const e of this.enemies) {
      if (!e.alive || !e.isBlocker || u.x > e.x + 0.5) continue;
      if (u.passedBlockers.includes(e.id)) continue;
      if (!blocker || e.x < blocker.x) blocker = e;
    }
    if (!blocker) return null;
    // A blocker only intercepts a zombie that was going to WALK PAST it. A Garden zombie
    // holds at GARDEN_STATION_X, a fixed station far behind the line and far behind either
    // kind of blocker, so it never closes on one, is never in reach of one, and can never
    // break one — yet an abductee beamed into mid-lane still counted as "in its way" and
    // shut its healing and its revive off for as long as the abductee lived. That is the
    // whole raid, in the raid the player has the least business being short a healer in:
    // the alien boss re-summons the moment the last abductee dies. The healers just stood
    // there, out of reach of a fight they had been drafted into.
    //
    // The test is exactly the one the march already applies below (`destinationX`): a
    // blocker that does not move where this unit stops is not blocking it. Everything that
    // marches to the LINE still stops short and fights — a slot beyond the blocker fails
    // this test — so interception is unchanged for every zombie that walks into one. The
    // carrier of a Mini Buddy is always blocked: it rams the enemy line rather than its own
    // slot, and asking `ramTargetFor` here would recurse back through `targetEnemy`.
    //
    // Only a DEPLOYED zombie has a real slot — `armyOrder` places the advancing/fighting
    // block and nobody else — so one still waiting at the back is left exactly as it was
    // rather than being read off its staging position.
    const deployed = u.state === "advance" || u.state === "fight";
    if (deployed && !u.buddyId && u.slotX <= blocker.x - this.blockerGap(blocker)) return null;
    return blocker;
  }

  /** How close a zombie gets to a blocker before trading blows with it. */
  private blockerGap(e: SimUnit): number {
    return e.isWall ? WALL_MELEE_GAP : SUMMON_MELEE_GAP;
  }

  /** The FRONT-MOST player within an enemy's striking range — the single zombie
   *  nearest the enemy down the lane, NOT the whole front row. Enemies commit all
   *  their damage to this one target (a big/slow hit knocks it back or drops it
   *  rather than chipping the entire line), so losses are more focused. Among the
    *  front column (zombies sharing the lead x) the tiebreak picks the visually
    *  front-most unit (largest y), matching the renderer's depth order.
    *
    *  RANGE IS ASYMMETRIC ON PURPOSE, but not unboundedly so. Zombies attack from
    *  anywhere in the combat zone — a band COMBAT_ZONE_DEPTH deep — while an enemy strikes
    *  only what stands within `engageDistance` of it. That is what makes the front row (and
    *  the Headless zombies that fight for it) matter: the back rows deal damage without
    *  taking it.
    *
    *  What that must NOT become is an enemy WITH NO ONE TO HIT WHILE A STANDING ROW IS
    *  HITTING IT. The melee band empties in ways the zombies control: a knockback attack
    *  shoves its victim 0.9-2.7 melee gaps down the lane (see knockBackZombie) and
    *  re-slots it last; a Headless walking to its promotion slot RESERVES the front slot
    *  while the rest of the row STANDS a row-depth back, inside the combat zone, swinging
    *  every cycle. The enemy stood there with a null target, contractually blind
    *  ("enemies not attacking despite zombies being in front of them"). v36 answered the
    *  knockback case (the enemy disarmed ITSELF — its reach is unconditional); v40(b)
    *  answers the reserved-slot case: a LINE enemy with an empty melee range strikes the
    *  front-most FRONT-BAND zombie STANDING at its slot.
    *
    *  Three deliberate limits on the v40 half, each holding a measured regression out:
    *  - STANDING only: a line mid-walk (re-forming after a death, a burn, a conversion)
    *    stays untargetable exactly as it always was — waves must not get free hits on
    *    every re-form (+35% on the ordinary Video Games p* without it).
    *  - FRONT BAND only: the deep rows keep dealing damage without taking it — that
    *    asymmetry is the design, not the bug.
    *  - LINE enemies only (not turned / summoned / wall units): a turned pixel zombie or
    *    a beamed-in abductee stands MID-LANE, usually with an empty melee ring of its
    *    own, and the reach let it shred the army from behind the line all fight long. */
  private playerInRange(e: SimUnit): SimUnit | null {
    if (e.isFlanker) return this.backlineTarget();
    // A zombie mid-shove is not a melee target: `-[ZombieActor isInMeleeRange]` returns
    // false for the whole time `knockBackPoint` is live, and every melee set the fight
    // manager builds is filtered through it. Without this the shove is a pure penalty —
    // the victim cannot act, but is still stood inside the reach of the thing that hit it.
    const inMelee = this.frontMostPlayer(
      (p) => p.knockBackSpeed <= 0 && Math.abs(p.x - e.x) <= this.engageDistance
    );
    if (inMelee) return inMelee;
    // Reach-of-last-resort: a zombie in attack position, with no wall standing between
    // the two of them (that fight is the wall's, not this enemy's). A KNOCKBACK enemy
    // reaches any such zombie (v36 — whatever it shoved away, it can still answer);
    // every other enemy reaches only one STANDING at its slot (v40 — the reserved-slot
    // case), so a line mid-re-form walks in unpunished exactly as it always did.
    const standingFrontBand = (p: SimUnit) =>
      p.lineupIndex < BAND_SIZE &&
      Math.abs(p.slotX - p.x) <= 2 && Math.abs(p.slotY - p.y) <= 2;
    // The v40 reach belongs to enemies AT THE LINE — a turned pixel zombie or a beamed-in
    // abductee stands MID-LANE, often with no one in its own melee ring, and handing one
    // the standing reach let it shred the army from behind the line (measured: +35% on
    // the ordinary Video Games p* almost entirely from the turned unit).
    const onTheLine = !e.isTurned && !e.isSummon && !e.isWall;
    return this.frontMostPlayer((p) =>
      this.inAttackPosition(p) && !this.wallInWay(p) &&
      (e.knockBack || (onTheLine && standingFrontBand(p)))
    );
  }

  /** The front-most living, on-lane player satisfying `pick` (null if none). Ties on x
   *  break to the visually front-most (largest y), matching the renderer's depth order. */
  private frontMostPlayer(pick: (p: SimUnit) => boolean): SimUnit | null {
    let best: SimUnit | null = null;
    for (const p of this.players) {
      // Off the lane: seized by a trapeze, or carried out of the fight entirely (a crab's
      // passenger, a zombie Zedzox has turned). `taken` used to imply the `grabbed` state
      // — the crab was the only way to get it — so testing the state alone was enough.
      // `turnZombie` broke that: a converted zombie keeps whatever state it was in, so it
      // has to be excluded by the flag or the enemy team keeps aiming at a unit that is
      // not on the field.
      if (!p.alive || p.taken || p.state === "grabbed") continue;
      // Never a zombie still in the queue: melee, its stun and shove all aim through here.
      if (!this.onField(p)) continue;
      if (!pick(p)) continue;
      if (
        !best ||
        p.x > best.x + 0.5 || // more forward (nearer the enemy) wins
        (Math.abs(p.x - best.x) <= 0.5 && p.y > best.y)
      ) {
        best = p;
      }
    }
    return best;
  }

  /** Backline target for the Ninja smoke-bomb flank. Gardens are preferred; if the
   *  player brought no Garden zombies, the rear-most deployed zombie takes the hit. */
  private backlineTarget(): SimUnit | null {
    const deployed = this.players.filter((p) =>
      p.alive && !p.taken && this.onField(p) && p.state !== "grabbed"
    );
    const gardens = deployed.filter((p) => p.isGarden);
    const candidates = gardens.length ? gardens : deployed;
    return candidates.reduce<SimUnit | null>((rear, p) => !rear || p.x < rear.x ? p : rear, null);
  }

  /** Whom the boss aims at: the FARTHEST-BACK deployed zombie (min x), so lobbed
   *  throws arc over the frontline tanks and land on the support/healers massed
   *  behind them. "Deployed" = released from the focus bar (brain popped) and now
   *  advancing/fighting on the lane; zombies still waiting or charging are off-limits.
   *  Returns null when nothing is deployed — so the boss doesn't throw at an empty
   *  lane. The lead (see leadVelocity) is applied at launch. */
  private throwTarget(): SimUnit | null {
    const deployed = this.players.filter(
      (p) => p.alive && !p.taken && (p.state === "advance" || p.state === "fight")
    );
    if (!deployed.length) return null;
    return deployed.reduce((a, b) => (b.x < a.x ? b : a));
  }

  /** Whom the ALIEN LASER aims at — ANY zombie standing on the lane, picked at random.
   *
   *  GROUND TRUTH (`ZFFightMan shootBullet:from:` 0x5ea74): the saucer builds a fresh
   *  candidate array of zombies that are `isInMeleeRange` — which `-[ZombieActor
   *  isInMeleeRange]` resolves to `actorIsFighting` (state 11/12/13), plus a zombie
   *  parked at its destination in one of the listed states — OR are in state 10 / 31 /
   *  32 (the two states `damageIn:` also exempts from the lineup-depth penalty, i.e.
   *  mid special attack). It then picks ONE AT RANDOM:
   *      idx = (arc4random() % 100) / 100.0 * count
   *  and fires at that zombie's position. Empty candidate list -> no bullet at all.
   *
   *  DELIBERATE DIVERGENCE — the candidate list is every DEPLOYED zombie, not only the
   *  engaged ones. Design call: the saucer fires whenever the player has anything on the
   *  lane at all. Two reasons the recovered reading could not stay:
   *
   *   1. It could stall the raid outright. A Garden zombie holds at a fixed absolute x
   *      (GARDEN_STATION_X — itself a deliberate divergence, see there) and closes on
   *      nothing, so it is never `actorIsFighting`. An army of nothing but healers, or
   *      one whose last ordinary body has died, handed the saucer an empty list on EVERY
   *      cycle: it fired nothing, they had nothing hurt to heal, and the fight ran out
   *      the four-minute cap with neither side able to touch the other. Reported as the
   *      boss refusing to shoot the Gardens at the back.
   *   2. The engaged-only list also went empty for whole seconds at a time in ordinary
   *      fights — between waves, and while the front rank crossed the lane — and a boss
   *      that visibly stops shooting for no reason the player can see reads as broken
   *      rather than as faithful.
   *
   *  The source's own selection is UNCHANGED: one candidate at random, same roll, same
   *  salt. Only the list it draws from is wider. That does mean the healers are now in it
   *  — the thing this function was originally written to prevent — but the two are not
   *  the same shape at all. The old bug was `throwTarget()` here, which picks the
   *  REAR-MOST deployed zombie every single time: it is a lob aimed over the tanks, so
   *  every bolt in the fight landed on the support station and nowhere else. A random draw
   *  puts a healer's share of the fire on it and no more — one bolt in N with N deployed —
   *  which is pressure on the back line, not a guided missile at it. Do not "fix" this
   *  back to `throwTarget`.
   *
   *  Deployed = on the lane: advancing to its slot or fighting at it. A zombie still in
   *  the charge queue at the back is not on the field, and one carried off by a crab or
   *  turned into a pixel zombie (`taken`) is off it, so neither is a candidate. */
  private laserTarget(): SimUnit | null {
    const deployed = this.players.filter(
      (p) => p.alive && !p.taken && (p.state === "advance" || p.state === "fight")
    );
    if (!deployed.length) return null;
    return deployed[
      Math.floor(hash(this.actionCount * 13 + 7) * deployed.length) % deployed.length
    ];
  }

  /** The velocity a throw leads a target by: its MEASURED velocity (how it actually
   *  moved last step), CLAMPED to PREDICT_SPEED_CAP. So a slow/normal zombie is led by
   *  its true speed (and gets hit), while a fast one is led only as if it were "lowish
   *  speed" — the shot lands behind it and it outruns the throw. Zero when it's not
   *  moving (parked at its slot, fighting), so a stationary target is aimed at directly. */
  private leadVelocity(u: SimUnit): { vx: number; vy: number } {
    const spd = Math.hypot(u.vx, u.vy);
    if (spd < 1) return { vx: 0, vy: 0 };
    const k = Math.min(1, PREDICT_SPEED_CAP / spd);
    return { vx: u.vx * k, vy: u.vy * k };
  }

  /** Can this side still fight? A zombie carried off by a crab is still ALIVE (it returns
   *  after the raid) but is out of the battle, so it must not keep a lost fight running.
   *
   *  A converted PIXEL ZOMBIE is excluded for a different reason: its authored body is a
   *  million hit points (con 10000), so a win condition that had to kill it could never be
   *  met — the fight would run to the four-minute cap every time Zedzox landed one. It is
   *  a hazard standing on the field, not a member of the wave, and it dies to taps rather
   *  than to the army. Clearing the wave and the boss therefore still wins; a zombie still
   *  captive at that point comes home the same way a crab's passenger does.
   *
   *  A BLOCKER is excluded for the same reason, found the hard way. A boss's `wall` is not
   *  a member of the wave either — it is scenery the army pushes past and the player taps
   *  down — and a zombie only fights one that is AHEAD of it (`wallInWay`, and
   *  `passedBlockers` remembers the ones it has already gone around). So a wall the line
   *  has walked past is a wall nothing will ever attack again. While the win still required
   *  killing it, the result was a fight that could not end: measured on raid 13, every
   *  enemy including the boss dead at 120 s, one orphaned 1,800-point wall behind the line,
   *  and the army standing at attention until the four-minute cap turned a clean victory
   *  into `truncated_transcript` — no result, no reward, no explanation.
   *
   *  Latent before the dual invasions and reachable now: with the wave trickling one body
   *  at a time the line rarely advanced past a blocker, and the lined-up wave
   *  (dualInvasion.dualWaveCadence) pushes it past them constantly. */
  /** Is everything still standing on the army's side a station Garden with nothing left to
   *  do but heal? Waiting and carried-off zombies count as fighters (they will deploy or come
   *  home); one converted into a bozo does not, since only damage frees it. A Garden with a
   *  Resurrect banked while a corpse waits can still bring a fighter back, so it counts. */
  private healersOnly(): boolean {
    let standing = false;
    for (const p of this.players) {
      if (!p.alive || p.isTurned || this.bozoIds.includes(p.id)) continue;
      standing = true;
      if (!p.isGarden) return false;
      if (this.fallen.length && p.abilities.includes("ressurect") && !p.resurrectUsed) return false;
    }
    return standing;
  }

  private anyAlive(side: SimUnit[]): boolean {
    // A blocker sits outside the win condition (a wall, an abductee, the bozo stack) — except
    // a BOSS standing as one (raid 14's ringmaster), who still has to be beaten.
    return side.some((u) => u.alive && !u.taken && !u.isTurned && (!u.isBlocker || u.isBoss));
  }

  /** Replay-safe equivalent of `(arc4random() % 100)`. Multiplication by 37
   *  permutes all 100 integer results once per cycle, preserving the binary's
   *  exact 9/4/29 successful rolls without making replays nondeterministic. */
  private abilityRoll(u: SimUnit): number {
    const roll = (stringSeed(u.id) + u.abilityRollSeq * 37) % 100;
    u.abilityRollSeq++;
    return roll;
  }

  /** Fire the automatic walking laser. Both versions deal `laserHitDamage(finalPower)`
   *  — 20 % of Power, strength and nothing else (see combatStats); Ver.2 only schedules
   *  faster, at finalAttackSpeed/6 instead of /3. */
  private stepLaser(u: SimUnit, dtMs: number) {
    const interval = laserInterval(u.abilities, u.cooldownMs);
    if (interval <= 0) return;
    u.laserTimerMs -= dtMs;
    if (u.laserTimerMs > 0) return;
    const foe = this.targetEnemy(u);
    if (foe) {
      const mult = this.outgoingMult(u);
      const dmg = mult === 1 ? laserHitDamage(u.power) : Math.max(1, Math.round(laserHitDamage(u.power) * mult));
      this.dealDamage(foe, dmg, true);
      u.laserTargetId = foe.id;
      u.laserFxSeq++;
      u.struckThisTick = true;
      this.attacksLanded++;
      this.playerDamage += dmg;
    }
    u.laserTimerMs += interval;
  }

  /** The DEFENDER's walking laser — a PvP-only mirror of stepLaser, and a deliberate
   *  divergence from it.
   *
   *  An attacker's beam fires while the FIRER walks: it is the weapon of the approach, and
   *  it falls silent the moment its owner arrives and starts swinging. A defender never
   *  makes that approach — it is stood on an authored station waiting — so the same trigger
   *  would hand it a beam it could essentially never fire. The mirror is therefore taken on
   *  the OTHER side of the same moment: a defender fires while THEY are walking in, at
   *  whoever is still closing. Both readings cover exactly one phase of the fight, the
   *  approach, from the two ends of it.
   *
   *  Consequences worth naming:
   *   - it goes quiet once the line is engaged and nobody is walking, so it cannot grind a
   *     stalled fight down; a knocked-back attacker walking back in re-opens the window,
   *     exactly as it re-opens the attacker's own beam;
   *   - it targets the CLOSEST walker, which is the unit about to reach the line rather
   *     than a straggler still leaving the charge queue;
   *   - damage goes through `dealEnemyDamage`, so the victim's Protect reduction, Block
   *     roll and one-shot floor all apply, the same as any other blow it takes.
   *
   *  Raids cannot reach this: every authored raid enemy carries `abilities: []`, and PvP
   *  only lets a formation defense keep its abilities (see pvp.toEnemyCopy). */
  private stepDefenderLaser(u: SimUnit, dtMs: number) {
    const interval = laserInterval(u.abilities, u.cooldownMs);
    if (interval <= 0) return;
    u.laserTimerMs -= dtMs;
    if (u.laserTimerMs > 0) return;
    const foe = this.closestAdvancingPlayer(u);
    if (foe) {
      const mult = this.outgoingMult(u);
      this.dealEnemyDamage(foe, mult === 1 ? laserHitDamage(u.power) : Math.max(1, Math.round(laserHitDamage(u.power) * mult)));
      u.laserTargetId = foe.id;
      u.laserFxSeq++;
      u.struckThisTick = true;
      this.attacksLanded++;
    }
    u.laserTimerMs += interval;
  }

  /** The nearest zombie still walking in — a defender laser's target. `walkingThisTick` is
   *  set by the zombie walk step, which runs earlier in the same tick, so this reads the
   *  CURRENT tick's decision rather than the previous one's. */
  private closestAdvancingPlayer(u: SimUnit): SimUnit | null {
    let best: SimUnit | null = null;
    let bestD = Infinity;
    for (const p of this.players) {
      if (!p.alive || p.taken || p.isTurned || !p.walkingThisTick) continue;
      const d = Math.abs(p.x - u.x);
      if (d < bestD) {
        bestD = d;
        best = p;
      }
    }
    return best;
  }

  /** One attack cycle in ms for `u` while facing `foe` — ground truth
   *  `-[Actor getFightAttackSpeed]`. `cooldownMs` already carries the raw dex clock
   *  (2/dex zombie, 1/dex enemy) times the attack's `speedMultiplier`; on top of that:
   *   - a player zombie deeper than the front five swings slower (lineupSpeedBand);
   *   - a Scallywag throws its own clock away and mirrors its opponent's CURRENT cycle,
 *     and Arrrnold does the same against that opponent's SPECIES BASE cycle.
   *  Everything that re-arms an attack timer goes through here. */
  private cycleMs(u: SimUnit, foe: SimUnit | null): number {
    // Slowed (raid 12): the ruling stretches every zombie's attack interval.
    if (u.team === "player") {
      const cycle = u.cooldownMs * this.speedBand(u) * this.rulingFx.slow;
      return this.raging(u) ? cycle / RAGE_SPEED_MULT : cycle;
    }
    // Do or Die: every enemy at twice its dex, which is half its cycle.
    const haste = this.doOrDie ? DO_OR_DIE_HASTE : 1;
    // Endless primes a mirroring pirate against the zombie it is about to meet, so even its
    // first swing at a new arrival keeps the mirrored tempo rather than its own dex clock.
    // Invasions keep the shipped behaviour: the first swing runs on the unit's own clock.
    const mirrored = foe ?? (u.mirrorsOpponentSpeed && this.endlessMechanics ? this.frontDeployed() : null);
    if (u.mirrorsOpponentSpeed && mirrored && mirrored.team === "player") {
      const foeSec = (mirrored.cooldownMs * lineupSpeedBand(mirrored.lineupIndex)) / 1000;
      return (mirrorIntervalSec(u.sourceKey, foeSec, mirrored.speciesCycleMs / 1000) * 1000 * u.mirrorPace) / haste;
    }
    // A PvP defender's Rage (raid enemies carry no abilities, so this is 1 for every raid).
    return u.cooldownMs / haste / (this.raging(u) ? RAGE_SPEED_MULT : 1);
  }

  /** The line's slowdown and softening behind the front five, halved by Endless's Rearguard. */
  private speedBand(u: SimUnit): number {
    const band = lineupSpeedBand(u.lineupIndex);
    return this.endlessMechanics?.rearguard ? 1 + (band - 1) / 2 : band;
  }
  private damageBand(u: SimUnit): number {
    const band = lineupDamageBand(u.lineupIndex);
    return this.endlessMechanics?.rearguard ? 1 - (1 - band) / 2 : band;
  }

  /** The deployed zombie furthest forward: the one an arriving enemy meets first. */
  private frontDeployed(): SimUnit | null {
    let best: SimUnit | null = null;
    for (const p of this.players) {
      if (!p.alive || p.taken || p.state === "waiting" || p.state === "charging" || p.state === "dead") continue;
      if (!best || p.x > best.x) best = p;
    }
    return best;
  }

  /** Land a hit from `u` on `foe` when its clock is ready; else re-arm. An enemy
   *  hit can also knock the zombie back (to the back of the line) and/or stun it. */
  private tryAttack(u: SimUnit, foe: SimUnit, dtMs: number) {
    u.timerMs -= dtMs;
    if (u.timerMs > 0) return;
    u.timerMs += this.cycleMs(u, foe);
    // Player normal swings take the lineup-depth band (front five full, then 0.85/0.7/0.55);
    // enemies always hit at band 1.0. See combatStats.lineupDamageBand (ground truth).
    const dmg =
      u.team === "player"
        ? Math.max(1, Math.round(u.damage * this.damageBand(u) * this.outgoingMult(u)))
        // A circus stack hits for as many midgets as are still standing on each other's
        // shoulders. Multiplied here rather than baked into `damage`, because the height
        // changes every time the tower takes a pool's worth and the swing has to follow it
        // down within the same tick.
        //
        // Guarded on BEING a stack rather than relying on a height of 1, because an enemy's
        // `damage` is not an integer and rounding it unconditionally moves every other
        // raid: the first cut of this line changed a burn total by one point and the
        // pixelFire test caught it.
        : u.stackBaseHp > 0
          ? Math.max(1, Math.round(u.damage * this.stackHeight(u)))
          : u.damage;
    if (u.team === "enemy") {
      // A PvP defender's own damage abilities. Raid enemies carry none, so `mult` is exactly
      // 1 and the swing is untouched for every raid.
      const mult = this.outgoingMult(u);
      // A flanking ninja starts soft and ramps to full (endlessFlankDamageScale).
      const flank = u.isFlanker ? endlessFlankDamageScale(u.flankMs) : 1;
      this.dealEnemyDamage(foe, mult === 1 && flank === 1 ? dmg : Math.max(1, Math.round(dmg * mult * flank)));
      if (u.abilities.length) this.defenderSwingProcs(u, foe);
      // One Garden per smoke bomb (owner, 2026-11-11): the flanking ninja that drops a Garden
      // bombs straight back to the front, so a bomb costs at most one healer and a revive can
      // undo it rather than the ninja working down the whole backline.
      if (u.isFlanker && foe.isGarden && !foe.alive) this.endlessNinjaReturn(u);
    } else {
      this.dealDamage(foe, dmg, true);
      this.playerDamage += dmg;

      // Girl `damageIn:` uses integer rolls >.70 and >.95. Double Strike adds
      // the authored 0.25× Power strike; Random Stun holds the target for 1s.
      if (u.abilities.includes("doubleStrike") && this.abilityRoll(u) > 70 && foe.alive) {
        const bonus = Math.max(
          1,
          Math.round(u.power * 0.25 * this.damageBand(u) * this.outgoingMult(u))
        );
        this.dealDamage(foe, bonus, true);
        this.playerDamage += bonus;
        this.attacksLanded++;
      }
      if (u.abilities.includes("stun") && this.abilityRoll(u) > 95 && foe.alive) {
        this.stunEnemy(foe, 1000, "stun", u);
      }
      // Berserk: the swing costs its own Life. Straight through dealDamage, so nothing
      // softens it (not Protect, not Block, not the one-shot floor) and it can kill.
      if (u.abilities.includes("berserk")) this.dealDamage(u, this.berserkCost(u), false);
    }
    u.struckThisTick = true;
    this.attacksLanded++;
    // The ringmaster's whip stuns GARDEN zombies (raid 14) — the healer stack's tax. The lash
    // lands on the nearest zombie on his left (whipTarget); its CRACK stuns a Garden within
    // reach on that side — the one struck if it is one, else the nearest not already held.
    // Measured 2026-09-27: keyed on the struck zombie alone, Gardens spent 0-1.5 s a fight
    // stunned, because the nearest zombie on his left is almost never the healer at the back.
    if (this.bigTop && u === this.boss) {
      const garden = foe.alive && foe.isGarden ? foe : this.whipGarden(u);
      if (garden) garden.stunMs = Math.max(garden.stunMs, this.bigTop.whipGardenStunMs);
    }
    if (u.team === "enemy" && foe.alive && foe.team === "player") {
      // Enemy attack effects on the struck zombie — BOTH of which `-[Actor damageIn:]`
      // (0x37738) refuses while the victim's `fightData.canInterrupt` is NO. See
      // `uninterruptible`: only the bash and explode families ever set it.
      if (!this.uninterruptible(foe)) {
        // Which attack this swing WAS decides whether it carries an effect: the source
        // rolls one entry out of the unit's list per swing and applies that entry's
        // flags. One roll covers both effects, matching the single `rollAgainstFrequency`
        // the source makes — so the Lawyers boss's Double Punch is stun-and-shove or
        // neither, never half of one. See CombatEngine.attackEffects.
        const special = this.abilityRoll(u) < 100 * Math.max(u.knockBackChance, u.stunChance);
        if (special && u.stunInflictMs > 0 && u.stunChance > 0) {
          foe.stunMs = Math.max(foe.stunMs, u.stunInflictMs);
        }
        if (special && u.knockBack && u.knockBackChance > 0 && (!u.knockBackHeadlessOnly || foe.isHeadless)) this.knockBackZombie(foe);
        // Endless curses: rolled apart from the attack's own effects, so they only ever add.
        if (u.curseStunChance > 0 && this.abilityRoll(u) < 100 * u.curseStunChance) {
          foe.stunMs = Math.max(foe.stunMs, u.curseStunMs);
        }
        if (u.curseShoveChance > 0 && foe.isHeadless && this.abilityRoll(u) < 100 * u.curseShoveChance) {
          this.knockBackZombie(foe);
        }
      }
    }
  }

  /** Is this zombie mid-swing on a move that cannot be interrupted?
   *
   *  GROUND TRUTH: `-[Actor fightAttack:]` (0x36d28) reads `cantInterrupt` off the attack
   *  variation rolled for the swing and sets `fightData.canInterrupt = !cantInterrupt`;
   *  `-[Actor doneAttacking:]` (0x37cd8) restores YES when the swing ends. `damageIn:` then
   *  refuses both the stun and the knockback while it is NO.
   *
   *  Attacks.json carries `cantInterrupt` on EXACTLY four attacks — ZombieBash, ZombieBashV2,
   *  ZombieExplode, ZombieExplodeV2 — which are precisely this sim's wind-up moves. So it is
   *  super armour on the activated big hits and nothing else: pay for a Smash or light a
   *  fuse and no enemy shoves you out of it. (It is also why the depth-damage penalty exempts
   *  states 31/32 — the same two moves; see COMBAT_STATS_RECOVERED.md.) */
  private uninterruptible(p: SimUnit): boolean {
    return !!p.windupKey && !!ACTIVATED_ABILITY[p.windupKey]?.cantInterrupt;
  }

  /** Knock a zombie back. GROUND TRUTH — `-[Actor damageIn:]` 0x3777a rolls the shove and
   *  `-[Actor knockBackBy:force:]` 0x37e68 applies it:
   *
   *      [victim knockBackBy: -(50 + arc4random() % 100) force: 5.0]
   *
   *  `knockBackBy:force:` then, for a ZombieActor only:
   *    * `setZombieToLastIndex` — pull it out of the army array and re-insert it just
   *      BEFORE the first zombie still in the back group, i.e. at the tail of the DEPLOYED
   *      block. Not the tail of the roster: it stays ahead of everyone yet to deploy.
   *    * unschedule `damageIn:` / `fightAttack:` / `attackSFXIn:` — the swing in flight is
   *      cancelled outright, it does not resume on landing.
   *    * nudge x by -1 and set state 10 if it was in melee, breaking the position ==
   *      destination equality `isInMeleeRange` tests.
   *    * `reorderZombies`, and (ZombieActor override) recompute `destinationPoint` from the
   *      NEW index — which is why the shove costs depth: a deeper band means a slot further
   *      back to walk to, softer hits and a slower swing.
   *
   *  The shove itself is a SLIDE, not a teleport: `knockBackPoint` is parked at
   *  `(x + distance, y)` and `-[Actor movementUpdate:]` moves the zombie toward it at
   *  `force * 60` px/s, clearing the point on arrival (see stepKnockBack). */
  private knockBackZombie(p: SimUnit): boolean {
    // `damageIn:` gates BOTH the stun and the shove on `[fightData canInterrupt]` (0x37738)
    // and on `!invincible`. What writes `canInterrupt` was not pinned in this pass, so only
    // the narrowest reading is applied: a zombie already mid-shove is not shoved again.
    // Without it a fast knockback attacker re-parks the point every hit and its victim
    // never lands — which is a compounding buff the source's gate plainly exists to stop.
    if (p.knockBackSpeed > 0 || p.blastAirMs > 0) return false;
    // A shove sets "advance", so on a queued zombie it would force it onto the field.
    if (!this.onField(p)) return false;
    p.windupKey = null;
    p.windupMs = 0;
    // Replay-safe stand-in for `arc4random() % 100`: the victim's id and the current tick
    // are both part of the deterministic transcript, so client and verifier roll alike.
    const roll = Math.floor(hash(stringSeed(p.id) + this.elapsed * 0.37) * 100) % 100;
    const gapsPerSourcePoint = this.engageDistance / SRC_MELEE_GAP;
    const dist = (SRC_KNOCKBACK_BASE + roll) * gapsPerSourcePoint;
    // The source lets a zombie be shoved anywhere; we floor it at the staging slot so it
    // cannot be driven back into the milling crowd it was released from. `min(p.x, …)`
    // keeps that floor from turning the shove into a shove FORWARD for a zombie that is
    // somehow already behind the slot.
    p.knockBackToX = Math.min(p.x, Math.max(CHARGE_X, p.x - dist));
    p.knockBackSpeed = SRC_KNOCKBACK_FORCE * 60 * gapsPerSourcePoint;
    p.formOrder = this.releaseSeq++; // tail of the deployed block → deeper band
    p.frontPriority = false;
    p.inLine = false; // it is walking back in; it holds no place until it gets there
    p.state = "advance";
    p.timerMs = this.cycleMs(p, null);
    return true;
  }

  /** Advance a live knockback slide. Returns true while the zombie is still being shoved,
   *  in which case it neither walks nor fights this step (source: `movementUpdate:` returns
   *  early, and a non-zero `knockBackPoint` makes `isInMeleeRange` false). */
  private stepKnockBack(p: SimUnit, dtMs: number): boolean {
    let active = false;
    if (p.knockBackSpeed > 0) {
      const step = (p.knockBackSpeed * dtMs) / 1000;
      const dx = p.knockBackToX - p.x;
      if (Math.abs(dx) <= step) {
        p.x = p.knockBackToX;
        p.knockBackSpeed = 0;
      } else {
        p.x += Math.sign(dx) * step;
      }
      active = true;
    }
    if (p.blastAirMs > 0) {
      p.blastAirMs = Math.max(0, p.blastAirMs - dtMs);
      const progress = 1 - p.blastAirMs / Math.max(1, p.blastAirTotalMs);
      const lift = 4 * progress * (1 - progress);
      p.y = p.slotY - lift * p.blastAirHeight;
      if (p.blastAirMs === 0) {
        p.y = p.slotY;
        p.blastAirTotalMs = 0;
        p.blastAirHeight = 0;
        p.blastSpin = 0;
      } else {
        active = true;
      }
    }
    if (!active) return false;
    p.state = "advance";
    p.timerMs = this.cycleMs(p, null);
    return true;
  }

  /** A PvP defender's swing procs, mirroring the attacker's: Double Strike's bonus strike,
   *  Random Stun (held for a second, unless the zombie is mid-move and cannot be
   *  interrupted), and Berserk's self-cost. Only ever reached by a unit that carries
   *  abilities on the enemy side, which no raid enemy does. */
  private defenderSwingProcs(u: SimUnit, foe: SimUnit): void {
    const mult = this.outgoingMult(u);
    if (u.abilities.includes("doubleStrike") && this.abilityRoll(u) > 70 && foe.alive) {
      this.dealEnemyDamage(foe, Math.max(1, Math.round(u.power * 0.25 * mult)));
      this.attacksLanded++;
    }
    if (u.abilities.includes("stun") && this.abilityRoll(u) > 95 && foe.alive && !this.uninterruptible(foe)) {
      foe.stunMs = Math.max(foe.stunMs, 1000);
    }
    // `fromPlayer` false: its own side's blow, so its shield and Phase do not apply.
    if (u.abilities.includes("berserk") && u.alive) this.dealDamage(u, this.berserkCost(u), false);
  }

  /** The front of a PvP formation defense: the live line defender on the forward-most
   *  station. Support takes its share of blows aimed at this one. */
  private frontDefender(): SimUnit | null {
    let front: SimUnit | null = null;
    for (const e of this.enemies) {
      if (!e.alive || e.isGarden || e.stationX === null) continue;
      if (e.state !== "hold" && e.state !== "fight") continue;
      if (!front || e.stationX < (front.stationX ?? Infinity)) front = e;
    }
    return front;
  }

  /** Rage: true while a holder is under RAGE_HP_FRAC of its Life (Life only; a shield is
   *  not Life). */
  private raging(u: SimUnit): boolean {
    return u.hp < u.maxHp * RAGE_HP_FRAC && u.abilities.includes("rage");
  }

  /** What one Berserk swing costs its swinger (see BERSERK_SELF_DRAIN_PER_SEC). */
  private berserkCost(u: SimUnit): number {
    return Math.max(1, Math.round(u.maxHp * BERSERK_SELF_DRAIN_PER_SEC * u.cooldownMs / 1000));
  }

  /** What this zombie's own damage is multiplied by: Berserk always, Rage while raging. */
  private outgoingMult(u: SimUnit): number {
    let mult = 1;
    if (u.abilities.includes("berserk")) mult *= BERSERK_DAMAGE_MULT;
    if (this.raging(u)) mult *= RAGE_DAMAGE_MULT;
    return mult;
  }

  /** Shield Bar soaks a blow before Life; returns what is left of it. The soaked part is
   *  still published as damage taken, so the numbers read the whole hit. Healers never see
   *  the shield (they pick by Life), so a shielded zombie at full Life reads as full. */
  private absorbShield(foe: SimUnit, dmg: number): number {
    if (foe.shield <= 0 || dmg <= 0) return dmg;
    const soak = Math.min(foe.shield, dmg);
    foe.shield -= soak;
    foe.damageFxTaken += soak;
    return dmg - soak;
  }

  private dealDamage(foe: SimUnit, dmg: number, fromPlayer: boolean, shared = false) {
    if (foe.team === "player" && !fromPlayer && dmg > 0) {
      // Phase: nothing lands on it while the window is open.
      if (foe.phaseMs > 0) return;
      dmg = this.absorbShield(foe, dmg);
      if (dmg <= 0) return;
    }
    // A PvP DEFENDER struck by the army: the same defensive abilities the attacking side
    // has. Gated on a formation defense (authored stations), which no raid has, so raids are
    // untouched. Not on the struck unit's own abilities: Support and Protect protect OTHERS.
    if (foe.team === "enemy" && fromPlayer && dmg > 0 && this.authoredStations) {
      if (foe.phaseMs > 0) return;
      // Support: every defending holder takes a tenth of a blow aimed at the front defender.
      if (!shared && foe === this.frontDefender()) {
        const share = dmg * SUPPORT_SHARE;
        for (const e of this.enemies) {
          if (dmg <= 0) break;
          if (e === foe || !e.alive || !e.abilities.includes("support")) continue;
          if (e.state !== "hold" && e.state !== "fight") continue;
          const taken = Math.min(share, dmg);
          dmg -= taken;
          this.dealDamage(e, taken, true, true);
        }
        if (dmg <= 0) return;
      }
      // Protect: folded into the defender's damageReduction when the defense was built.
      if (foe.damageReduction > 0) dmg = applyDamage(dmg, 0, Math.min(1, foe.damageReduction));
      dmg = this.absorbShield(foe, dmg);
      if (dmg <= 0) return;
    }
    // A staggered captain takes more (raid 13): the payoff for breaking his charge.
    if (fromPlayer && foe.staggerMs > 0 && dmg > 0) dmg = Math.round(dmg * STAGGER_DAMAGE_MULT);
    // The ninja's retreat (raid 13, t9+): on the ground he cannot be taken below his retreat
    // line — he smokes back up to the perch instead, and stays there until the rest are down.
    if (foe === this.boss && this.ninjaDown && !this.ninjaRetreated && this.duel?.swapMs) {
      const floor = foe.maxHp * this.duel.ninjaRetreatFrac;
      if (foe.hp - dmg <= floor) {
        if (dmg > 0) foe.damageFxTaken += Math.max(0, foe.hp - floor);
        foe.hp = Math.max(1, floor);
        this.ninjaRetreated = true;
        this.duelSwap(false);
        return;
      }
    }
    // Weakened (raid 12): the army's blows land lighter. Taps on a wall or on a converted
    // zombie are the player's own fingers, not the army's damage, so they are left alone.
    if (fromPlayer && this.rulingFx.weaken !== 1 && dmg > 0 && foe.team === "enemy" &&
        !foe.isWall && !foe.isTurned) {
      dmg = Math.max(1, Math.round(dmg * this.rulingFx.weaken));
    }
    // Publish the hit at its full post-mitigation size BEFORE the HP subtraction clamps
    // it. `hp` is what the fight runs on; `damageFxTaken` is what the numbers report.
    if (dmg > 0) foe.damageFxTaken += dmg;
    foe.hp -= dmg;
    if (foe.hp > 0) return;
    // PHASE (the Secret Boss Zombie): the first killing blow leaves it on 1 Life and out of
    // reach for PHASE_INVULN_MS, long enough for a healer to find it. Same choke point as
    // Unwrapped, and spent for good the same way.
    if (!foe.phaseUsed && foe.abilities.includes("phase")) {
      foe.phaseUsed = true;
      foe.hp = 1;
      foe.phaseMs = PHASE_INVULN_MS;
      foe.phaseFxSeq++;
      return;
    }
    // UNWRAPPED (the Mummy Zombie): the first killing blow of the fight leaves it standing
    // at half Life instead. Here, at the one choke point every death passes through, so no
    // damage path can skip it. Spent for good: Resurrect does not hand it back.
    if (!foe.unwrapUsed && foe.abilities.includes("unwrapped")) {
      foe.unwrapUsed = true;
      foe.hp = Math.max(1, Math.round(foe.maxHp * UNWRAP_HP_FRAC));
      foe.unwrapFxSeq++;
      foe.healFxSeq++;
      return;
    }
    foe.hp = 0;
    foe.alive = false;
    foe.state = "dead";
    if (foe.buddyId) this.deployMiniBuddy(foe, null);
    if (foe.buddyCarrierId) {
      const carrier = this.players.find((p) => p.id === foe.buddyCarrierId);
      if (carrier) carrier.buddyId = null;
      foe.buddyCarrierId = null;
    }
    // A fallen zombie joins the corpse backlog a Garden holder's Resurrect draws from.
    // It is NOT revived here: the source game polls `canRez` from the Garden's own
    // update, so the revive lands whenever a holder is next in a position to cast —
    // which may be long after this death, and may be a holder not yet deployed.
    if (foe.team === "player") {
      this.fallen.push(foe.id);
      if (foe.abilities.includes("lastLaugh")) this.lastLaugh(foe);
      return;
    }
    // A fallen PvP defender joins its own side's corpse backlog (a defending Resurrect draws
    // on it) and sets off its Treat. Keyed on the defense having stations, not this unit:
    // the brute's perch is cleared when it climbs down. No raid authors a station.
    if (this.authoredStations) {
      this.fallenDefenders.push(foe.id);
      if (foe.abilities.includes("lastLaugh")) this.lastLaugh(foe);
    }
    // A pixel zombie broken open hands its captive back. Done HERE rather than in
    // `tapTurned` so it cannot be bypassed: this is the one choke point every death goes
    // through, and a captive stranded by some other damage path would sit `taken` with
    // nothing left on the field able to release it.
    if (foe.isTurned) {
      this.releaseTurned(foe);
      return; // …and it is not wave population, so it does not gate the next emergence.
    }
    // The bozo stack broken open: everyone standing in it comes back (raid 14).
    if (foe.isBozoStack) {
      this.freeBozos(foe, 0);
      return;
    }
    // Volatile Remains (Endless curse): a blast where the enemy fell, not a team-wide hit.
    // It used to strike every living zombie, including the ones still queued to deploy, so
    // one pop took a quarter of the team bar off bodies no healer could reach (player
    // report, 2026-11-11). Now only zombies out on the field and within reach of the body:
    // the front line and the band behind it. Gardens at their station stay clear.
    if (foe.deathExplosion && this.abilityRoll(foe) < foe.deathExplosion.chance * 100) {
      const reach = this.engageDistance + DEATH_BLAST_REACH;
      for (const player of this.players) {
        if (!player.alive || player.taken || !this.onField(player)) continue;
        if (Math.abs(player.x - foe.x) > reach) continue;
        this.dealDamage(player, Math.max(1, Math.round(player.maxHp * foe.deathExplosion.damagePercent / 100)), false);
      }
    }
    // Only an enemy reaches here. A downed one opens the gate for the next to emerge.
    if (fromPlayer) this.emergeCooldown = ENEMY_EMERGE_GAP_MS;
  }

  /** LAST LAUGH (JackoZombie): it falls, and every zombie still standing heals a fifth of
   *  its Life — deployed or still waiting, since the waiting ones are part of the army too
   *  (they are at full Life anyway). Fires on ANY death, its own Explode included, which
   *  is what makes the fuse a planned sacrifice rather than just a blast. */
  private lastLaugh(fallen: SimUnit): void {
    fallen.lastLaughFxSeq++;
    for (const p of fallen.team === "player" ? this.players : this.enemies) {
      if (!p.alive || p.taken || p.hp >= p.maxHp) continue;
      p.hp = Math.min(p.maxHp, p.hp + Math.max(1, Math.round(p.maxHp * LAST_LAUGH_HEAL_FRAC)));
      p.healFxSeq++;
    }
  }

  /** Resurrect is automatic and one-use. A living Garden holder revives the
   *  defeated zombie at full Life and sends it back into formation. */
  private resurrect(healer: SimUnit, defeated: SimUnit): void {
    healer.resurrectUsed = true;
    const slot = this.fallen.indexOf(defeated.id);
    if (slot >= 0) this.fallen.splice(slot, 1);
    defeated.alive = true;
    defeated.hp = defeated.maxHp;
    defeated.state = "advance";
    defeated.teleportPending = defeated.abilities.includes("teleport");
    defeated.x = CHARGE_X;
    // Stale until the next formation pass; a Teleport holder must not jump to it.
    if (defeated.teleportPending) defeated.slotX = CHARGE_X;
    defeated.y = CENTER_Y;
    defeated.prevX = defeated.x;
    defeated.prevY = defeated.y;
    // Death gives the slot up, so resurrection is a fresh arrival at the tail just like
    // knockback. Headless is the one exception to where that arrival is displayed: every
    // incoming Headless pushes to position zero, including one arriving via resurrection
    // — but only once it has walked back up. It holds no place in the line on the way
    // (`inLine`), so the row does not step back to leave its spot open for the seven
    // seconds a slow Headless takes to cross the field.
    defeated.formOrder = this.releaseSeq++;
    defeated.frontPriority = defeated.isHeadless;
    defeated.inLine = false;
    // Sent back to the charge slot means sent back BEHIND anything standing mid-lane —
    // the alien boss's abductee, or a boss wall. `passedBlockers` records "already ahead of
    // that blocker when it appeared", and a corpse carried back to x=CHARGE_X plainly is
    // not: leaving it latched let a revived zombie walk straight through the abductee it
    // had marched past in its first life and never trade a blow with it. It re-enters the
    // lane like any other zombie, so it re-earns the latch (or fights the blocker).
    //
    // ANY backwards carry is this same case, not just a revive — a teleport that throws the
    // line back down the lane has to clear this too, or half the army walks through a wall
    // it is standing behind.
    defeated.passedBlockers = [];
    defeated.timerMs = this.cycleMs(defeated, null);
    defeated.windupKey = null;
    defeated.windupMs = 0;
    defeated.stunMs = 0;
    defeated.burnMs = 0; // whatever it died of, it does not come back still alight
    defeated.dotMs = 0;
    defeated.oneShotProtectionUsed = false;
    // GROUND TRUTH (`-[ZombieActorGarden ressurectZombie:]` 0x7d3c2-0x7d436): the revived
    // actor's whole `abilityList` is walked and EVERY ability carrying `consumable` is
    // handed `setConsumed:YES` — and `-[ZFActorAbility isUseable]` (0x9cafc) refuses a
    // consumed ability outright. So a zombie comes back ALIVE but SPENT: it can never
    // light a second fuse, and a revived Garden holder can never pay the revive forward
    // (which is what stops two holders reviving each other for the rest of the fight).
    // The consumable set is exactly the four one-use abilities (`ZFActorActivatedAbility
    // initWithTag:` writes the flag for tags 29/30/35/36) — Resurrect, Mini Buddy,
    // Explode, Explode Ver.2 — which is `useOnce` here plus the Resurrect latch.
    //
    // It is UNCONDITIONAL: a move the zombie never got round to using is spent too, so a
    // bomber cut down before it lit its fuse comes back without one. Coming back at all is
    // the reward; coming back armed is not.
    //
    // Read BEFORE the abilities are marked: a zombie that spent Explode and is standing
    // here as a casualty is, by definition, the one that blew itself up. That combination —
    // a Garden holder pulling a Small zombie back out of its own blast — is the
    // "Recycled" achievement, and this is the only moment it is observable.
    const exploded = defeated.usedAbilities.some((k) => k === "explode" || k === "explodeV2");
    this.feats.resurrections.push({ exploded });
    for (const key of defeated.abilities) {
      if (ACTIVATED_ABILITY[key]?.useOnce && !defeated.usedAbilities.includes(key)) {
        defeated.usedAbilities.push(key);
      }
    }
    if (defeated.abilities.includes("ressurect")) defeated.resurrectUsed = true;
    defeated.healFxSeq++;
  }

  /** Apply an ordinary enemy hit through the recovered player-zombie one-shot floor. */
  private dealEnemyDamage(foe: SimUnit, dmg: number, shared = false) {
    if (foe.team === "player" && foe.phaseMs > 0) return;
    // Support (the Mega Boss Zombie): every holder on the field takes SUPPORT_SHARE of the
    // ORIGINAL blow aimed at the front zombie (two holders take a tenth each, not a tenth and
    // then a tenth of the rest), through its own mitigation. Split before the raid's damage
    // multipliers, which each share then picks up on its own way through. Ten holders would
    // share out the whole blow, and the front takes nothing.
    if (!shared && foe.team === "player" && !foe.isGarden && foe.lineupIndex === 0 && dmg > 0) {
      const share = dmg * SUPPORT_SHARE;
      for (const p of this.players) {
        if (dmg <= 0) break;
        if (p === foe || !p.alive || p.taken || !p.abilities.includes("support")) continue;
        if (p.state !== "advance" && p.state !== "fight") continue;
        const taken = Math.min(share, dmg);
        dmg -= taken;
        this.dealEnemyDamage(p, taken, true);
      }
      if (dmg <= 0) return;
    }
    // Emboldened (raid 12): everything the enemy lands on a zombie lands harder.
    if (foe.team === "player" && this.rulingFx.embolden !== 1) dmg *= this.rulingFx.embolden;
    // Do or Die: every blow on a zombie lands at DO_OR_DIE_DAMAGE — swings, throws, the
    // Count's slam, burns — on top of the doubled swing rate, so ~4x the damage a second.
    if (foe.team === "player" && this.doOrDie) dmg *= DO_OR_DIE_DAMAGE;
    // Team Block adds 20% per carrier whose one-second window is live, up to 100%.
    // Protect remains additive, with the combined reduction capped below.
    const blockers = this.players.filter((p) => p.alive && p.blockMs > 0).length;
    const blockReduction = Math.min(1, blockers * 0.2);
    const reduction = foe.team === "player"
      ? Math.min(1, (foe.damageReduction ?? 0) + blockReduction)
      : 0;
    const applied = foe.team === "player"
      ? this.absorbShield(foe, applyDamage(dmg, 0, reduction))
      : applyDamage(dmg, 0, reduction);
    if (
      applied > 0 &&
      foe.team === "player" &&
      foe.alive &&
      !foe.oneShotProtectionUsed &&
      foe.hp > 1 &&
      (foe.hp - applied) / foe.maxHp < ONE_SHOT_FLOOR
    ) {
      // The latch spares the zombie but does not soften the blow: the number still
      // reads the whole hit. This branch bypasses `dealDamage`, so it publishes itself.
      foe.damageFxTaken += applied;
      foe.hp = 1;
      foe.oneShotProtectionUsed = true;
      return;
    }
    this.dealDamage(foe, applied, false);
  }

  /** Burn down one tick of `pixelFire`. The RATE is ground truth — `damage:
   *  hitPointsTotal/20 × dt`, 5 % of max HP a second, through the normal damage path so
   *  armour, damage reduction and the one-shot floor all apply. The DURATION is ours (see
   *  PIXEL_FIRE_BURN_MS): the shipped game's burn lasts a single frame.
   *
   *  Costed against the tick actually taken rather than a fixed frame, so a 50 ms sim step
   *  and a 16 ms one remove the same HP per second of burn. */
  /** Tick a gout burn (ruleset 92): flat damage per Ms through the ordinary damage path, so
   *  armour, Protect and the rest apply. No panic and no tapping, unlike pixelFire. */
  private stepDot(p: SimUnit, dtMs: number) {
    if (p.dotMs <= 0) return;
    const burnt = Math.min(p.dotMs, dtMs);
    p.dotMs -= dtMs;
    if (p.dotMs <= 0) { p.dotMs = 0; }
    this.dealEnemyDamage(p, p.dotPerMs * burnt);
    p.struckThisTick = true;
  }

  /** How far the Video Games front-area moves reach from the enemy (sim units): the front
   *  line and the band behind it. Read by the renderer so the gout is drawn exactly as long
   *  as the area it burns. */
  frontAreaReach(): number {
    return this.engageDistance + DEATH_BLAST_REACH;
  }

  /** Deployed zombies within `reach` of an enemy standing at the front (gout, shield slam). */
  private frontAreaPlayers(e: SimUnit, reach: number): SimUnit[] {
    return this.players.filter((p) => p.alive && !p.taken && this.onField(p) && Math.abs(p.x - e.x) <= reach);
  }

  private stepBurn(p: SimUnit, dtMs: number) {
    if (p.burnMs <= 0) return;
    const burnt = Math.min(p.burnMs, dtMs);
    p.burnMs -= dtMs;
    if (p.burnMs <= 0) {
      p.burnMs = 0;
      p.burnWalk = false;
      p.timerMs = this.cycleMs(p, null); // it comes out of the fire mid-swing, not primed
    }
    this.dealEnemyDamage(p, (p.maxHp * BURN_MAX_HP_FRACTION_PER_SEC * burnt) / 1000);
    p.struckThisTick = true;
  }

  /** A burning zombie's panic walk: back and forth over PIXEL_FIRE_PACE_REACH either side
   *  of wherever the fire caught it, turning at each end. It covers no ground and reaches
   *  no formation slot — that is the point of being on fire. */
  private pacePanicked(p: SimUnit, dtMs: number) {
    p.x += (p.burnDir * PIXEL_FIRE_PACE_SPEED * dtMs) / 1000;
    if (p.burnDir < 0 && p.x <= p.burnAnchorX - PIXEL_FIRE_PACE_REACH) {
      p.x = p.burnAnchorX - PIXEL_FIRE_PACE_REACH;
      p.burnDir = 1;
    } else if (p.burnDir > 0 && p.x >= p.burnAnchorX + PIXEL_FIRE_PACE_REACH) {
      p.x = p.burnAnchorX + PIXEL_FIRE_PACE_REACH;
      p.burnDir = -1;
    }
    p.y = p.slotY;
  }

  /** Advance the charging zombie's focus bar, running the bubble minigame unless
   *  Concentration is active. See CHARGE_STEPS: the fill clamps to the next
   *  threshold so a big frame can't skip a distraction. */
  private stepCharge(p: SimUnit, dtMs: number) {
    if (this.concentration) {
      p.charge = Math.min(1, p.charge + dtMs / this.focusChargeMs);
      if (p.charge >= 1) this.releaseCharger(p);
      return;
    }
    if (this.noDistractions) {
      if (p.awaitRelease) {
        p.bubbleMs -= dtMs;
        if (p.bubbleMs <= 0) this.releaseCharger(p);
        return;
      }
      p.charge = Math.min(1, p.charge + dtMs / this.focusChargeMs);
      if (p.charge >= 1) { p.awaitRelease = true; p.bubbleMs = BRAIN_AUTO_MS; }
      return;
    }
    if (p.distracted) {
      p.bubbleMs -= dtMs;
      if (p.bubbleMs <= 0) p.distracted = false; // auto-refocus
      return;
    }
    if (p.awaitRelease) {
      p.bubbleMs -= dtMs;
      if (p.bubbleMs <= 0) this.releaseCharger(p); // auto-advance
      return;
    }
    const next = CHARGE_STEPS[p.distractStep] ?? 1;
    p.charge = Math.min(next, p.charge + dtMs / this.focusChargeMs);
    if (p.charge >= next) {
      p.distractStep++;
      if (next >= 1) {
        // Full bar: gate the release (brain bubble). This is a release prompt, not
        // a focus roll, so it always shows (Concentration path above skips it).
        p.awaitRelease = true;
        p.bubbleMs = BRAIN_AUTO_MS;
      } else if (this.rollDistract(p)) {
        // Passing a 0.25 segment: distract only if the focus roll fails. Miss the
        // roll and the meter keeps filling toward the next segment uninterrupted.
        p.distracted = true;
        p.bubbleMs = BUTTERFLY_AUTO_MS;
      }
    }
  }

  /** Deterministic per-segment distraction roll. GROUND TRUTH (`-[FightFocusBar
   *  update:]`): at each 0.25 charge segment a zombie is distracted iff
   *  `rand01 > focus/100` — so focus 100 (premium) is NEVER distracted, and a
   *  focus-40 starter is distracted ~60% of the time per segment. Uses the
   *  replayable `hash` (keyed by the unit's seed + which segment) instead of an RNG
   *  so the sim stays deterministic/replayable. */
  private rollDistract(p: SimUnit): boolean {
    const r = hash(p.distractSeed * 16.7 + p.distractStep * 3.1);
    return r > clamp(p.focus, 0, 100) / 100;
  }

  /** MEDUSA (owner, 2026-11-05). On deploy Petrify freezes a boss up on its perch, stalling
   *  whatever it was doing, and Stone Gaze gets one look at the first enemy she can see. Each
   *  is a card ability, so each opens with its Life Force slot like every other. */
  private medusaDeployed(p: SimUnit) {
    p.gazeReady = p.abilities.includes("stoneGaze");
    const boss = this.boss;
    if (p.abilities.includes("petrify") && boss && boss.alive && boss.state === "structure" && this.bossFreezeLockMs <= 0) {
      this.bossFreezeMs = MEDUSA_FREEZE_MS;
      this.bossFreezeLockMs = MEDUSA_FREEZE_LOCK_MS;
      boss.stoneMs = MEDUSA_FREEZE_MS;
    }
  }

  /** Spend each ready Medusa's look on the nearest enemy actually on the field. A perched boss
   *  is the freeze's business and a foe that shrugs the stun off stays its colour. */
  private stepMedusa(dtMs: number) {
    if (this.bossFreezeMs > 0) this.bossFreezeMs = Math.max(0, this.bossFreezeMs - dtMs);
    if (this.bossFreezeLockMs > 0) this.bossFreezeLockMs = Math.max(0, this.bossFreezeLockMs - dtMs);
    for (const u of this.units) if (u.stoneMs > 0) u.stoneMs = Math.max(0, u.stoneMs - dtMs);
    for (const p of this.players) {
      if (!p.gazeReady || !p.alive) continue;
      const seen = this.enemies
        .filter((e) => e.alive && !e.isWall && e.state !== "queued" && e.state !== "structure" && e.state !== "descending" && e.state !== "falling")
        .sort((a, b) => a.x - b.x)[0];
      if (!seen) continue;
      p.gazeReady = false;
      this.stunEnemy(seen, MEDUSA_GAZE_MS, "medusaGaze", p);
      if (seen.stunMs > 0) seen.stoneMs = Math.max(seen.stoneMs, seen.stunMs);
    }
  }

  /** Dr. Groundhog's launch: the zombie is thrown clear to the back and has to walk in again.
   *  It flies there like a projectile (the blast arc), landing as the slide ends. */
  private launchToBack(p: SimUnit) {
    if (!p.alive || p.taken || p.knockBackSpeed > 0 || p.blastAirMs > 0) return;
    if (!this.onField(p)) return; // never launch (and so deploy) a queued zombie
    const airMs = Math.max(600, Math.round(Math.abs(p.x - Math.min(p.x, CHARGE_X)) / LAUNCH_SPEED * 1000));
    p.blastAirMs = airMs;
    p.blastAirTotalMs = airMs;
    p.blastAirHeight = p.isHeadless ? 150 : 120;
    p.blastSpin = (stringSeed(p.id) & 1) === 0 ? 1 : -1;
    p.windupKey = null;
    p.windupMs = 0;
    p.knockBackToX = Math.min(p.x, CHARGE_X);
    p.knockBackSpeed = LAUNCH_SPEED;
    p.formOrder = this.releaseSeq++;
    p.frontPriority = false;
    p.inLine = false;
    p.state = "advance";
    p.timerMs = this.cycleMs(p, null);
  }

  /** Tapping a winding-up slam that allows it weakens it (Endless's Dr. Groundhog). */
  tapCharge(unitId: string): boolean {
    const foe = this.enemies.find((e) => e.id === unitId);
    const reduce = foe?.chargeCfg?.tapReduce ?? 0;
    if (!foe || !foe.alive || reduce <= 0 || foe.chargeMs <= 0 || foe.chargeTapScale <= CHARGE_TAP_FLOOR) return false;
    foe.chargeTapScale = Math.max(CHARGE_TAP_FLOOR, foe.chargeTapScale - reduce);
    return true;
  }

  /** Release a fully-charged zombie to advance to the front line. */
  private releaseCharger(p: SimUnit) {
    // Nothing has claimed a formation slot yet: this is the army's first deploy.
    const firstDeploy = !p.loaned && this.releaseSeq === 0;
    p.state = "advance";
    p.teleportPending = p.abilities.includes("teleport");
    if (p.abilities.includes("stoneGaze") || p.abilities.includes("petrify")) this.medusaDeployed(p);
    p.formOrder = this.releaseSeq++; // claim a formation slot on release
    p.distracted = false;
    p.awaitRelease = false;
    if (!p.loaned && this.ownDeployed() >= LOANED_AFTER_DEPLOYS) this.releaseLoaned();
    if (firstDeploy && this.openingEscort > 0) {
      // Head Start: the next in line go with it, in queue order. A Mini already riding a
      // Large is "carried", not queued, and goes with its carrier.
      const escort = this.players
        .filter((q) => q !== p && q.alive && !q.loaned && (q.state === "waiting" || q.state === "charging"))
        .slice(0, this.openingEscort);
      for (const q of escort) this.releaseCharger(q);
    }
  }

  /** How many of the army's own zombies have left the queue (dead ones included). Read off
   *  the units, not a counter, so a restored snapshot needs nothing extra. */
  private ownDeployed(): number {
    return this.players.filter((q) => !q.loaned && q.state !== "waiting" && q.state !== "charging" && q.state !== "carried").length;
  }

  /** Out on the field: deployed and not yet fallen. A Mini riding a Large ("carried") is NOT —
   *  it has not deployed, and its x is wherever it was standing in the queue when it was picked
   *  up. Boss moves that pick "deployed" zombies used to include riders: Dr. Groundhog's launch
   *  threw every rider off its carrier to walk in alone (a player report, 2026-11-11), and the
   *  Ninja flank, reading the stale x as the rear, went for them first. */
  private onField(p: SimUnit): boolean {
    return p.state !== "waiting" && p.state !== "charging" && p.state !== "carried" && p.state !== "dead";
  }

  /** Endless's loaned Special skips the line (owner, 2026-11-08): it walks on with the army's
   *  third deploy, so it is a reinforcement rather than a body clogging the queue. */
  private releaseLoaned() {
    for (const q of this.players) {
      if (q.loaned && q.alive && (q.state === "waiting" || q.state === "charging")) this.releaseCharger(q);
    }
  }

  /** Who the ringmaster's whip strikes (raid 14): the nearest zombie on his LEFT — the healer
   *  side — within reach, and only with nothing there the nearest on his right, the front
   *  line. Null when nobody is in reach either way. */
  private whipTarget(e: SimUnit): SimUnit | null {
    const reach = this.bigTop?.whipReach ?? 0;
    let left: SimUnit | null = null;
    let right: SimUnit | null = null;
    for (const p of this.players) {
      if (!p.alive || p.taken || (p.state !== "advance" && p.state !== "fight")) continue;
      const d = Math.abs(p.x - e.x);
      if (d > reach) continue;
      if (p.x < e.x - 0.5) {
        if (!left || p.x > left.x) left = p;
      } else if (!right || p.x < right.x) {
        right = p;
      }
    }
    return left ?? right;
  }

  /** The Garden the whip's crack holds (raid 14): the nearest one on the ringmaster's LEFT,
   *  within reach, that is not already stunned. Null when there is none. */
  private whipGarden(e: SimUnit): SimUnit | null {
    const reach = this.bigTop?.whipReach ?? 0;
    let best: SimUnit | null = null;
    for (const p of this.players) {
      if (!p.alive || !p.isGarden || p.taken || p.stunMs > 0) continue;
      if (p.state !== "advance" && p.state !== "fight") continue;
      if (p.x >= e.x - 0.5 || e.x - p.x > reach) continue;
      if (!best || p.x > best.x) best = p;
    }
    return best;
  }

  /** The zombies on the lane the big top can reach: deployed, not carried, not converted. */
  private onLane(): SimUnit[] {
    return this.players.filter((p) =>
      p.alive && !p.taken && (p.state === "advance" || p.state === "fight"));
  }

  /** The bozo stack standing in the middle, or null. */
  private bozoStack(): SimUnit | null {
    return this.enemies.find((e) => e.isBozoStack && e.alive) ?? null;
  }

  /** Run the big top's clocks (raid 14): the trapeze, the bozos and their hammers, and the
   *  pixel fire. The whip lives in the enemy loop and the ringmaster's drop in promote. */
  private stepBigTop(dtMs: number) {
    const cfg = this.bigTop;
    if (!cfg || !this.anyAlive(this.players)) return;

    // THE TRAPEZE (t3+). One artist at a time; she comes for the rearmost zombie on the
    // lane, swings with it, and drops it where the swing is when tapped — or back at the
    // staging slot when she gives up.
    if (cfg.trapeze) {
      const active = this.grabbers.some((g) => g.drop && g.state !== "gone");
      if (!active) {
        this.trapezeTimerMs += dtMs;
        const lane = this.onLane();
        if (this.trapezeTimerMs >= cfg.trapezeEveryMs && lane.length > 1) {
          this.trapezeTimerMs = 0;
          this.spawnTrapeze(lane.sort((a, b) => a.x - b.x)[0], cfg);
        }
      }
      this.stepTrapezes(dtMs);
    }

    // BOZOS (t5+): once the ringmaster is down, the Video Games boss starts converting.
    const stack = this.bozoStack();
    if (cfg.bozos && cfg.bozo && this.boss && !this.boss.alive) {
      this.convertTimerMs += dtMs;
      if (this.convertTimerMs >= cfg.convertMs) {
        this.convertTimerMs = 0;
        if (this.bozoIds.length < cfg.bozoCap) this.convertToBozo(cfg);
      }
    }
    // The stack's hammers, faster the taller it is.
    if (stack) {
      const height = this.stackHeight(stack);
      this.hammerTimerMs += dtMs * height;
      if (this.hammerTimerMs >= cfg.hammerMs) {
        this.hammerTimerMs = 0;
        const target = this.throwTarget();
        if (target) {
          this.launchProjectile(target, cfg.hammerDamage, HAMMER_SPRITE, 28, {
            originDx: stack.x - BOSS_STRUCT_X,
            originDy: stack.y - 40 - BOSS_STRUCT_Y,
          });
        }
      }
    }

    // PIXEL FIRE (t7+): a burning zombie walks BACK — see walkBurning.
    if (cfg.fire) {
      this.fireTimerMs += dtMs;
      if (this.fireTimerMs >= cfg.fireEveryMs) {
        this.fireTimerMs = 0;
        const lane = this.onLane().filter((p) => p.burnMs <= 0);
        if (lane.length) {
          const victim = lane[Math.floor(hash(this.elapsed * 0.013 + 29) * lane.length) % lane.length];
          victim.windupKey = null;
          victim.windupMs = 0;
          victim.burnMs = PIXEL_FIRE_BURN_MS;
          victim.burnWalk = true;
          victim.burnAnchorX = victim.x;
          victim.burnDir = -1;
          victim.struckThisTick = true;
        }
      }
    }
  }

  /** A burning zombie on the big top walks BACK toward the staging slot until the fire goes
   *  out. Whatever blocker it walks back past is ahead of it again, so if it gets far enough
   *  it turns and fights the ringmaster or the bozo stack — the fire is a penalty that
   *  doubles as the way into the middle. */
  private walkBurning(p: SimUnit, dtMs: number) {
    p.inLine = false;
    p.walkingThisTick = true;
    p.x = Math.max(CHARGE_X, p.x - (FIRE_WALK_SPEED * dtMs) / 1000);
    p.y = p.slotY;
    if (p.passedBlockers.length) {
      p.passedBlockers = p.passedBlockers.filter((id) => {
        const b = this.enemies.find((e) => e.id === id);
        return !!b && b.alive && b.x < p.x;
      });
    }
  }

  /** A trapeze artist for the raid-14 drop. Swoops like the rescue hazard, then SWINGS. */
  private spawnTrapeze(victim: SimUnit, cfg: BigTopConfig) {
    const seq = this.grabSeq++;
    const swingStartDeg = seq % 2 === 0 ? 0 : 180;
    const targetDx = clamp((victim.x - GRABBER_PIVOT_X) / GRABBER_SWING_RADIUS_X, -1, 1);
    const contactDeg = Math.acos(targetDx) * 180 / Math.PI;
    const swingTotalMs = Math.max(1, GRABBER_FULL_ARC_MS * Math.abs(contactDeg - swingStartDeg) / 180);
    this.grabbers.push({
      id: `trap${seq}`,
      x: GRABBER_PIVOT_X,
      y: GRABBER_PIVOT_Y,
      state: "swoop",
      hp: 1,
      maxHp: 1,
      tapDamage: 1,
      grabbedId: null,
      pauseMs: swingTotalMs,
      tapCdMs: 0,
      sprite: TRAPEZE_SPRITE,
      rot: swingStartDeg,
      swingStartDeg,
      contactDeg,
      swingTotalMs,
      targetId: victim.id,
      struckThisTick: false,
      drop: true,
      swingMs: 0,
      holdMs: cfg.trapezeHoldMs,
    });
  }

  /** Swoop, grab, swing — and let go at the staging slot if nobody taps in time. */
  private stepTrapezes(dtMs: number) {
    for (const g of this.grabbers) {
      if (!g.drop || g.state === "gone") continue;
      if (g.state === "swoop") {
        g.pauseMs = Math.max(0, g.pauseMs - dtMs);
        const t = 1 - g.pauseMs / g.swingTotalMs;
        const eased = t * t * (3 - 2 * t);
        g.rot = g.swingStartDeg + (g.contactDeg - g.swingStartDeg) * eased;
        if (g.pauseMs > 0) continue;
        const victim = g.targetId ? this.players.find((p) => p.id === g.targetId) : null;
        if (!victim || !victim.alive || victim.taken ||
            (victim.state !== "advance" && victim.state !== "fight")) {
          g.state = "gone";
          continue;
        }
        g.grabbedId = victim.id;
        g.targetId = null;
        g.state = "carry";
        g.swingMs = 0;
        victim.state = "grabbed";
        victim.windupKey = null;
        victim.windupMs = 0;
        victim.stunMs = 0;
        victim.burnMs = 0;
        victim.burnWalk = false;
        continue;
      }
      // carry: the catch rides a pendulum across the middle of the lane.
      const z = g.grabbedId ? this.players.find((p) => p.id === g.grabbedId) : null;
      if (!z || !z.alive) {
        g.grabbedId = null;
        g.state = "gone";
        continue;
      }
      g.swingMs = (g.swingMs ?? 0) + dtMs;
      const phase = (2 * Math.PI * g.swingMs) / TRAPEZE_SWING_PERIOD_MS;
      g.x = TRAPEZE_SWING_CENTRE_X + TRAPEZE_SWING_HALF_X * Math.sin(phase);
      g.y = CENTER_Y - GRABBER_ZOMBIE_OFFSET_Y - 70;
      g.rot = 90 + 30 * Math.cos(phase);
      z.x = g.x;
      z.y = g.y + GRABBER_ZOMBIE_OFFSET_Y;
      z.prevX = z.x;
      z.prevY = z.y;
      if (g.swingMs >= (g.holdMs ?? 0)) this.dropTrapeze(g, CHARGE_X);
    }
    for (let i = this.grabbers.length - 1; i >= 0; i--) {
      if (this.grabbers[i].drop && this.grabbers[i].state === "gone") this.grabbers.splice(i, 1);
    }
  }

  /** Put the trapeze's catch down at lane `x`. Everything behind that point it is past;
   *  everything ahead — the ringmaster, the stack — it will stop and fight. */
  private dropTrapeze(g: SimGrabber, x: number) {
    const z = g.grabbedId ? this.players.find((p) => p.id === g.grabbedId) : null;
    g.grabbedId = null;
    g.state = "gone";
    if (!z || !z.alive) return;
    z.state = "advance";
    z.x = clamp(x, CHARGE_X, this.frontX);
    z.y = CENTER_Y;
    z.prevX = z.x;
    z.prevY = z.y;
    z.vx = 0;
    z.vy = 0;
    z.timerMs = this.cycleMs(z, null);
    z.formOrder = this.releaseSeq++;
    z.frontPriority = false;
    z.inLine = false;
    z.passedBlockers = this.enemies.filter((e) => e.alive && e.isBlocker && e.x < z.x).map((e) => e.id);
  }

  /** Player tapped the raid-14 trapeze: drop the catch where the swing is RIGHT NOW. The
   *  position is sim state on both sides, so the transcript carries only which artist.
   *  Returns false — a refusal the transcript records — when there is nothing to drop. */
  tapTrapeze(id: string): boolean {
    if (this.finished) return false;
    const g = this.grabbers.find((x) => x.id === id && x.drop && x.state === "carry");
    if (!g) return false;
    g.struckThisTick = true;
    this.dropTrapeze(g, g.x);
    return true;
  }

  /** The raid-14 trapeze carrying a zombie right now, or null. */
  activeTrapeze(): SimGrabber | null {
    return this.grabbers.find((g) => g.drop && g.state === "carry") ?? null;
  }

  /** Where the middle of the lane is being held right now (the ringmaster on the ground, or
   *  the bozo stack), for a player deciding where to drop — null when nothing is. */
  bigTopMiddle(): SimUnit | null {
    if (!this.bigTop) return null;
    const boss = this.boss;
    if (boss && boss.alive && boss.isBlocker) return boss;
    return this.bozoStack();
  }

  /** How many zombies are standing in the bozo stack, and the cap. */
  bozoStatus(): { count: number; cap: number } | null {
    if (!this.bigTop?.bozos) return null;
    return { count: this.bozoIds.length, cap: this.bigTop.bozoCap };
  }

  /** The Video Games boss turns a zombie into a bozo: it leaves the lane (`taken` — alive,
   *  a survivor, NOT a loss) and climbs onto the stack in the middle. */
  private convertToBozo(cfg: BigTopConfig) {
    const lane = this.onLane();
    if (!lane.length || !cfg.bozo) return;
    const victim = lane[Math.floor(hash(this.elapsed * 0.017 + 41) * lane.length) % lane.length];
    victim.taken = true;
    victim.windupKey = null;
    victim.windupMs = 0;
    victim.burnMs = 0;
    victim.burnWalk = false;
    victim.struckThisTick = true;
    this.bozoIds.push(victim.id);
    let stack = this.bozoStack();
    if (!stack) {
      stack = this.spawnEnemy(cfg.bozo);
      stack.isBozoStack = true;
      stack.isBlocker = true;
      stack.isSummon = true;
      stack.anchorsLine = false;
      stack.state = "hold";
      stack.x = cfg.stationX;
      stack.y = CENTER_Y;
      stack.stationX = cfg.stationX;
      stack.stationY = CENTER_Y;
      stack.prevX = stack.x;
      stack.prevY = stack.y;
      stack.stackBaseHp = cfg.bozoHp;
      stack.stackGrowMs = 0;
      stack.stackCeiling = cfg.bozoCap;
      stack.hp = 0;
      stack.maxHp = 0;
      for (const p of this.players) {
        if (p.alive && p.x > stack.x + 0.5) p.passedBlockers.push(stack.id);
      }
    }
    const count = this.bozoIds.length;
    stack.stackMax = count;
    stack.maxHp = count * cfg.bozoHp;
    stack.hp = Math.min(stack.maxHp, stack.hp + cfg.bozoHp);
    stack.stackSeen = this.stackHeight(stack);
  }

  /** Knock bozos off until the stack is `height` tall, most recent first — each one is a
   *  zombie coming back, put down just in front of the stack (so it is past it). */
  private freeBozos(stack: SimUnit, height: number) {
    const cfg = this.bigTop;
    while (this.bozoIds.length > height) {
      const id = this.bozoIds.pop()!;
      const z = this.players.find((p) => p.id === id);
      if (!z || !z.alive) continue;
      z.taken = false;
      z.state = "advance";
      z.x = stack.x + 30;
      z.y = CENTER_Y;
      z.prevX = z.x;
      z.prevY = z.y;
      z.timerMs = this.cycleMs(z, null);
      z.formOrder = this.releaseSeq++;
      z.inLine = false;
      z.passedBlockers = this.enemies.filter((e) => e.alive && e.isBlocker && e.x < z.x).map((e) => e.id);
    }
    if (cfg && stack.alive) {
      stack.stackMax = Math.max(1, this.bozoIds.length);
      stack.maxHp = Math.max(1, this.bozoIds.length * cfg.bozoHp);
      stack.hp = Math.min(stack.hp, stack.maxHp);
    }
  }

  /** Player tapped the focus bubble over the charging zombie: a butterfly
   *  (distraction) pop resumes the fill; a brain (full) pop sends it forward.
   *  Returns true if a bubble was actually popped (drives tap feedback). */
  popBubble(id: string): boolean {
    if (this.finished) return false;
    const p = this.players.find((u) => u.id === id);
    if (!p || !p.alive || p.state !== "charging") return false;
    if (p.awaitRelease) { this.releaseCharger(p); return true; }
    if (p.distracted) { p.distracted = false; return true; }
    return false;
  }

  /** The charging zombie showing a focus bubble right now (or null). Only one
   *  zombie charges at a time, so at most one bubble is ever live. */
  chargingBubble(): { id: string; kind: "butterfly" | "brain" } | null {
    const p = this.players.find(
      (u) => u.alive && u.state === "charging" && (u.distracted || u.awaitRelease)
    );
    return p ? { id: p.id, kind: p.awaitRelease ? "brain" : "butterfly" } : null;
  }

  /** Promote the zombie charge queue + the enemy emerge queue.
   *
   *  GROUND TRUTH for the enemy half — see types.WaveCadence. Two things release a
   *  queued enemy in the source, and both boil down to "fill a free `enemySlots` entry":
   *  a death (`update:` 0x5d60c) and the `spawnTimer` drip (`updateTimer:` 0x613ee).
   *  The death path only ever REPLACES what died, so the field can grow past one enemy
   *  only via the drip — which is why `activeTarget` climbs one per drip rather than the
   *  whole wave pouring out at t=0. Ten of the eleven raids have no drip at all and so
   *  stay at `activeTarget` 1 for the whole fight. */
  private promote(dtMs: number) {
    this.emergeCooldown -= dtMs;

    const charging = this.players.some((p) => p.alive && p.state === "charging");
    if (!charging) {
      // The loaned Special never queues (releaseLoaned); an army of fewer than three of
      // its own zombies sends it once the last of them is out.
      const next = this.players.find((p) => p.alive && p.state === "waiting" && !p.loaned);
      if (next) next.state = "charging";
      else this.releaseLoaned();
    }

    // The reinforcement clock runs on its own regardless of the emerge beat below.
    const queuedLeft = this.enemies.some((e) => e.alive && !e.isBoss && e.state === "queued");
    if (this.cadence.dripMs > 0 && this.activeTarget < this.cadence.maxActive && queuedLeft) {
      this.dripLeft -= dtMs;
      if (this.dripLeft <= 0) {
        this.dripLeft = this.cadence.dripMs;
        this.activeTarget++;
      }
    }

    if (this.emergeCooldown > 0) return;

    // A summoned abductee is off-budget on BOTH counts: it does not occupy one of the
    // wave's slots, and it does not hold the boss on its perch. See SimUnit.isSummon.
    // The front-most surviving station decides where the army stands (no-op in raids).
    this.refreshFrontLine();
    // AUTHORED DEFENDERS (PvP formation defense) ignore the wave budget entirely:
    // each walks on when its own clock says so, and none of them counts toward or
    // competes for `activeTarget`. Absent `deployAtMs` this loop does nothing, which
    // is every raid.
    // The fight's MIDPOINT (raid 12's farmer mob, raid 13's captain): a unit waiting on a
    // share of the wave gets its clock set the moment that share is down, and from then on
    // it is an ordinary `deployAtMs` unit — off the drip, on its own beat.
    if (this.enemies.some((e) => e.deployAtWaveFrac !== null && e.deployAtMs === null && e.alive)) {
      const body = this.enemies.filter((e) => e.waveBody);
      const frac = body.length ? body.filter((e) => !e.alive).length / body.length : 1;
      for (const e of this.enemies) {
        if (e.deployAtWaveFrac === null || e.deployAtMs !== null || !e.alive) continue;
        if (frac >= e.deployAtWaveFrac) e.deployAtMs = this.elapsed;
      }
    }
    for (const e of this.enemies) {
      if (e.deployAtMs === null || !e.alive || e.state !== "queued") continue;
      if (this.elapsed < e.deployAtMs) continue;
      e.state = "emerging";
      // The captain's entrance (raid 13): a smoke bomb pushes the army back to give him room.
      if (e.chargeCfg && this.duel) this.smokeBomb();
    }
    // A support defender alone at the back would stand past the attackers' reach and
    // run the fight to the four-minute cap. Drop its station so it walks up to the
    // ordinary doorway, where every raid's enemies are fought — the fight can end.
    const standing = this.enemies.filter((e) => e.alive && !e.isSummon && !e.isTurned);
    if (standing.length === 1 && standing[0].defenseRole === "support" &&
        standing[0].stationX !== null) {
      standing[0].stationX = null;
      if (standing[0].state === "hold") standing[0].state = "emerging";
    }

    const activeMelee = this.enemies.filter(
      (e) => e.alive && !e.isBoss && !e.isWall && !e.isSummon &&
        e.deployAtMs === null && e.state !== "queued"
    ).length;
    // A mini still waiting in the barn is ammunition, not a defender holding the line:
    // counting it here would hold the brute on its perch forever, since the very thing
    // that releases the mini is the brute climbing down.
    const normalsLeft = this.enemies.some(
      (e) => !e.isBoss && !e.isWall && !e.isSummon && e.alive &&
        !(e.deployWithBoss && e.state === "queued")
    );
    // A standing WALL deliberately does not hold the boss on its perch (ruleset 47).
    // It used to: with the wave dead and only the carrotWall/junkWall left, the boss sat
    // up top — untargetable, still throwing — while the army chewed 1500 hp of wall, and
    // any zombie already past the wall when it was cast (`passedWall`) had no target at
    // all: it stood idle under fire until the player hand-tapped the wall down. The boss
    // now comes down once the MINIONS are cleared; the wall still stands and still bars
    // un-passed zombies, and no replacement follows the boss down — every boss action is
    // perch-gated in canPerform.

    // While the captain is out the wave STANDS DOWN (raid 13) — nobody new walks on.
    if (activeMelee < this.activeTarget && !this.captainOut()) {
      const next = this.enemies.find(
        (e) => e.alive && !e.isBoss && e.deployAtMs === null && e.deployAtWaveFrac === null &&
          e.state === "queued" && !e.deployWithBoss
      );
      if (next) next.state = "emerging";
    }

    // WHEN the perched unit comes down. A raid boss waits for its whole wave to be
    // cleared. A PvP formation BRUTE comes down as soon as the ground line is gone —
    // every defender still standing is a healer, or nobody is standing at all — because
    // the Garden zombie cannot hold a line and leaving the brute up there while it is
    // farmed just parks the defense's best fighter somewhere unreachable.
    //
    // A line reinforcement still waiting on the drip HOLDS THE BRUTE UP even though it
    // is not on the ground yet (owner, 2026-09-09). It used to read who was standing
    // only, and that had the brute-heavy defenses opening with no perch phase at all: a
    // farm with no Headless has nobody but the healer on the lawn at the bell — the
    // Normal and Girl are still queued for their PVP_DEFENSE_DRIP_MS beats — so the descent
    // condition was already true on tick one and the brute walked its mini straight out
    // of the barn. The gate is now the LINE: the brute comes down once the tank and both
    // reinforcements are dead, whether they got to stand or not. It still never waits on
    // the healer, and never on the mini (the descent is what releases it).
    const bruteHolds = this.boss?.defenseRole === "brute"
      ? this.enemies.some((e) => e.alive && !e.isBoss && !e.isWall && !e.isSummon &&
          e.defenseRole !== "support" &&
          (e.state !== "queued" || isLineRole(e.defenseRole)))
      : normalsLeft || activeMelee > 0;
    // THE RINGMASTER DOES NOT WAIT (raid 14, rung 5+). Every other boss comes down when
    // its wave is gone, which means the player meets it on an empty field — and this one
    // fight is about not being able to be in two places at once, so a boss that politely
    // queues behind its own minions removes the whole point. His clock overrides the
    // gate; nothing else in the game sets one.
    let dropsOnTheClock = this.bossDropAtMs !== null && this.elapsed >= this.bossDropAtMs;
    // Raid 14: and only once the front line has formed behind his station (or at the latest).
    if (dropsOnTheClock && this.bigTop && this.elapsed < this.bigTop.dropLatestMs) {
      const past = this.players.filter((p) => p.alive && !p.taken && p.x > this.bigTop!.stationX).length;
      dropsOnTheClock = past >= this.bigTop.dropAfterPast;
    }
    if (this.boss && this.boss.alive && this.boss.state === "structure"
        && (!bruteHolds || dropsOnTheClock)) {
      // Climb down, exit out the back, then re-enter. An authored PERCH is dropped
      // here: from now on this is a ground unit, and keeping the station would walk
      // it back to a spot up in the air.
      //
      // …unless the fight names a GROUND station for it, which the ringmaster does: he
      // lands mid-lane and fights there rather than joining the line, and `anchorsLine`
      // stays false so the army does not march back to meet him.
      if (this.bossGroundStationX !== null) {
        this.boss.stationX = this.bossGroundStationX;
        this.boss.stationY = CENTER_Y;
        this.boss.anchorsLine = false;
        this.boss.state = "descending";
        for (const e of this.enemies) {
          if (e.deployWithBoss && e.alive && e.state === "queued") e.state = "emerging";
        }
        return;
      }
      this.boss.stationX = null;
      this.boss.stationY = null;
      this.boss.state = "descending";
      // The brute brings its ammunition down with it — the mini stops being a thrown
      // projectile and joins the fight on foot. (The scripted Mini Buddy mount, when
      // the brute has that ability, is still to come; today they simply arrive together.)
      for (const e of this.enemies) {
        if (e.deployWithBoss && e.alive && e.state === "queued") e.state = "emerging";
      }
    }
  }

  /** The army's line follows the FRONT-MOST defender.
   *
   *  `frontX` is normally a constant — every raid's wave holds at the same doorway, so
   *  `ENEMY_HOLD_X - engageDistance` is where the zombies stop. A formation defense
   *  breaks that assumption: its tank stands well forward of the barn, and an army
   *  anchored on the doorway would walk straight PAST it to a line behind its back.
   *
   *  So when stations are authored the line is re-derived from the front-most station
   *  still held by a live defender. It reads STATIONS rather than live positions on
   *  purpose: a reinforcement still walking in would otherwise drag the line around
   *  behind it. When the tank falls, the next station forward becomes the line and the
   *  army pushes up — which is the behaviour you want anyway. */
  private refreshFrontLine(): void {
    if (!this.authoredStations) return;
    const holdX = this.bossFallsFromSky ? EPIC_BOSS_HOLD_X : ENEMY_HOLD_X;
    let front = holdX;
    for (const e of this.enemies) {
      // The perched brute is up in the air and unreachable until it climbs down, so
      // it must never pull the army's line forward onto a position it cannot fight.
      if (!e.alive || e.isSummon || e.isTurned || e.isBoss) continue;
      // Same reasoning as the perched brute: a mini still in the barn is unreachable.
      if (e.deployWithBoss && e.state === "queued") continue;
      // A hazard parked mid-lane is not a line to be met — walking the army up to it would
      // undo the distance it was dropped at. See SimUnit.anchorsLine.
      if (!e.anchorsLine) continue;
      front = Math.min(front, e.stationX ?? holdX);
    }
    this.frontX = front - this.engageDistance;
  }

  /** Where this enemy stands once it has walked in: its authored station if it has
   *  one (PvP formation defense), otherwise the shared doorway every raid uses. */
  private holdXOf(e: SimUnit): number {
    if (e.stationX !== null) return e.stationX;
    return this.bossFallsFromSky ? EPIC_BOSS_HOLD_X : ENEMY_HOLD_X;
  }

  /** Which row bucket a zombie falls in — `calculateDestinationPoint` dispatches on the
   *  concrete ZombieActor subclass, and a Cupid Garden buckets with Small, not Garden.
   *
   *  The source's `Small` bucket is folded into `Regular` here on purpose; see
   *  MINI_STANDS_WITH_REGULAR above. That takes the Cupid Gardens with it, since they
   *  bucket with Small rather than with Garden. */
  private bodyOf(p: SimUnit): string {
    if (/Cupid/i.test(p.sourceKey)) return "Regular";
    if (p.isHeadless) return "Headless";
    if (p.isGarden) return "Garden";
    const g = p.group ?? "";
    if (BODY_ROW_ORDER.includes(g)) return g;
    return "Regular"; // includes every Small: a Mini queues with the ordinary bodies
  }

  /** Build the authoritative line order. Ordinary zombies are FIFO by release
   *  (`formOrder`). Knockback and resurrection assign a fresh order at the tail. An active
   *  Headless priority overrides FIFO and puts that zombie at the very front; among
   *  Headless zombies, the newest arrival is first because it pushes into position zero.
   *
   *  A zombie still WALKING IN (`!inLine`) ranks behind everyone already standing,
   *  whatever its priority or order: it has no place in the line until it gets there,
   *  and takes its release-order place — pushing in ahead of later releases, a Headless
   *  ahead of everyone — only on arrival. Before v52 it was ranked at once: a Headless
   *  crossing the field (from the charge slot, or revived at the rear) held slot zero for
   *  the whole walk, so the standing row re-slotted a body standoff BACK to leave its
   *  spot open, out of the wave's melee reach, for as long as the walk took (seven
   *  seconds for a dex-1 Headless). Reported as zombies "reserving spots for themselves
   *  while walking in" with the enemy standing in front of an empty slot. Now the row
   *  keeps the line and the newcomer pushes its way in when it gets there — the same
   *  final formation, without the hole. Release order (not arrival order) stays the
   *  rank so a fast body released later never overtakes one sent ahead of it — the Mini
   *  rule (MINI_STANDS_WITH_REGULAR) depends on that. */
  private armyOrder(): SimUnit[] {
    // `!p.taken`: a zombie carried out of the fight (a crab's passenger, a zombie
    // Zedzox has converted) keeps whatever state it was in, and it used to keep its
    // SLOT too. The ghost anchored its row from the front — a Headless leads its row,
    // and the front fighter is exactly the zombie `turnZombie` takes — so the
    // survivors re-slotted BEHIND a unit that was no longer on the field, one
    // body-standoff short of the wave's reach, and the enemies held with nothing in
    // range for the rest of the fight ("the enemies stop attacking when my headless
    // becomes the pixel zombie").
    const committed = this.players
      .filter((p) => p.alive && !p.taken && (p.state === "advance" || p.state === "fight"))
      .sort((a, b) => {
        if (a.inLine !== b.inLine) return a.inLine ? -1 : 1;
        if (a.frontPriority !== b.frontPriority) return a.frontPriority ? -1 : 1;
        return a.frontPriority
          ? b.formOrder - a.formOrder
          : a.formOrder - b.formOrder;
      });
    return committed;
  }

  /** Place the army. Band and slot both come directly from the authoritative line order;
   *  body geometry may add spacing, but it may never let a later arrival overtake an
   *  earlier one. */
  private assignFormation() {
    const order = this.armyOrder();
    // KNOWN STALL, NOT FIXED HERE. A Garden zombie holds GARDEN_STATION_X out of the
    // combat zone, which is right while it has somebody to support — and a dead end when
    // the healers are the only survivors: measured on raid 15, four Gardens stood at x 250
    // from second 120 to the four-minute cap while twelve enemies stood at the doorway,
    // neither side able to touch the other. Not a loss, a `truncated_transcript`.
    //
    // The obvious fix — let a Garden take an ordinary slot once every survivor is a Garden
    // — was tried and reverted: it walks the last medic into a blocker, and `stepResurrect`
    // refuses a healer with a wall in its way, so the army loses the revives that were its
    // way back. alienStage.test.ts catches exactly that. The real answer is probably in
    // `wallInWay`'s treatment of a stationed healer rather than in the formation, and it
    // belongs to the balance pass with a measurement behind it.

    // Lineup index = index in the army array. It drives the damage and cadence falloff
    // bands (combatStats), and now the formation reads from the SAME index, so the visible
    // rank and the band a zombie is punished for finally agree.
    //
    // v68: the stationed supports (`isGarden`) are NOT part of that count. They hold
    // GARDEN_STATION_X out of the combat zone and never stand in a row, but they used to
    // take array indices all the same — so five Gardens sent first filled band 0 and
    // pushed every fighter behind them into band 1: the damage/cadence falloff, and (v40)
    // the enemy's reach of last resort, which only touches the front band. "The Gardens
    // occupy the first five front-row positions" (issue 10). The line now counts only its
    // own fighters, and the supports are numbered among themselves.
    const line = order.filter((p) => !p.isGarden);
    const supports = order.filter((p) => p.isGarden);
    this.placeRows(line);
    this.placeRows(supports);
  }

  /** Number one group front to back (`lineupIndex`, the damage band) and stand it in
   *  rows of BAND_SIZE. See assignFormation, which calls this once for the fighting line
   *  and once for the stationed supports. */
  private placeRows(order: SimUnit[]) {
    order.forEach((p, i) => {
      p.lineupIndex = i;
    });

    for (let start = 0; start < order.length; start += BAND_SIZE) {
      const band = start / BAND_SIZE;
      const members = order.slice(start, start + BAND_SIZE);
      const row = members;
      const n = row.length;
      // Source x is absolute off `zombieAttackPosition`; ours hangs off `frontX`, which is
      // derived from the raid's own hold position. Normalising on the row's front-most
      // member keeps band 0's leading slot exactly ON the old line, so the recovered
      // standoff/fan only ever adds depth BEHIND it and never pushes the whole army out of
      // contact.
      const rel = (p: SimUnit, slot: number) =>
        -(SRC_BODY_STANDOFF[this.bodyOf(p)] ?? 0) * SIM_PER_SOURCE_X + (n - 1 - slot) * SLOT_X_STEP;
      const bandX = this.frontX - band * BAND_GAP;
      const rels: number[] = [];
      for (let slot = 0; slot < row.length; slot++) {
        const authored = rel(row[slot], slot);
        // Body-specific standoff values are spacing hints, not another ordering system.
        // Clamp each later slot behind its predecessor so FIFO stays true on screen and
        // in `playerInRange`, which selects the physically front-most zombie.
        rels.push(slot === 0 ? authored : Math.min(authored, rels[slot - 1] - SLOT_X_STEP));
      }
      // Anchor the row on the front-most member that has actually REACHED the line —
      // not on one still walking in from the charge slot. See ROW_ANCHOR_EPS.
      const standing = rels.filter((_, i) => row[i].x >= bandX - ROW_ANCHOR_EPS);
      const relMax = Math.max(...(standing.length ? standing : rels));
      row.forEach((p, slot) => {
        // A healer keeps its station EXACTLY — no band gap, no row fan. Those terms are
        // relative to a front line it is not part of, and they dragged it ~36 units off
        // the mark. Gardens share the one x and are separated by `slotY` below.
        //
        // The `min` only bites for a zombie still crossing that outranks everyone
        // standing: with the row anchored behind it, its own offset comes out NEGATIVE
        // (a slot in front of the line). It walks to the line instead, and takes the
        // anchor with it when it gets there.
        p.slotX = p.isGarden
          ? GARDEN_STATION_X
          : Math.min(bandX, bandX - (relMax - rels[slot]) * this.rowXFit);
        // Source: y = 4*slot - 2*n + 10, whose midpoint is y=8 for ANY n. Two adjustments:
        // we hang the row off the lane centre instead of the stage's y origin (so the +10
        // becomes +2 — the formula minus its own fixed centre — and the block stays centred
        // as the row fills), and the sign FLIPS because cocos2d y grows upward while this
        // sim's grows downward. Slot 0 therefore takes the largest y, i.e. nearest the
        // camera and drawn in front, which is what the source's explicit zOrder does too.
        // ROW_SPREAD widens the whole step for legibility; see its note.
        p.slotY = CENTER_Y
          - (SLOT_Y_STEP * slot - (SLOT_Y_STEP / 2) * n + 2 * SIM_PER_SOURCE_Y) * ROW_SPREAD;
      });
    }
  }

  /** Advance the sim by `dtMs`. Returns false once the battle is over. */
  step(dtMs: number): boolean {
    if (this.finished) return false;
    this.elapsed += dtMs;
    this.projectileImpactsThisTick = 0;
    this.lastProjectileImpactSprite = "";
    for (const u of this.units) {
      u.struckThisTick = false;
      u.walkingThisTick = false;
      u.prevX = u.x; // snapshot for this step's velocity measurement (see below)
      u.prevY = u.y;
    }
    for (const g of this.grabbers) g.struckThisTick = false;
    // Before anything moves: the clock may just have closed an objection slot, and a
    // zombie barred by it has to start walking off on this tick rather than the next.
    this.stepSign();
    // Towers climb (and record a topple) before anything swings, so a stack that just
    // lost a level swings at its new height on the same tick it lost it.
    this.stepStacks(dtMs);
    this.stepBubble(dtMs);

    this.promote(dtMs);
    this.stepDuel(dtMs);
    this.refreshTeamAuras();
    this.stepEnrage(dtMs);

    // Throws and specials draw from ONE action budget (ground truth: the boss rolls a
    // single weighted pick over `bossActions` per cycle — see stepBossActions).
    this.stepBossActions(dtMs);
    this.stepBossMagic(dtMs);
    this.stepMedusa(dtMs);
    this.stepEndlessMechanics(dtMs);
    this.stepGrabbers(dtMs);
    this.stepBigTop(dtMs);
    this.stepCrabs(dtMs);
    this.stepMegaBot(dtMs);
    this.stepProjectiles(dtMs);

    this.assignFormation();
    this.stepHealing(dtMs, this.stepResurrect());
    // The DEFENDER's own support pass. Only a PvP formation defense carries healing
    // abilities on the enemy side (raid enemies are authored with none), so this is a
    // no-op everywhere else. Resurrect is deliberately NOT mirrored: it draws on the
    // player-side corpse backlog, and a defender backlog is its own piece of work.
    this.stepHealing(dtMs, this.fallenDefenders.length ? this.stepDefenderResurrect() : EMPTY_CAST, this.enemies);
    const frontX = this.frontX;

    // Zombies.
    for (const p of this.players) {
      if (!p.alive) continue;
      // Carried out of the fight — by a crab, or converted into a pixel zombie. Still
      // alive and still a survivor, but it neither walks nor swings until it is back.
      if (p.taken) continue;
      // The fire burns on a WALL CLOCK, so it is ticked ahead of every other gate —
      // including the trapeze's. The trapeze and crab are client-only, so a burn the
      // client paused while a zombie dangled would run out earlier on the server; ticking
      // it here keeps the burn bit-identical on both sides whatever the hazards do.
      this.stepBurn(p, dtMs);
      this.stepDot(p, dtMs);
      if (!p.alive) continue; // the burn can be the killing blow
      if (p.blockMs > 0) p.blockMs = Math.max(0, p.blockMs - dtMs);
      if (p.phaseMs > 0) p.phaseMs = Math.max(0, p.phaseMs - dtMs);
      if (p.abilities.includes("shieldBar") && (p.state === "advance" || p.state === "fight")) {
        p.shield = Math.min(p.maxHp, p.shield + (p.maxHp * SHIELD_REGEN_FRAC_PER_SEC * dtMs) / 1000);
      }
      if (p.state === "grabbed") continue; // seized by the trapeze — position driven by stepGrabbers
      if (p.abilityCdMs > 0) p.abilityCdMs -= dtMs; // activated-move recharge
      switch (p.state) {
        case "waiting": {
          // Idle in the back group: stand STILL most of the time, with only an
          // occasional brief shuffle to a nearby spot — so the crowd looks alive
          // without the old constant pacing. Deterministic (cycle-indexed hash, no
          // RNG): each zombie holds a spot for ~85% of its cycle, then eases a few
          // px to the next spot in the last ~15%. No vertical hover.
          const off = p.mill / (Math.PI * 2); // 0..1 per-unit phase
          const period = 2600 + off * 2200; // 2.6-4.8s per shuffle cycle
          const raw = this.elapsed / period + off;
          const cyc = Math.floor(raw);
          const ph = raw - cyc; // 0..1 within the cycle
          const MOVE_FRAC = 0.12; // only the last 12% of the cycle is a shuffle
          const AMP = 14; // shuffle reach in sim px (was a ±26 constant pace) — big
          // enough that the brief shuffle clears the walk-anim threshold (a real
          // step, not a glide), while the long still stretch keeps them planted
          const spot = (c: number) => (hash(c * 1.73 + p.mill) - 0.5) * 2 * AMP;
          const from = spot(cyc);
          let d = from;
          if (ph > 1 - MOVE_FRAC) {
            const t = (ph - (1 - MOVE_FRAC)) / MOVE_FRAC; // 0..1 across the shuffle
            const e = t * t * (3 - 2 * t); // smoothstep ease
            d = from + (spot(cyc + 1) - from) * e;
          }
          p.x = p.homeX + d;
          p.y = p.homeY;
          break;
        }
        case "charging": {
          // Step out to the staging slot (in front of the group) and focus.
          const dx = CHARGE_X - p.x;
          const dy = CENTER_Y - p.y;
          const d = Math.hypot(dx, dy);
          const stepd = (STEP_SPEED * dtMs) / 1000;
          if (d > 2) {
            p.x += (dx / d) * Math.min(stepd, d);
            p.y += (dy / d) * Math.min(stepd, d);
            p.timerMs = this.cycleMs(p, null);
          } else {
            this.stepCharge(p, dtMs);
          }
          break;
        }
        case "carried": {
          p.buddyMountMs = Math.max(0, p.buddyMountMs - dtMs);
          p.timerMs = this.cycleMs(p, null);
          break;
        }
        default: {
          // Being shoved: the slide owns the zombie's position, and it is out of melee for
          // the duration (`movementUpdate:` returns before the walk, and a live
          // knockBackPoint makes `isInMeleeRange` false). Checked BEFORE the stun so a
          // knockback attack that also stuns still travels — the source parks the point on
          // fightData and slides it regardless of what else the hit applied.
          if (this.stepKnockBack(p, dtMs)) break;
          // Stunned by an enemy hit — can't move or attack until it wears off.
          if (p.stunMs > 0) {
            p.stunMs -= dtMs;
            p.timerMs = this.cycleMs(p, null);
            break;
          }
          // On fire: the zombie is beating at itself, not fighting. It holds no formation
          // slot and lands no swings — it just paces on the spot until the fire goes out
          // or the player taps it out. Checked after the shove and the stun so neither is
          // swallowed by the fire (a burning zombie can still be knocked back or held).
          if (p.burnMs > 0) {
            if (p.burnWalk) this.walkBurning(p, dtMs);
            else this.pacePanicked(p, dtMs);
            p.timerMs = this.cycleMs(p, null);
            break;
          }
          // Benched by the placard: no advance, no attack, no laser — it is walking away.
          // Same shape as the panic above, and for the same reason: everything this branch
          // skips is everything a zombie out of the fight should not be doing.
          if (this.isSigned(p)) {
            this.walkOffSigned(p, dtMs);
            p.timerMs = this.cycleMs(p, null);
            break;
          }
          // Move to the assigned formation slot (never past the enemy).
          //
          // …EXCEPT while carrying a Mini Buddy, which is a RAM and not a march. A brute
          // with a mini aboard drives at the enemy line rather than to its own slot: the
          // move is "it runs forward and stuns what it hits", and a Large's slot is the
          // furthest back of any body type (v23 gave each body its own standoff), so
          // aiming at the slot stopped the charge well SHORT of the enemy — measured on a
          // real party: it halted 72 units behind its own front rank and stunned a knight
          // 162 units away that it had never reached. The stun looked like it fired at
          // random from across the field, because effectively it did.
          // Teleport (the Secret Boss Zombie): the walk in is skipped. It appears at its place
          // in the line, past any wall on the way. Deploying is otherwise ordinary: it waited
          // its turn and charged like everyone else. A Mini Buddy carrier rams instead.
          //
          // It waits for a slot AHEAD of it: a revive lands after this tick's formation pass
          // (stepResurrect runs after assignFormation), so on that tick the slot is the one it
          // died in, or the charge slot a revive resets it to. It jumps on the next tick, once
          // the formation has placed it. Reaching the line any other way disarms it.
          if (p.teleportPending && p.inLine) p.teleportPending = false;
          if (p.teleportPending && p.slotX > p.x + 1) {
            p.teleportPending = false;
            if (!p.buddyId) {
              p.x = p.slotX;
              p.y = p.slotY;
              p.prevX = p.x;
              p.prevY = p.y;
              p.teleportFxSeq++;
            }
          }
          const blockingWall = this.wallInWay(p);
          const ramTarget = p.buddyId ? this.ramTargetFor(p) : null;
          const slotX = ramTarget ? ramTarget.x - this.engageDistance : p.slotX;
          const destinationX = blockingWall
            ? Math.min(slotX, blockingWall.x - this.blockerGap(blockingWall))
            : slotX;
          const mdx = destinationX - p.x;
          const mdy = p.slotY - p.y;
          const md = Math.hypot(mdx, mdy);
          const wasWalking = md > 2;
          const stepd = (p.moveSpeed * (p.buddyId ? MINI_CARRIER_SPEED_MULT : 1) * dtMs) / 1000;
          if (md > stepd) {
            p.x += (mdx / md) * stepd;
            p.y += (mdy / md) * stepd;
          } else {
            p.x = destinationX;
            p.y = p.slotY;
          }
          p.walkingThisTick = wasWalking;
          // The laser is the weapon of the approach: it fires while its owner WALKS and
          // falls silent once it arrives. A Garden holder is the exception (v50): it
          // walks to a station outside the combat zone and stays there healing, so the
          // walking rule would give it a beam it fires for a few seconds and never again.
          // A support zombie fires from wherever it stands — walking or stationed —
          // for as long as one of its own is ahead of it to shoot over.
          if (p.isGarden ? this.zombieAhead(p) : wasWalking) this.stepLaser(p, dtMs);
          // The formation is only for spacing / projectile hitboxes — EVERY zombie
          // that has reached the combat zone attacks the enemy once it has arrived
          // (not just the front row). The enemy still only strikes those in melee
          // range (the front), so front-row / headless zombies take the hits.
          const foe = this.targetEnemy(p);
          const enemyArrived = !!foe && (foe.state === "hold" || foe.state === "fight");
          const inCombatZone = p.x >= frontX - COMBAT_ZONE_DEPTH;
          const atSlot = Math.hypot(destinationX - p.x, p.slotY - p.y) <= 2;
          // Arrival. Until now this zombie was ranked behind everyone standing and walked
          // to a place at the tail of the line; from here it holds its real place, by
          // release order (a Headless pushes to the front — see armyOrder). Not while
          // parked short of its slot at a blocking wall: that is not the line, and a
          // Headless stuck behind a wall must not pull the row back to make room for it
          // at the front.
          if (!p.inLine && atSlot && !blockingWall) p.inLine = true;
          // Knockback and carry/drop effects send a Headless zombie to the rear long
          // enough for another row to fill the open front slot. Once it reaches that
          // recovery slot, restore its defining behavior: it pushes forward again.
          if (p.isHeadless && !p.frontPriority && atSlot) p.frontPriority = true;
          // The ram lands on CONTACT with the thing it charged, not on arrival at a slot.
          // `atSlot` is kept as a backstop so a carrier whose target dies mid-charge (or
          // that is walled off short of it) still puts its passenger down instead of
          // running around with it for the rest of the fight.
          if (p.buddyId && enemyArrived) {
            const reached = Math.abs(foe!.x - p.x) <= this.engageDistance + 2;
            if (reached || atSlot) this.deployMiniBuddy(p, foe);
          }
          const atBlockingWall = !!blockingWall &&
            Math.abs(blockingWall.x - p.x) <= this.blockerGap(blockingWall) + 2;
          // A Garden fights only what is on top of it; otherwise it holds its station.
          const gardenInReach = p.isGarden && !!foe && Math.abs(foe.x - p.x) <= this.engageDistance + 2;
          if (foe && enemyArrived && (inCombatZone || atBlockingWall || gardenInReach)) {
            p.state = "fight";
            // A charging zombie makes no normal attacks — it's winding up the big
            // hit; deliver the payoff when the wind-up fills. Otherwise attack.
            if (p.windupKey) this.stepWindup(p, foe, dtMs);
            else this.tryAttack(p, foe, dtMs);
          } else {
            p.state = "advance";
            // A lit Explode fuse burns down wherever the zombie is and whether or not
            // anything is standing in front of it — that is the whole point of being
            // able to light it early. Every OTHER wind-up is a swing at a specific foe,
            // so it still waits for one (the bash family keeps its charge held).
            if (ACTIVATED_ABILITY[p.windupKey ?? ""]?.suicide) this.stepWindup(p, null, dtMs);
            else p.timerMs = this.cycleMs(p, null);
          }
        }
      }
    }

    // Enemies (emerge / boss descends, then stand and strike; never move otherwise).
    for (const e of this.enemies) {
      if (!e.alive || e.state === "queued" || e.state === "structure") continue;
      // A PvP defender's timed abilities (raid enemies carry none).
      if (e.phaseMs > 0) e.phaseMs = Math.max(0, e.phaseMs - dtMs);
      if (e.abilities.includes("shieldBar") && (e.state === "hold" || e.state === "fight")) {
        e.shield = Math.min(e.maxHp, e.shield + (e.maxHp * SHIELD_REGEN_FRAC_PER_SEC * dtMs) / 1000);
      }
      if (e.isWall) {
        e.state = "hold";
        e.timerMs = this.cycleMs(e, null);
        continue;
      }
      // The defender's beam, before any state branch: it fires from the station it is
      // standing on, while it is walking to that station, and while it is fighting. What
      // gates it is whether anyone is still WALKING IN, not what this unit is doing.
      this.stepDefenderLaser(e, dtMs);
      // The pirate captain's slam charge, likewise before the state branches: it is his own
      // clock, and it has to keep running through the ticks his ordinary attack cycle does
      // nothing on. No-op for every unit without a charge config, which is all of them
      // outside raid 13.
      this.stepSlamCharge(e, dtMs);

      if (e.state === "falling") {
        e.y = Math.min(CENTER_Y, e.y + (EPIC_BOSS_FALL_SPEED * dtMs) / 1000);
        e.timerMs = this.cycleMs(e, null);
        if (e.y >= CENTER_Y) {
          e.y = CENTER_Y;
          e.state = "landing";
          e.timerMs = EPIC_BOSS_LAND_MS;
        }
        continue;
      }
      if (e.state === "landing") {
        e.timerMs -= dtMs;
        if (e.timerMs <= 0) {
          e.state = "hold";
          e.timerMs = this.cycleMs(e, null);
        }
        continue;
      }
      if (e.state === "descending") {
        if (e.sourceKey === CIRCUS_BOSS_KEY) {
          // The Ringmaster jumps straight down from the circus car instead of using
          // the generic boss route (walk out behind the structure, then re-enter).
          // Keep progress in the existing x/y fields so snapshots and replays need
          // no raid-specific animation state.
          //
          // He lands on his STATION rather than on the doorway, which is the same thing
          // for raid 8 (no station, so `holdXOf` answers the doorway) and the whole point
          // for raid 14, where the rung drops him into the middle of the field. Without
          // it he jumped down and then stood at the doorway like any other boss, station
          // or no station — measured in the Raid Lab at x 940 with `stationX` 640.
          const landX = this.holdXOf(e);
          const dy = CENTER_Y - BOSS_STRUCT_Y;
          e.y = Math.min(CENTER_Y, e.y + (dy * dtMs) / BOSS_JUMP_MS);
          const t = clamp((e.y - BOSS_STRUCT_Y) / dy, 0, 1);
          e.x = BOSS_STRUCT_X + (landX - BOSS_STRUCT_X) * t;
          e.timerMs = this.cycleMs(e, null);
          if (e.y >= CENTER_Y) {
            e.x = landX;
            e.y = CENTER_Y;
            e.state = "hold";
            // Raid 14: he stands in the MIDDLE as a blocker. Whoever is already past him does
            // not turn round; whoever walks out later stops and fights him.
            if (this.bigTop && e === this.boss) {
              e.isBlocker = true;
              for (const p of this.players) {
                if (p.alive && p.x > e.x + 0.5) p.passedBlockers.push(e.id);
              }
            }
          }
          continue;
        }
        // Leave the perch by heading OUT THE RIGHT SIDE (through the entrance),
        // staying up at structure height; the renderer slides it off-screen behind
        // the structure. Only once fully off-screen does it drop to the ground and
        // re-enter — no floating diagonally toward the middle.
        const sx = (EMERGE_SPEED * dtMs) / 1000;
        e.x = Math.min(ENEMY_SPAWN_X, e.x + sx); // walk out to the hidden spawn
        e.timerMs = this.cycleMs(e, null);
        if (e.x >= ENEMY_SPAWN_X) {
          e.x = ENEMY_SPAWN_X;
          e.y = CENTER_Y; // now a ground unit, hidden off the right edge
          e.state = "emerging"; // walk back in from the entrance, facing the zombies
        }
        continue;
      }
      if (e.state === "emerging") {
        // Re-enter from the right at ground level and walk left to the hold spot —
        // exactly where the normal enemies attack from, unless this defender was
        // authored a station of its own (PvP formation defense).
        const holdX = this.holdXOf(e);
        // A PvP defender's Teleport skips the walk to its station; Turbo doubles it.
        if (e.abilities.includes("teleport") && e.x > holdX) {
          e.x = holdX;
          e.prevX = e.x;
          e.teleportFxSeq++;
        }
        const sx = (EMERGE_SPEED * (e.abilities.includes("turboSpeed") ? 2 : 1) * dtMs) / 1000;
        e.x = Math.max(holdX, e.x - sx);
        e.y = e.stationY ?? CENTER_Y;
        e.timerMs = this.cycleMs(e, null);
        if (e.x <= holdX) {
          e.x = holdX;
          e.y = e.stationY ?? CENTER_Y;
          e.state = "hold";
        }
        continue;
      }
      // The stand-down (raid 13): while the captain is out, the rest of the wave steps back
      // behind the doorway and waits. It does not swing and is not a target.
      if (this.standsDown(e)) {
        const holdX = this.holdXOf(e) + (this.duel?.standDownX ?? 0);
        e.x = Math.min(holdX, e.x + (EMERGE_SPEED * dtMs) / 1000);
        e.state = "hold";
        e.timerMs = this.cycleMs(e, null);
        continue;
      }
      // Stunned (by an Explode) — can't act; hold its attack clock.
      if (e.stunMs > 0) {
        e.stunMs -= dtMs;
        // Invasions restart the swing from scratch, so ANY stun, however short, costs a whole
        // attack cycle — enough stunners lock an enemy out for the entire fight. Endless
        // (owner, 2026-11-11, ruleset 85) PAUSES the clock instead: a stun costs exactly its
        // length, so its depth-shortened stuns (ENDLESS_STUN_RESIST_PER_TIER) really are
        // shorter, and a stun army stays strong without a permanent lock.
        if (!this.endlessMechanics) e.timerMs = this.cycleMs(e, null);
        continue;
      }
      const foe = this.bigTop && e === this.boss ? this.whipTarget(e) : this.playerInRange(e);
      if (foe) {
        e.state = "fight";
        // A channelled move (the Video Games dragon's gout, ruleset 92): no ordinary swings
        // while it winds up, nor through its lockout after. It still stands and engages.
        if (e.chargeCfg?.channel && (e.chargeMs > 0 || e.chargeLockMs > 0)) e.timerMs = this.cycleMs(e, null);
        else this.tryAttack(e, foe, dtMs);
      } else {
        e.state = "hold";
        e.timerMs = this.cycleMs(e, null);
      }
    }

    // Measure each unit's velocity from this step's movement (for boss-throw lead).
    // A big jump is a teleport (knockback re-slot, boss perch↔ground) not real motion —
    // zero it so a throw doesn't lead a phantom high-speed vector.
    const dtSec = dtMs / 1000;
    if (dtSec > 0) {
      for (const u of this.units) {
        const ddx = u.x - u.prevX;
        const ddy = u.y - u.prevY;
        if (Math.hypot(ddx, ddy) > TELEPORT_PX) {
          u.vx = 0;
          u.vy = 0;
        } else {
          u.vx = ddx / dtSec;
          u.vy = ddy / dtSec;
        }
      }
    }

    const wiped = !this.anyAlive(this.players);
    const cleared = !this.anyAlive(this.enemies);
    // Only healers left (owner, 2026-09-27): a station Garden cannot damage anything — its
    // laser needs a zombie ahead to fire over — so an army down to its Gardens has lost; it
    // used to stand at the station until the clock ran out, minutes later.
    const healersOnly = !wiped && !cleared && this.healersOnly();
    if (healersOnly) this.healersOnlyEnd = true;
    if (wiped || cleared || healersOnly || this.elapsed >= this.fightClockMs) {
      // Decided beats expired: an army that clears the last enemy ON the final tick has
      // won, and one wiped out on it has lost the ordinary way. Out of time is only what
      // is left over — both sides still standing when the clock stops.
      this.outOfTime = !wiped && !cleared && !healersOnly;
      this.finished = true;
    }
    return !this.finished;
  }

  /** Throw wind-up for the renderer's perched-boss throw animation: 0..1 filling over
   *  the last `windowMs` before the next throw releases (the arm cocks and swings), or
   *  null when the boss isn't perched-and-throwing / has no target. The projectile
   *  launches as this reaches 1, so the renderer can time the arm to the release. */
  bossThrowSwing(windowMs = THROW_WINDUP_MS, visualLeadMs = 0): number | null {
    if (!this.bossThrow || !this.boss || !this.boss.alive || this.boss.state !== "structure") {
      return null;
    }
    if (this.isCastingWall()) return null;
    if (this.nextAction?.kind !== "throw") return null; // a special is up next — arm rests
    if (!this.throwTarget()) return null; // empty lane → arm rests
    const visualTimer = Math.max(0, this.actionCd - visualLeadMs);
    if (visualTimer > windowMs) return 0;
    return clamp(1 - visualTimer / windowMs, 0, 1);
  }

  private isCastingWall(): boolean {
    return this.pendingSpecial?.name === "wall";
  }

  /** Progress of the wall-summoning pose. This replaces the normal throw swing
   *  throughout the wall action's authored cast time. */
  bossWallSummonProgress(): number | null {
    const sp = this.pendingSpecial;
    if (!sp || sp.name !== "wall") return null;
    return clamp(1 - this.specialCast / Math.max(1, sp.castMs), 0, 1);
  }

  /** Whether the boss is "active" (able to throw / cast specials): alive and either
   *  perched on its structure or fighting on the ground (not descending/queued). */
  private bossActive(): boolean {
    const b = this.boss;
    return !!b && b.alive && (b.state === "structure" || b.state === "hold" || b.state === "fight");
  }

  /** Round countdown → enrage. When the timer expires the boss enrages once: throws
   *  come faster, specials recover faster, and its melee hits harder. */
  private stepEnrage(dtMs: number) {
    if (this._enraged || !this.boss || !this.boss.alive) return;
    this.roundLeft -= dtMs;
    if (this.roundLeft > 0) return;
    if (this.escapeOnRoundEnd) {
      this.roundLeft = 0;
      this.escaped = true;
      this.finished = true;
      return;
    }
    this._enraged = true;
    if (this.bossThrow) this.bossThrow.intervalMs *= ENRAGE_THROW_MULT;
    this.boss.damage = Math.max(1, Math.round(this.boss.damage * ENRAGE_DMG_MULT));
  }

  /** Boss action scheduler — GROUND TRUTH (`CivilianActorFight bossUpdate:` 0x67e8c).
   *  When the boss's action cooldown expires it makes ONE weighted roll over its whole
   *  `bossActions` list (`rollAgainstFrequencyInArray:`) and dispatches on the chosen
   *  action's name: `throw` launches a projectile and recovers for the raid's
   *  `throwSpeed`; every other action winds up for its `castTime` and then recovers for
   *  its `cooldownTime`. Throws therefore COMPETE with specials for the same slot —
   *  a boss whose list is all throws (most of them) tosses on a plain interval, while
   *  the Robot BrainBot (75 % throws) and the Video Games boss (27 %) throw
   *  proportionally less because their specials consume the budget.
   *
   *  The next action is rolled as soon as the previous one resolves so the renderer can
   *  telegraph it (`bossThrowSwing` only winds the arm when a throw is actually next). */
  private stepBossActions(dtMs: number) {
    if (!this.actions.length || !this.bossActive() || !this.anyAlive(this.players)) return;
    // Frozen by Medusa: everything it was doing simply waits.
    if (this.bossFreezeMs > 0) return;
    // In Endless a stun interrupts him: a move mid-cast is lost, and he acts again once free.
    if (this.endlessMechanics && this.boss && this.boss.stunMs > 0) {
      if (this.pendingSpecial) {
        this.actionCd = Math.max(300, this.pendingSpecial.cooldownMs);
        this.pendingSpecial = null;
        this.boss.chargeFrac = 0;
        this.rollNextAction();
      }
      return;
    }
    // A special that is already winding up owns the boss until it lands.
    if (this.pendingSpecial) {
      this.specialCast -= dtMs;
      if (this.pendingSpecial.name === "launch" && this.boss) {
        this.boss.chargeFrac = 1 - Math.max(0, this.specialCast) / Math.max(1, this.pendingSpecial.castMs);
      }
      if (this.specialCast <= 0) {
        const sp = this.pendingSpecial;
        this.runSpecial(sp);
        this.pendingSpecial = null;
        this.actionCd = Math.max(300, sp.cooldownMs * (this._enraged ? ENRAGE_SPECIAL_MULT : 1));
        this.rollNextAction();
      }
      return;
    }
    const next = this.nextAction;
    if (!next) return;
    // Once the boss is off its perch it has no action budget at all (see bossCanAct), so
    // let the slot rest instead of re-rolling it every tick for the rest of the fight.
    // A cast ALREADY in flight is deliberately left to land above: the source arms those
    // through `schedule:interval:`, which fires whatever state the boss has moved on to.
    if (!this.bossCanAct()) return;
    // A throw waiting on an empty lane parks its timer at the full wind-up instead of
    // running out (ruleset 39). The old pin-at-zero released the projectile on the very
    // tick a target first appeared — so the first throw of every fight, and every throw
    // after a line wipe, fired with no arm-swing at all. Parked here, the moment a
    // zombie enters the lane the timer runs THROW_WINDUP_MS down to release, which is
    // exactly the window bossThrowSwing() animates over. Checked before the decrement
    // (not at expiry) so a lane that empties mid-wind-up re-parks the timer too.
    if (next.kind === "throw" && this.actionCd <= THROW_WINDUP_MS && !this.throwTarget()) {
      this.actionCd = THROW_WINDUP_MS;
      return;
    }
    // Do or Die: the boss's action clock runs fast, so it throws twice as often.
    this.actionCd -= this.doOrDie ? dtMs * DO_OR_DIE_HASTE : dtMs;
    if (this.actionCd > 0) return;
    // The source checks each action's `allowedTo…` gate AFTER the roll but BEFORE arming
    // any timer, so an action it cannot perform right now (a second wall, an exhausted
    // summon) costs nothing — it simply re-rolls on the next tick instead of burning the
    // slot on a no-op cast.
    if (!this.canPerform(next)) {
      this.rollNextAction();
      return;
    }
    if (next.kind === "throw") {
      const target = this.throwTarget();
      if (!target) {
        // Unreachable at the fixed 50 ms tick (the empty-lane park above catches the
        // timer long before expiry) — kept as the same hold for safety at any dt.
        this.actionCd = THROW_WINDUP_MS;
        return;
      }
      this.launchProjectile(target, next.option.damage, next.option.sprite, next.option.spriteSize);
      this.throwCount++;
      // The dex tax (raid 13): the wait until the NEXT throw is re-derived from the army
      // that is on the field right now, so it tightens as the player commits more of it.
      // Off everywhere else, and below t3 — the authored interval stands.
      this.actionCd = this.duel?.dexTax
        ? dexTaxedInterval(this.bossThrow!.intervalMs, this.deployedDex())
        : this.bossThrow!.intervalMs;
      this.rollNextAction();
      return;
    }
    // A special: wind up now, resolve when the cast completes (above).
    this.pendingSpecial = next.special;
    this.specialCast = Math.max(0, next.special.castMs);
    if (next.special.name === "galacticBlast") {
      if (this.boss) {
        this.bossSpecialEffects.push({
          name: "galacticBeamCharge",
          x: Math.min(FIELD_W - 20, this.boss.x + 95),
          y: CENTER_Y,
        });
      }
    }
  }

  /** Endless location actions share the ordinary special implementations, while their
   *  independent clocks and counters remain part of snapshots for deterministic replay. */
  private stepEndlessMechanics(dtMs: number) {
    const mechanics = this.endlessMechanics;
    if (!mechanics || !this.anyAlive(this.players)) return;
    this.stepSmokeWindups(dtMs);
    for (const [key, cooldown] of Object.entries(mechanics.cooldownsMs)) {
      const remaining = (this.endlessMechanicTimers[key] ?? cooldown) - dtMs;
      if (remaining > 0) {
        this.endlessMechanicTimers[key] = remaining;
        continue;
      }
      this.endlessMechanicTimers[key] = Math.max(1_000, cooldown);
      this.endlessMechanicCount++;
      this.actionCount++;
      if (key === "smoke-bomb-teleport") {
        // No ninja at the front yet: try again shortly, so the bomb goes off once one is.
        if (!this.endlessNinjaWindup()) this.endlessMechanicTimers[key] = ENDLESS_SMOKE_RETRY_MS;
      } else if (key === "laser") {
        this.runSpecial({ name: "alienLaser", weight: 1, castMs: 0, damage: ALIEN_LASER_DAMAGE, cooldownMs: 0 });
      } else if (key === "summons") {
        const template = mechanics.reinforcementTemplate;
        if (template && this.enemies.filter((e) => e.alive && !e.isBoss).length < 10) this.spawnEnemy(template);
      } else if (key === "pixel-fire") {
        this.runSpecial({ name: "pixelFire", weight: 1, castMs: 0, damage: 0, cooldownMs: 0 });
      } else if (key === "turn-zombie") {
        this.runSpecial({ name: "turnZombie", weight: 1, castMs: 0, damage: 0, cooldownMs: 0 });
      } else if (key === "carrot-wall") {
        this.runSpecial({ name: "wall", weight: 1, castMs: 0, damage: 0, cooldownMs: 0 });
      } else if (key === "beam-walk-in") {
        this.endlessBeamWalkIn();
      }
    }
  }

  /** Alien Landing's saucer beams its next walk-in boss down mid-field, the way an alien
   *  invasion's abductee arrives: inside a light pillar (RaidScene draws it for a summon),
   *  standing its ground as a roadblock. Unlike an abductee it must be beaten to clear the
   *  floor, which every enemy must (playerWon). The count sent rides the snapshotted timers. */
  private endlessBeamWalkIn() {
    const sent = this.endlessMechanicTimers["beam-walk-in:sent"] ?? 0;
    const template = this.endlessMechanics?.walkInTemplates?.[sent];
    if (!template) return;
    this.endlessMechanicTimers["beam-walk-in:sent"] = sent + 1;
    const boss = this.spawnEnemy(template);
    boss.isSummon = true;
    boss.isBlocker = true;
    boss.state = "hold";
    boss.x = SUMMON_SPAWN_X;
    boss.y = CENTER_Y;
    boss.prevX = boss.x;
    boss.prevY = boss.y;
    for (const p of this.players) {
      if (p.alive && p.x > boss.x + 0.5) p.passedBlockers.push(boss.id);
    }
  }

  /** A ninja able to throw the smoke bomb: fighting at the front, not already flanking. */
  private smokeBomberReady(e: SimUnit): boolean {
    return e.alive && !e.isBoss && !e.isSummon && !e.isWall && !e.isFlanker && !e.isTurned &&
      (e.state === "hold" || e.state === "fight") && ENDLESS_SMOKE_BOMBERS.has(e.sourceKey);
  }

  /** The bomb's wind-up (owner, 2026-11-11: "a larger wind up"): the ninja at the front gathers
   *  smoke for ENDLESS_SMOKE_WINDUP_MS, still fighting, then vanishes. False when no ninja is at
   *  the front or no Garden is out (the bomb is for the healers, owner 2026-11-10). */
  private endlessNinjaWindup(): boolean {
    if (this.enemies.some((e) => e.alive && e.smokeWindupMs > 0)) return true;
    const unit = this.enemies.find((e) => this.smokeBomberReady(e));
    if (!unit || !this.backlineTarget()?.isGarden) return false;
    unit.smokeWindupMs = ENDLESS_SMOKE_WINDUP_MS;
    return true;
  }

  /** Count wind-ups down. A ninja that falls, or leaves the front, loses its bomb. */
  private stepSmokeWindups(dtMs: number) {
    for (const e of this.enemies) {
      if (e.isFlanker && e.alive) e.flankMs += dtMs;
      if (e.smokeWindupMs <= 0) continue;
      if (!this.smokeBomberReady(e)) { e.smokeWindupMs = 0; continue; }
      e.smokeWindupMs = Math.max(0, e.smokeWindupMs - dtMs);
      if (e.smokeWindupMs === 0) this.endlessNinjaFlank(e);
    }
  }

  /** The flanking ninja smokes back to its place at the front after killing a Garden. */
  private endlessNinjaReturn(unit: SimUnit) {
    unit.isFlanker = false;
    unit.flankMs = 0;
    unit.state = "hold";
    unit.x = this.holdXOf(unit);
    unit.y = CENTER_Y;
    unit.prevX = unit.x;
    unit.prevY = unit.y;
    unit.vx = 0;
    unit.vy = 0;
    unit.timerMs = this.cycleMs(unit, null);
    this.smokeSeq++;
  }

  /** A Ninja smoke bomb (owner, 2026-11-10): the ninja fighting at the front vanishes in smoke
   *  and reappears in the formation's Garden line. Its slot at the front stays empty while it
   *  lives (it still counts as the one enemy out), so the zombies that turn back to deal with
   *  it are not hit from the front meanwhile. False when the Gardens left the field during the
   *  wind-up (the bomb fizzles). */
  private endlessNinjaFlank(unit: SimUnit): boolean {
    const target = this.backlineTarget();
    if (!target?.isGarden) return false;
    unit.isFlanker = true;
    unit.flankMs = 0;
    unit.state = "fight";
    unit.x = Math.max(35, target?.x ?? 130);
    unit.y = target?.y ?? CENTER_Y;
    unit.prevX = unit.x;
    unit.prevY = unit.y;
    unit.vx = 0;
    unit.vy = 0;
    this.smokeSeq++;
    return true;
  }

  /** Is the boss in its action posture at all?
   *
   *  GROUND TRUTH: `-[CivilianActorFight bossUpdate:]` (0x67b40) opens with
   *  `if (state - 15 > 12) goto civilianUpdate`, and inside that 15..27 window the action
   *  ROLL lives only in the state-19 arm. A boss that has finished its descent is in
   *  state 9 — below the window — so it drops straight through to `civilianUpdate` and
   *  has NO specials at all: no laser, no summon, no wall, no throw. It just swings.
   *
   *  An Epic Boss is the one exception, and only because it has no perch to be gated on:
   *  it falls onto the lane instead of occupying a state-19 phase, so it keeps its
   *  actions once it has landed. */
  /** Zedzox's magic (Video Games boss, ruleset 92; CombatUnit.magic). Its own clock beside the
   *  boss's ordinary actions, which he keeps: only while he is up on his perch with zombies on
   *  the field, every `everyMs` he charges for `castMs` (glowing, chargeFrac) and then casts
   *  one of two spells, picked by a deterministic hash of how many he has cast:
   *    - the BEAM sweeps over `beamSweepMs` from the front of the army to the very back, the
   *      Gardens' station included, hitting each zombie once for `beamDamage` and a stun;
   *    - the FIREBALL is lobbed onto the front group (the front line and the band behind it)
   *      for `blastDamage` each, sending every one of them flying (galacticBlast's knock).
   *  Medusa's freeze pauses it, and it stops the moment he comes down to fight. */
  private stepBossMagic(dtMs: number) {
    const boss = this.boss;
    const cfg = boss?.magicCfg;
    if (!boss || !cfg) return;
    if (this.bossFreezeMs > 0) return;
    // A beam already sweeping finishes even if the last target walks off it.
    if (boss.magicSweepMs > 0) {
      boss.magicSweepMs = Math.max(0, boss.magicSweepMs - dtMs);
      const onField = this.players.filter((p) => p.alive && !p.taken && this.onField(p));
      if (onField.length) {
        const front = Math.max(...onField.map((p) => p.x));
        const back = Math.min(...onField.map((p) => p.x));
        const f = cfg.beamSweepMs > 0 ? 1 - boss.magicSweepMs / cfg.beamSweepMs : 1;
        const sweepX = front - (front - back) * f;
        for (const p of onField) {
          if (p.x < sweepX - 0.5 || boss.magicHit.includes(p.id)) continue;
          boss.magicHit.push(p.id);
          this.dealEnemyDamage(p, cfg.beamDamage);
          p.struckThisTick = true;
          if (p.alive && cfg.beamStunMs > 0 && !this.uninterruptible(p)) p.stunMs = Math.max(p.stunMs, cfg.beamStunMs);
        }
      }
      if (boss.magicSweepMs <= 0) { boss.magicKind = 0; boss.magicHit = []; }
      return;
    }
    const canCast = this.bossCanAct() && boss.state === "structure" &&
      this.players.some((p) => p.alive && !p.taken && this.onField(p));
    if (boss.magicCastMs > 0) {
      if (!canCast) { boss.magicCastMs = 0; boss.magicKind = 0; boss.chargeFrac = 0; return; }
      boss.magicCastMs = Math.max(0, boss.magicCastMs - dtMs);
      boss.chargeFrac = cfg.castMs > 0 ? 1 - boss.magicCastMs / cfg.castMs : 1;
      if (boss.magicCastMs > 0) return;
      boss.chargeFrac = 0;
      boss.magicSeq++;
      boss.magicCdMs = Math.max(0, cfg.everyMs - cfg.castMs);
      if (boss.magicKind === 1) {
        boss.magicSweepMs = Math.max(1, cfg.beamSweepMs);
        boss.magicHit = [];
        this.bossSpecialEffects.push({ name: "zedzoxBeam", x: boss.x, y: boss.y });
        return;
      }
      // The fireball, lobbed onto the front group.
      const reach = this.engageDistance + DEATH_BLAST_REACH;
      const lead = this.frontFighter();
      const victims = lead
        ? this.players.filter((p) => p.alive && !p.taken && this.onField(p) && lead.x - p.x <= reach)
        : [];
      if (lead) this.bossSpecialEffects.push({ name: "zedzoxFireball", x: lead.x, y: lead.y });
      for (const v of victims) {
        this.dealEnemyDamage(v, cfg.blastDamage);
        v.struckThisTick = true;
        if (v.alive && this.knockBackZombie(v)) {
          const airMs = v.isHeadless ? 1650 : 900;
          v.blastAirMs = airMs;
          v.blastAirTotalMs = airMs;
          v.blastAirHeight = v.isHeadless ? 108 : 84;
          v.blastSpin = (stringSeed(v.id) & 1) === 0 ? 1 : -1;
        }
      }
      boss.magicKind = 0;
      return;
    }
    if (!canCast) return;
    if (boss.magicCdMs > 0) { boss.magicCdMs = Math.max(0, boss.magicCdMs - dtMs); return; }
    // Start a charge. A fresh salt pair (61/7) so the pick is independent of every other hash.
    boss.magicKind = hash(boss.magicCount * 61 + 7) < 0.5 ? 1 : 2;
    boss.magicCount++;
    boss.magicCastMs = cfg.castMs;
    this.bossSpecialEffects.push({ name: boss.magicKind === 1 ? "zedzoxBeamCharge" : "zedzoxFireballCharge", x: boss.x, y: boss.y });
  }

  private bossCanAct(): boolean {
    if (!this.boss || !this.boss.alive) return false;
    // The retreated ninja (raid 13, t9+) sits up top and does nothing until the rest are down.
    if (this.ninjaRetreated) return false;
    if (this.bossFallsFromSky) return this.boss.state !== "falling";
    return this.boss.state === "structure";
  }

  /** The source's per-action `allowedTo…` gates: a wall while one already stands and a
   *  summon while the last abductee still lives are refused, and the boss picks again
   *  rather than casting a no-op. Everything else is performable while it is up top. */
  private canPerform(action: BossActionChoice): boolean {
    // EVERY action is gated on the boss still being on its perch, not just throws. Doing
    // this as "un-performable" rather than "wait" matters: otherwise a pre-rolled action
    // would sit in the slot forever once the boss descends.
    if (!this.bossCanAct()) return false;
    if (action.kind === "throw") return !!this.bossThrow;
    if (action.kind !== "special") return true;
    if (action.special.name === "wall") {
      const wt = this.wallTemplate;
      return !!wt && !this.enemies.some((e) => e.alive && e.sourceKey === wt.sourceKey);
    }
    if (action.special.name === "summonBoss") {
      // `allowedToSummonBoss` (0x5eda4): a non-empty list, and `bossWall` empty — the
      // summoned actor is parked there, so only one abductee lives at a time.
      return (
        !!this.summonCfg &&
        this.summonQueue.length > 0 &&
        !this.enemies.some((e) => e.alive && e.isSummon)
      );
    }
    if (action.special.name === "turnZombie") {
      // Same shape as `allowedToSummonBoss`: one converted zombie stands at a time, and
      // there has to be a front fighter to convert. Refusing costs the boss nothing — it
      // re-rolls — so an army with nobody deployed yet is not quietly given a free pass.
      return (
        !!this.turnedTemplate &&
        !this.enemies.some((e) => e.alive && e.isTurned) &&
        !!this.frontFighter()
      );
    }
    if (action.special.name === "alienLaser") {
      // `ZFFightMan allowedToShootBullet` walks `zombies` and refuses the shot unless at
      // least one is ENGAGED (`isInMeleeRange`, or one of the special-attack states). With
      // the lane empty of fighters the saucer holds its fire — it never snipes the crowd
      // still walking up. See laserTarget().
      return !!this.laserTarget();
    }
    return true;
  }

  /** Roll the next action from the merged budget (deterministic — no RNG). */
  private rollNextAction() {
    this.nextAction = weightedPick(this.actions, this.actionCount, 0x51ec1a1);
    if (this.nextAction) this.actionCount++;
  }

  /** Merge the boss's throw options and specials into one weighted table, exactly the
   *  `bossActions` array the source rolls against: each throwable debris keeps its own
   *  authored frequency alongside each special's. */
  private buildActionBudget(): BossActionChoice[] {
    const out: BossActionChoice[] = [];
    if (this.boss && this.bossThrow) {
      for (const option of this.bossThrow.options) {
        out.push({ kind: "throw", weight: option.weight, option, special: null as never });
      }
    }
    for (const special of this.specials) {
      out.push({ kind: "special", weight: special.weight, special, option: null as never });
    }
    return out;
  }

  /** Land a boss special. Effects that need spawned entities (summonBoss, wall) go
   *  through spawnEnemy; both are capped so the fight still resolves. */
  private runSpecial(sp: BossSpecial) {
    switch (sp.name) {
      case "launch": {
        if (this.boss) this.boss.chargeFrac = 0;
        // The front `targets` deployed zombies (Endless: four), front-most first.
        const targets = this.players
          .filter((p) => p.alive && !p.taken && this.onField(p))
          .sort((a, b) => b.x - a.x || a.formOrder - b.formOrder)
          .slice(0, Math.max(1, sp.targets ?? 1));
        for (const target of targets) {
          this.dealEnemyDamage(target, sp.damage);
          this.launchToBack(target);
        }
        break;
      }
      case "alienLaser": {
        // Flat 200 per bolt — a hard constant in the source, not a stat-derived value
        // (`AlienStageBullet collidedWith:` passes the immediate 200.0f to `damage:`).
        // The saucer has TWO guns and picks between them 50/50 every shot
        // (`AlienStageActor createBullet`: a `(arc4random()%100)/100 < 0.5` roll chooses
        // (-55,+2) or (+5,-5) off the boss, in the source's 480x320 stage points).
        const target = this.laserTarget();
        if (target) {
          const muzzle = hash(this.actionCount * 11 + 3) < 0.5 ? LASER_MUZZLE_A : LASER_MUZZLE_B;
          this.launchProjectile(target, sp.damage || ALIEN_LASER_DAMAGE, ALIEN_LASER_SPRITE, 20, {
            straight: true,
            originDx: muzzle.dx,
            originDy: muzzle.dy,
          });
        }
        break;
      }
      case "pixelFire": {
        // Source (`ZFFightMan pixelFire`): picks ONE random eligible zombie and calls
        // `setOnFire`. The target selection is ground truth and unchanged; what the fire
        // then DOES is a deliberate divergence.
        //
        // Recovered, the burn lasts exactly one frame — `setOnFire` sets the zombie's
        // destination to its own current position, so the burning state ticks once, finds
        // it has already arrived, and leaves. ~0.08 % of max HP: Zedzox's headline special
        // was worth about two damage. We ship the burn it is plainly reaching for instead
        // (PIXEL_FIRE_BURN_MS at the recovered 5 %/s), and give the player the answer the
        // one-frame version never needed: tap it out. See raid/videoGameStage.ts.
        const eligible = this.players.filter(
          (p) => p.alive && !p.taken && !p.burnMs && (p.state === "advance" || p.state === "fight")
        );
        const victim = eligible.length
          ? eligible[Math.floor(hash(this.actionCount * 7 + 5) * eligible.length) % eligible.length]
          : null;
        if (victim) {
          victim.windupKey = null; // the cancelled swing (this half IS ground truth)
          victim.windupMs = 0;
          victim.timerMs = this.cycleMs(victim, null);
          victim.burnMs = PIXEL_FIRE_BURN_MS;
          victim.burnAnchorX = victim.x;
          // Panic AWAY from the enemy first, so the fire visibly breaks the front line
          // rather than shoving the zombie further into it.
          victim.burnDir = -1;
          victim.struckThisTick = true;
        }
        break;
      }
      case "turnZombie": {
        // Zedzox turns a zombie against you. This USED to be modelled as
        // `dealDamage(victim, victim.hp)` — the front zombie simply evaporated, with no
        // projectile, no animation and no attacker anywhere near it, and went down as a
        // permanent casualty. That is the "zombies die suddenly for no reason" players
        // reported on this invasion, and it was never what the action does: the source
        // name, the wiki text and an authored-but-unspawnable `VideoGameStageZombieActor`
        // all say CONVERT.
        //
        // So it converts. The zombie is carried out of the fight — `taken`, exactly like a
        // Beach crab's passenger: still alive, still a survivor, NOT a loss — and a pixel
        // zombie stands up in the middle of the lane wearing its identity. Tap that apart
        // and you get the zombie back (tapTurned).
        const template = this.turnedTemplate;
        const victim = template ? this.frontFighter() : null;
        if (victim && template) {
          victim.taken = true;
          victim.windupKey = null;
          victim.windupMs = 0;
          victim.burnMs = 0; // a zombie that is dragged off stops being on fire
          victim.dotMs = 0;
          victim.struckThisTick = true;
          const turned = this.spawnEnemy(template);
          turned.isSummon = true; // off the wave budget, so it can't hold the descent
          turned.isTurned = true;
          turned.turnedFromId = victim.id;
          // Beamed in mid-field on the scorch mark, standing, exactly as an abductee is —
          // same landing point, same "already past it" latch. See SUMMON_SPAWN_X.
          turned.state = "hold";
          turned.x = SUMMON_SPAWN_X;
          turned.y = CENTER_Y;
          turned.prevX = turned.x;
          turned.prevY = turned.y;
          // No `passedWall` latch here, unlike an abductee or a wall: this one blocks
          // nobody (see wallInWay), so there is nothing to have got past.
        }
        break;
      }
      case "telekinesis": {
        // Source (`ZFFightMan telekinesis:`) deals NO damage: it lifts the zombie,
        // `knockBackBy:force:` it down the lane and `stunSelfFor:` holds it there.
        const victim = this.frontFighter() ?? this.throwTarget();
        if (victim) {
          this.knockBackZombie(victim);
          victim.stunMs = Math.max(victim.stunMs, TELEKINESIS_STUN_MS);
          victim.struckThisTick = true;
        }
        break;
      }
      case "galacticBlast": {
        // Galactic Groundhog's special: one charged death beam sweeps across the
        // deployed line. Its broad deterministic damage and knockback resolve together
        // on the live client and replay worker; the sustained beam is presentation-only.
        const center = this.frontFighter();
        if (center) {
          this.bossSpecialEffects.push({ name: "galacticBeam", x: center.x, y: center.y });
          const radius = 190;
          const targets = this.players.filter((victim) => {
            if (!victim.alive || victim.taken) return false;
            if (victim.state !== "advance" && victim.state !== "fight" && victim.state !== "hold") return false;
            const dx = victim.x - center.x;
            const dy = victim.y - center.y;
            return dx * dx + dy * dy <= radius * radius;
          }).sort((a, b) =>
            hash(stringSeed(a.id) * 31 + this.actionCount * 17 + 3) -
            hash(stringSeed(b.id) * 31 + this.actionCount * 17 + 3)
          );
          for (const victim of targets) {
            this.dealDamage(victim, sp.damage, false);
            if (victim.alive && this.knockBackZombie(victim)) {
              const airMs = victim.isHeadless ? 1650 : 900;
              victim.blastAirMs = airMs;
              victim.blastAirTotalMs = airMs;
              victim.blastAirHeight = victim.isHeadless ? 108 : 84;
              victim.blastSpin = (stringSeed(victim.id) & 1) === 0 ? 1 : -1;
            }
          }
        }
        break;
      }
      case "summonBoss": {
        // GROUND TRUTH (`-[ZFFightMan summonBoss:]` 0x5ee2c): the alien boss abducts a
        // HUMAN. It pops `bossSummonList[0]`, spawns it at `enemyPosition`, and then
        // pushes ONE freshly rolled name back on — five candidates, 20 % each — so the
        // queue never empties. The only limit is one abductee alive at a time, enforced
        // in canPerform. The victim is off-budget (see SimUnit.isSummon).
        const cfg = this.summonCfg;
        const key = this.summonQueue.shift();
        if (!cfg || !key) break;
        const template = cfg.queue.find((u) => u.sourceKey === key)
          ?? cfg.pool.find((u) => u.sourceKey === key);
        if (template) {
          const victim = this.spawnEnemy(template);
          victim.isSummon = true;
          victim.isBlocker = true;
          // Beamed down mid-field, not queued behind the wave at the doorway — see
          // SUMMON_SPAWN_X. Leaving it "queued" would also deadlock it, since the wave's
          // release gate deliberately ignores summons.
          victim.state = "hold";
          // Raid 15 puts it immediately enemy-side of where the wall lands, so wall plus
          // abductee is one double-thick roadblock across the player's own lane rather
          // than two separate nuisances. Everywhere else it is the authored mid-lane spot.
          // Keyed on THIS FIGHT HAVING a bubble wall rather than on a raid id, which is
          // the honest coupling: the repositioning exists because of that wall, and a
          // fight without one has nothing to stand beside.
          victim.x = this.bubbleWall
            ? this.supportX + ABDUCTEE_WALL_GAP
            : SUMMON_SPAWN_X;
          victim.y = CENTER_Y;
          victim.prevX = victim.x;
          victim.prevY = victim.y;
          // Same latch the wall uses: a zombie already past the spawn point does not turn
          // round to fight something that appeared behind it.
          for (const p of this.players) {
            if (p.alive && p.x > victim.x + 0.5) p.passedBlockers.push(victim.id);
          }
        }
        // The refill roll: `(int)((arc4random() % 100) / 100.0f * 5.0f)`, hashed here for
        // replay. Rolled even when the spawn itself failed, exactly as the source does.
        //
        // Its own salt. Every draw in this sim is `hash(actionCount * a + b)`, so two
        // draws sharing (a, b) are not merely both deterministic — they are the SAME
        // number. This one shared (13,7) with `laserTarget`, and both belong to the
        // ALIEN boss, so which human it abducted was locked to which zombie its laser
        // would have picked on that same cycle. The pairs in use are (13,7) laser
        // target, (11,3) laser muzzle, (7,5) pixelFire victim, and (17,11) here; no two
        // of them agree for any actionCount.
        if (cfg.pool.length) {
          const i = Math.min(
            cfg.pool.length - 1,
            Math.floor(hash(this.actionCount * 17 + 11) * cfg.pool.length)
          );
          this.summonQueue.push(cfg.pool[i].sourceKey);
        }
        break;
      }
      case "wall": {
        // Materialize at the Garden support line. It never walks or attacks.
        // Re-check the perch here as well as in canPerform: with no wall standing and
        // the last minion dead, promote() can start the boss's descent DURING the 3 s
        // cast, and a wall that lands after that would sit behind the boss forever.
        const wt = this.endlessMechanics ? this.wallTemplate
          : this.boss?.state === "structure" ? this.wallTemplate : null;
        if (wt && !this.enemies.some((e) => e.alive && e.sourceKey === wt.sourceKey)) {
          const wall = this.spawnEnemy(wt);
          wall.isWall = true;
          wall.isBlocker = true;
          wall.state = "hold";
          wall.x = this.supportX;
          wall.y = CENTER_Y;
          wall.prevX = wall.x;
          wall.prevY = wall.y;
          wall.vx = 0;
          wall.vy = 0;
          for (const p of this.players) {
            if (p.alive && p.x > wall.x + 0.5) p.passedBlockers.push(wall.id);
          }
        }
        break;
      }
      // telekinesis handled above; anything else is a no-op.
      default:
        break;
    }
  }

  /** Presentation cues produced by resolved boss specials; draining them does not alter
   *  simulation state or replay outcomes. */
  drainBossSpecialEffects(): { name: string; x: number; y: number }[] {
    return this.bossSpecialEffects.splice(0);
  }

  /** Spawn a new enemy from a template mid-fight (abductee / wall). It joins the enemy
   *  roster + the shared units array (so the renderer picks it up) and emerges through
   *  the normal queue. */
  private spawnEnemy(template: CombatUnit): SimUnit {
    const su = toSim({ ...template, id: `spawn${this.spawnSeq++}` }, this.enemies.length);
    su.state = "queued";
    su.hp = su.maxHp;
    su.alive = true;
    this.enemies.push(su);
    this.units.push(su);
    return su;
  }

  /** Front-most fighting player zombie (nearest the enemy), or null. */
  private frontFighter(): SimUnit | null {
    let best: SimUnit | null = null;
    for (const p of this.players) {
      // `!p.taken` for the reason spelled out in frontMostPlayer: a zombie already turned
      // into a pixel zombie is not standing there to be turned (or shoved) again.
      if (!p.alive || p.taken || (p.state !== "fight" && p.state !== "advance")) continue;
      if (!best || p.x > best.x + 0.5 || (Math.abs(p.x - best.x) <= 0.5 && p.y > best.y)) best = p;
    }
    return best;
  }

  /** Deployed zombies (released from the focus bar and out on the lane). */
  private deployed(): SimUnit[] {
    return this.players.filter(
      (p) => p.alive && !p.taken && (p.state === "advance" || p.state === "fight")
    );
  }

  /** Advance the Trapeze Artist grab hazard. Spawns one at a time on a cadence; successive
   *  appearances alternate right-to-left and left-to-right, seize a selected zombie on
   *  contact, hold ~1s, then rise to carry it off. Tapping (tapGrabber) whittles its HP — killed → the
   *  zombie DROPS back into the fight; escaped off the top → the carried zombie DIES. */
  private stepGrabbers(dtMs: number) {
    if (!this.grabberCfg) return;
    // Spawn one at a time on a cadence, only while there's a deployed zombie to threaten.
    const active = this.grabbers.some((g) => g.state !== "gone");
    if (!active && this.anyAlive(this.players)) {
      this.grabberTimer -= dtMs;
      if (this.grabberTimer <= 0 && this.deployed().length > 0) {
        const victim = this.deployed().sort((a, b) => a.x - b.x)[0];
        this.spawnGrabber(victim);
        this.grabberTimer = GRABBER_SPAWN_MS;
      }
    }
    for (const g of this.grabbers) {
      if (g.state === "gone") continue;
      if (g.tapCdMs > 0) g.tapCdMs -= dtMs;
      if (g.state === "swoop") {
        g.pauseMs = Math.max(0, g.pauseMs - dtMs);
        const t = 1 - g.pauseMs / g.swingTotalMs;
        const eased = t * t * (3 - 2 * t);
        g.rot = g.swingStartDeg + (g.contactDeg - g.swingStartDeg) * eased;
        if (g.pauseMs <= 0) {
          const victim = g.targetId
            ? this.players.find((p) => p.id === g.targetId)
            : null;
          if (!victim || !victim.alive ||
              (victim.state !== "advance" && victim.state !== "fight")) {
            g.state = "gone";
            continue;
          }
          // Re-anchor directly above the victim and turn vertical. Because contactDeg
          // put the artist itself at the victim first, only the rope pivot jumps.
          g.x = victim.x;
          g.y = victim.y - GRABBER_ZOMBIE_OFFSET_Y;
          g.rot = GRABBER_CONTACT_DEG;
          g.grabbedId = victim.id;
          g.targetId = null;
          g.state = "carry";
          g.pauseMs = GRABBER_CARRY_PAUSE_MS;
          victim.state = "grabbed";
          victim.windupKey = null;
          victim.windupMs = 0;
          victim.stunMs = 0;
        }
      } else if (g.state === "carry") {
        const z = g.grabbedId ? this.players.find((p) => p.id === g.grabbedId) : null;
        if (!z || !z.alive) {
          g.grabbedId = null;
          g.state = "gone";
          continue;
        }
        if (g.pauseMs > 0) {
          g.pauseMs -= dtMs;
        } else {
          g.y -= (GRABBER_RISE_SPEED * dtMs) / 1000;
          g.rot = 90;
        }
        z.x = g.x; // the seized zombie rides below the overhead trapeze
        z.y = g.y + GRABBER_ZOMBIE_OFFSET_Y;
        z.prevX = z.x;
        z.prevY = z.y;
        if (z.y <= GRABBER_ESCAPE_ZOMBIE_Y) {
          z.hp = 0; // carried off — the zombie is lost
          z.alive = false;
          z.state = "dead";
          g.grabbedId = null;
          g.state = "gone";
        }
      }
    }
    // Drop inert grabbers so the array (and snapshots) stay small.
    for (let i = this.grabbers.length - 1; i >= 0; i--) {
      if (this.grabbers[i].state === "gone") this.grabbers.splice(i, 1);
    }
  }

  /** Advance the Beach crab hazard. Ground truth (`BeachStageActorCrab update:`): spawns on
   *  the obstacle timer up to `limit` alive at once, wanders, grabs the first deployed
   *  zombie it touches (that zombie goes inert + invincible), holds `holdMs`, then hauls it
   *  off the LEFT edge — at which point the zombie leaves the fight (`taken`, source state
   *  38: NOT death, it comes home afterwards). Tapping it to death (`tapCrab`) frees the
   *  zombie and returns the spawn slot. */
  private stepCrabs(dtMs: number) {
    if (!this.crabCfg) return;
    const live = this.crabs.filter((c) => c.state !== "gone").length;
    if (live < this.crabCfg.limit && this.anyAlive(this.players)) {
      this.crabTimer -= dtMs;
      if (this.crabTimer <= 0) {
        this.spawnCrab();
        this.crabTimer = this.crabCfg.spawnMs;
      }
    }
    for (const c of this.crabs) {
      if (c.state === "gone") continue;
      if (c.tapCdMs > 0) c.tapCdMs -= dtMs;
      if (c.state === "wander") {
        c.wanderMs -= dtMs;
        if (c.wanderMs <= 0) {
          // Re-pick a heading deterministically from the crab's own id + the sim clock,
          // so a replay of the same tick stream reproduces the same patrol.
          c.dir = ((this.crabSeq + Math.floor(this.elapsed / CRAB_WANDER_MS)) % 2 === 0 ? -1 : 1);
          c.wanderMs = CRAB_WANDER_MS;
        }
        c.x += (CRAB_WALK_SPEED * c.dir * dtMs) / 1000;
        if (c.x < CRAB_WANDER_MIN_X) { c.x = CRAB_WANDER_MIN_X; c.dir = 1; }
        if (c.x > CRAB_WANDER_MAX_X) { c.x = CRAB_WANDER_MAX_X; c.dir = -1; }
        const victim = this.deployed().find(
          (p) => !p.taken && Math.hypot(p.x - c.x, p.y - c.y) <= CRAB_HIT_R
        );
        if (victim) {
          c.grabbedId = victim.id;
          c.state = "hold";
          c.holdMs = this.crabCfg.holdMs;
          victim.state = "grabbed";
          victim.windupKey = null;
          victim.windupMs = 0;
          victim.stunMs = 0;
        }
      } else if (c.state === "hold" || c.state === "carry") {
        const z = c.grabbedId ? this.players.find((p) => p.id === c.grabbedId) : null;
        if (!z || !z.alive) {
          c.grabbedId = null;
          c.state = "gone";
          continue;
        }
        if (c.state === "hold") {
          c.holdMs -= dtMs;
          if (c.holdMs <= 0) c.state = "carry";
        } else {
          c.x -= (CRAB_CARRY_SPEED * dtMs) / 1000; // haul it off the left edge
        }
        z.x = c.x; // the seized zombie rides along with the crab
        z.y = c.y;
        z.prevX = z.x;
        z.prevY = z.y;
        if (c.x <= CRAB_EXIT_X) {
          z.taken = true; // out of THIS fight; still alive, still a survivor
          c.grabbedId = null;
          c.state = "gone";
        }
      }
    }
    for (let i = this.crabs.length - 1; i >= 0; i--) {
      if (this.crabs[i].state === "gone") this.crabs.splice(i, 1);
    }
  }

  private spawnCrab() {
    const cfg = this.crabCfg!;
    this.crabs.push({
      id: `crab${this.crabSeq++}`,
      x: CRAB_WANDER_MAX_X,
      y: CENTER_Y,
      state: "wander",
      dir: -1,
      wanderMs: CRAB_WANDER_MS,
      hp: cfg.hp,
      maxHp: cfg.hp,
      tapDamage: cfg.tapDamage,
      grabbedId: null,
      holdMs: 0,
      tapCdMs: 0,
      sprite: cfg.sprite,
      struckThisTick: false,
    });
  }

  /** Player tapped a crab: one tap of damage (rate-limited). Ground truth is 100 damage a
   *  tap against 1000 HP — ten taps; the shipped HP is tuned down per input device (seven
   *  taps on touch, four with a mouse — see RaidManager.crabOf and raid/hazardTaps.ts),
   *  and the rate limit likewise. Killing it releases any zombie it holds back onto the lane
   *  (source state 9 → 10, invincibility off) and frees its spawn slot. */
  tapCrab(id: string): boolean {
    const c = this.crabs.find((x) => x.id === id && x.state !== "gone");
    if (!c || c.tapCdMs > 0) return false;
    c.tapCdMs = this.hazardTapCooldownMs;
    c.hp -= c.tapDamage;
    c.struckThisTick = true;
    if (c.hp <= 0) {
      c.hp = 0;
      const z = c.grabbedId ? this.players.find((p) => p.id === c.grabbedId) : null;
      if (z && z.alive) {
        z.state = "advance"; // released: back on the lane, re-advances from the rear
        z.y = CENTER_Y;
        z.timerMs = this.cycleMs(z, null);
        z.stunMs = 0;
        z.formOrder = this.releaseSeq++;
        z.frontPriority = false;
        z.inLine = false;
      }
      c.grabbedId = null;
      c.state = "gone";
    }
    return true;
  }

  /** Crabs the renderer can draw / the player can tap. */
  activeCrabs(): SimCrab[] {
    return this.crabs.filter((c) => c.state !== "gone");
  }

  /** Advance the Mega-Robot (`RobotStageActorGiantBot update:`). It keys off the boss's
   *  enrage countdown exactly as the source does: time elapsed on the round clock
   *  decides when it climbs and first arms, time LEFT decides whether it stands or
   *  wanders, and enrage halves the fuse. Each armed cycle is an 8 s fuse the player can
   *  cut short by tapping the eyes out (→ 5 s rest), else a launch at one deployed zombie,
   *  a 1 s flight, the blast, and 1 s dark before it re-arms — one shot every 10 s. */
  private stepMegaBot(dtMs: number) {
    const m = this.megaBot;
    if (!m || m.phase === "gone") return;
    if (m.tapCdMs > 0) m.tapCdMs = Math.max(0, m.tapCdMs - dtMs);
    const roundGone = this.roundTotalMs - this.roundLeft;
    m.restless = this._enraged ? 2 : this.roundLeft <= MEGA_WANDER_LEFT_MS ? 1 : 0;

    switch (m.phase) {
      case "hidden":
        // No boss → the countdown never runs → it never rises (source default T = 180).
        // Enrage is checked first in the source (state 0 → 7), so it also wakes it.
        if (roundGone >= MEGA_RISE_AT_MS || this._enraged) m.phase = "rising";
        return;
      case "rising":
        if (roundGone >= MEGA_ARM_AT_MS || this._enraged) this.armMegaBot(m);
        return;
      case "dark":
        // State 6: re-arms the moment someone is on the field to shoot at.
        if (this.deployed().length) this.armMegaBot(m);
        return;
      case "charge":
        m.phaseMs -= dtMs;
        if (m.phaseMs > 0) return;
        this.launchMegaBot(m);
        return;
      case "fire":
        m.phaseMs -= dtMs;
        if (m.phaseMs > 0) return;
        this.detonateMegaBot(m);
        m.phase = "recover";
        m.phaseMs = MEGA_RECOVER_MS;
        return;
      case "recover":
      case "disabled":
        m.phaseMs -= dtMs;
        if (m.phaseMs <= 0) this.armMegaBot(m);
        return;
    }
  }

  /** States 1/2/7: fresh eye hitbox at full HP and a new fuse — or dark if nobody's out. */
  private armMegaBot(m: SimMegaBot) {
    if (!this.deployed().length) {
      m.phase = "dark";
      return;
    }
    m.phase = "charge";
    m.chargeMs = this._enraged ? MEGA_ENRAGE_CHARGE_MS : MEGA_CHARGE_MS;
    m.phaseMs = m.chargeMs;
    m.eyeHp = m.eyeMaxHp;
    m.tapCdMs = 0;
  }

  /** State 3: pick one deployed zombie and send both fireballs to where it stands NOW
   *  (they don't home). The source rolls `arc4random()%100/100 × count`; this is the same
   *  uniform pick off the sim's deterministic hash. */
  private launchMegaBot(m: SimMegaBot) {
    const targets = this.deployed();
    if (!targets.length) {
      m.phase = "dark";
      return;
    }
    const pick = Math.min(targets.length - 1, Math.floor(hash(m.shots * 7.13 + 3.7) * targets.length));
    const t = targets[pick];
    m.shots++;
    m.targetX = t.x;
    m.targetY = t.y;
    m.shotSeq++;
    m.phase = "fire";
    m.phaseMs = MEGA_FLIGHT_MS;
  }

  /** `explodeAttack:` — splash every deployed zombie within 40 points for 800/(1 + d/10),
   *  then a 100000 kill shot on the one nearest the blast.
   *
   *  Divergence, deliberate: the source's nearest-zombie search never updates its running
   *  minimum, so its victim is effectively arbitrary and can even stand outside the blast.
   *  The intent is plainly "the zombie at ground zero", so that is what this kills — and
   *  only inside the radius, so a zombie that has walked clear of the flight survives. */
  private detonateMegaBot(m: SimMegaBot) {
    m.blastSeq++;
    let nearest: SimUnit | null = null;
    let nearestPt = Infinity;
    for (const z of this.deployed()) {
      const dPt = Math.hypot(
        (z.x - m.targetX) / MEGA_SIM_PER_PT_X,
        (z.y - m.targetY) / MEGA_SIM_PER_PT_Y
      );
      if (dPt > MEGA_SPLASH_RADIUS_PT) continue;
      if (dPt < nearestPt) { nearestPt = dPt; nearest = z; }
      this.dealDamage(z, MEGA_SPLASH / (1 + dPt / 10), false);
    }
    if (nearest && nearest.alive) this.dealDamage(nearest, MEGA_KILL_SHOT, false);
  }

  /** Player tapped the Mega-Robot's eyes: one tap of damage. Emptying the hitbox cancels
   *  the pending shot (state 4). Only the lit eyes are tappable — the source releases the
   *  hitbox the instant it fires.
   *
   *  NOT rate-limited. The source's eye box takes every `ccTouchEnded:` (no `tapDelay` —
   *  that belongs to the trapeze and crab), and borrowing their 250 ms gate made the robot
   *  near-unbeatable on a phone: a finger tapping a little faster than 4/s has every
   *  other tap land inside the gate, so 12 taps took ~5 s of an 8 s fuse whose eyes only
   *  light up ~3 s in — and could not fit the 4 s enraged fuse at all. Player report
   *  2026-09-28: "tapping quite a bit" and the blast still fires. */
  tapMegaBotEyes(): boolean {
    const m = this.megaBot;
    if (!m || m.phase !== "charge") return false;
    m.eyeHp = Math.max(0, m.eyeHp - m.tapDamage);
    m.eyeHits++;
    if (m.eyeHp <= 0) {
      m.phase = "disabled";
      m.phaseMs = MEGA_DISABLED_MS;
    }
    return true;
  }

  /** The robot while its eyes can be tapped, else null. For HUDs and pilots. */
  megaBotCharging(): SimMegaBot | null {
    return this.megaBot?.phase === "charge" ? this.megaBot : null;
  }

  /** Prepare living zombies for the presentation-only end march. Remaining rescue
   *  hazards are destroyed and drop their passengers; focus/ability poses are
   *  cleared so nobody keeps thinking or attacking after combat has ended. */
  prepareArmyExit(): void {
    const heldIds = new Set<string>();
    for (const grabber of this.grabbers) {
      if (grabber.grabbedId) heldIds.add(grabber.grabbedId);
    }
    for (const crab of this.crabs) {
      if (crab.grabbedId) heldIds.add(crab.grabbedId);
    }

    this.grabbers.length = 0;
    this.crabs.length = 0;
    this.projectiles.length = 0;
    // Combat is over, so anything still holding a zombie lets go: a pixel zombie left
    // standing when the boss fell hands its captive back for the victory march. It costs
    // the player nothing either way (a captive is `taken`, so it was already coming home),
    // but marching out one short of the army that won looks like a bug.
    for (const turned of this.enemies) {
      if (turned.isTurned) this.releaseTurned(turned);
    }

    for (const zombie of this.players) {
      if (!zombie.alive || zombie.taken) continue;
      zombie.burnMs = 0; // nobody marches out of a won fight still on fire
      zombie.dotMs = 0;
      // A shove that was still sliding when the last enemy fell is abandoned where it
      // got to. The slide is only ever ended by `stepKnockBack`, and the simulation
      // stops stepping the moment the fight is decided — so a zombie caught mid-shove
      // kept `knockBackSpeed` forever, and the renderer draws a shoved zombie on an
      // ease-out CLAMPED to the slide's own interval. Marching the other way put it
      // outside that interval, pinning it to the spot it was hit on for the whole
      // victory march (posed standing, too: a shoved rig deliberately holds its pose
      // rather than running the walk cycle). It stood at the front line while the rest
      // of the army walked past it and off the stage.
      zombie.knockBackSpeed = 0;
      zombie.knockBackToX = zombie.x;
      if (heldIds.has(zombie.id)) zombie.y = CENTER_Y;
      if (!zombie.buddyCarrierId) zombie.state = "advance";
      zombie.prevX = zombie.x;
      zombie.prevY = zombie.y;
      zombie.vx = 0;
      zombie.vy = 0;
      zombie.charge = 0;
      zombie.distracted = false;
      zombie.awaitRelease = false;
      zombie.bubbleMs = 0;
      zombie.windupKey = null;
      zombie.windupMs = 0;
      zombie.stunMs = 0;
    }
  }

  private spawnGrabber(victim: SimUnit) {
    const cfg = this.grabberCfg!;
    const seq = this.grabSeq++;
    const swingStartDeg = seq % 2 === 0 ? 0 : 180;
    const targetDx = clamp(
      (victim.x - GRABBER_PIVOT_X) / GRABBER_SWING_RADIUS_X,
      -1,
      1
    );
    const contactDeg = Math.acos(targetDx) * 180 / Math.PI;
    const swingTotalMs = Math.max(
      1,
      GRABBER_FULL_ARC_MS * Math.abs(contactDeg - swingStartDeg) / 180
    );
    this.grabbers.push({
      id: `grab${seq}`,
      x: GRABBER_PIVOT_X,
      y: GRABBER_PIVOT_Y,
      state: "swoop",
      hp: cfg.hp,
      maxHp: cfg.hp,
      tapDamage: cfg.tapDamage,
      grabbedId: null,
      pauseMs: swingTotalMs,
      tapCdMs: 0,
      sprite: cfg.sprite,
      rot: swingStartDeg,
      swingStartDeg,
      contactDeg,
      swingTotalMs,
      targetId: victim.id,
      struckThisTick: false,
    });
  }

  /** Player tapped a Trapeze Artist: deal one tap of damage (rate-limited by tapDelay).
   *  Killing it frees (drops) the zombie it carried back onto the lane. Returns true if a
   *  tap registered (drives tap feedback). */
  tapGrabber(id: string): boolean {
    // The raid-14 trapeze is not a rescue: its tap is `tapTrapeze`, and it is transcribed.
    const g = this.grabbers.find((x) => x.id === id && x.state !== "gone" && !x.drop);
    if (!g || g.tapCdMs > 0) return false;
    g.tapCdMs = this.hazardTapCooldownMs;
    g.hp -= g.tapDamage;
    g.struckThisTick = true;
    if (g.hp <= 0) {
      g.hp = 0;
      const z = g.grabbedId ? this.players.find((p) => p.id === g.grabbedId) : null;
      if (z && z.alive) {
        // Dropped: it just falls back to the lane and resumes advancing/fighting.
        z.state = "advance";
        z.y = CENTER_Y;
        z.timerMs = this.cycleMs(z, null);
        z.stunMs = 0;
        z.formOrder = this.releaseSeq++; // re-enters at the back of the formation
        z.frontPriority = false;
        z.inLine = false;
      }
      g.grabbedId = null;
      g.state = "gone";
    }
    return true;
  }

  /** The live Trapeze Artist currently carrying a zombie (renderer taps it), or null. */
  activeGrabber(): SimGrabber | null {
    return this.grabbers.find((g) => g.state === "carry" && !g.drop) ?? null;
  }

  /** Player tapped a converted PIXEL ZOMBIE: beat one tap's worth out of it. Sized off its
   *  own max HP so PIXEL_ZOMBIE_TAPS taps break it open whatever the elite profile did to
   *  its body. Breaking it hands the zombie inside back to the lane — the same release the
   *  crab and the trapeze already do for a passenger, and the reason the taps are worth
   *  spending on a body the army cannot chew through.
   *
   *  Returns true if a pixel zombie took the tap (drives the tap feedback + the
   *  transcript). */
  tapTurned(id: string): boolean {
    const z = this.enemies.find((e) => e.id === id && e.isTurned && e.alive);
    if (!z) return false;
    this.dealDamage(z, Math.max(1, z.maxHp / PIXEL_ZOMBIE_TAPS), true);
    z.struckThisTick = true; // the release itself is dealDamage's job, not this one's
    return true;
  }

  /** Hand a broken-open pixel zombie's captive back. It re-enters at the BACK of the
   *  formation and re-advances, exactly as a dropped trapeze / crab passenger does. */
  private releaseTurned(turned: SimUnit): void {
    const z = turned.turnedFromId
      ? this.players.find((p) => p.id === turned.turnedFromId)
      : null;
    turned.turnedFromId = null;
    if (!z || !z.alive || !z.taken) return;
    z.taken = false;
    z.state = "advance";
    z.x = CHARGE_X;
    z.y = CENTER_Y;
    z.prevX = z.x;
    z.prevY = z.y;
    z.vx = 0;
    z.vy = 0;
    z.stunMs = 0;
    z.burnMs = 0;
    z.timerMs = this.cycleMs(z, null);
    z.formOrder = this.releaseSeq++;
    z.frontPriority = false;
    z.inLine = false;
  }

  /** Player tapped a burning zombie: smother the fire. One tap does it — the burn is on a
   *  clock, not a health bar, and making the player land several taps on a panicking rig
   *  that is pacing across the lane would mean the fire usually wins by default.
   *
   *  Returns true if a fire was actually put out, so a tap on a zombie that is not burning
   *  (or whose fire has already run out) is refused rather than transcribed. */
  tapFire(id: string): boolean {
    const z = this.players.find((p) => p.id === id && p.alive && !p.taken && p.burnMs > 0);
    if (!z) return false;
    z.burnMs = 0;
    z.timerMs = this.cycleMs(z, null); // back to a full swing, not a half-charged one
    return true;
  }

  /** Every zombie currently on fire — the renderer draws a flame on each and makes it a
   *  tap target. */
  burningPlayers(): SimUnit[] {
    return this.players.filter((p) => p.alive && !p.taken && p.burnMs > 0);
  }

  /** Live converted pixel zombies (the renderer taps these). */
  turnedEnemies(): SimUnit[] {
    return this.enemies.filter((e) => e.isTurned && e.alive);
  }

  /** Player tapped a boss-summoned wall: chip it (ground truth ZFFightWall ccTouchEnded →
   *  damage: ≈ maxHp/20). Returns true if a wall took the tap. */
  tapWall(id: string): boolean {
    const w = this.enemies.find((e) => e.id === id && e.isWall && e.alive);
    if (!w) return false;
    this.dealDamage(w, WALL_TAP_DAMAGE, true);
    w.struckThisTick = true;
    return true;
  }

  /** Launch a projectile at a target, LEADING its (capped) motion so it connects with
   *  advancing zombies. Ballistic by default (a lobbed throw); pass `straight` for a
   *  fast flat bolt (alien laser). */
  private launchProjectile(
    target: SimUnit,
    damage: number,
    sprite: string,
    spriteSize: number,
    opts: { straight?: boolean; originDx?: number; originDy?: number } = {}
  ) {
    const x0 = BOSS_STRUCT_X + (opts.originDx ?? 0);
    const y0 = BOSS_STRUCT_Y + (opts.originDy ?? 0);
    const grav = opts.straight ? 0 : GRAVITY;
    // Flight time: a straight bolt is range/speed; a ballistic lob scales with range.
    const T = opts.straight
      ? (Math.hypot(target.x - x0, target.y - y0) || 1) / LASER_SPEED
      : clamp(Math.abs(target.x - x0) / 520 + 0.7, 0.85, 1.7);
    // Aim where the target will be after T, using its speed-capped lead velocity — a
    // LOB only. A straight bolt is fired at wherever the target stood when the trigger
    // was pulled: `shootBullet:from:` reads `[target position]` once and hands the raw
    // point to `shootBulletAt:from:`, which just normalizes the difference. No lead.
    const { vx: lvx, vy: lvy } = opts.straight
      ? { vx: 0, vy: 0 }
      : this.leadVelocity(target);
    const tx = target.x + lvx * T;
    const ty = target.y + lvy * T;
    let vx: number;
    let vy: number;
    if (opts.straight) {
      const dx = tx - x0;
      const dy = ty - y0;
      const d = Math.hypot(dx, dy) || 1;
      vx = (dx / d) * LASER_SPEED;
      vy = (dy / d) * LASER_SPEED;
    } else {
      vx = (tx - x0) / T;
      vy = (ty - y0) / T - 0.5 * GRAVITY * T; // ballistic solve to the lead point
    }
    this.projectiles.push({
      id: `proj${this.projSeq++}`,
      x: x0,
      y: y0,
      vx,
      vy,
      rot: 0,
      rotSpeed: (vx < 0 ? -1 : 1) * 7,
      damage: damage > 0 ? Math.max(1, Math.round(damage)) : 0,
      sprite,
      spriteSize,
      done: false,
      gravity: grav,
    });
  }

  /** Integrate each throw under gravity; lazy circle collision vs zombies; a throw
   *  that reaches the ground has missed. Fast/small zombies can be missed. */
  private stepProjectiles(dtMs: number) {
    const dt = dtMs / 1000;
    for (const pr of this.projectiles) {
      if (pr.done) continue;
      pr.vy += pr.gravity * dt; // gravity 0 for straight bolts (alien laser)
      pr.x += pr.vx * dt;
      pr.y += pr.vy * dt;
      pr.rot += pr.rotSpeed * dt;
      const hitR = ZOMBIE_HIT_R + pr.spriteSize * PROJ_HIT_FACTOR;
      for (const p of this.players) {
        // A thrown item can only strike zombies that have moved out to fight —
        // ones still waiting in the group or charging up are safe.
        if (!p.alive || (p.state !== "advance" && p.state !== "fight")) continue;
        const dx = p.x - pr.x;
        const dy = p.y - pr.y;
        if (dx * dx + dy * dy <= hitR * hitR) {
          // Carried grabs are the Trapeze Artist (stepGrabbers) and the Beach crab
          // (stepCrabs), not projectiles — a projectile only ever deals damage.
          this.dealEnemyDamage(p, pr.damage);
          p.struckThisTick = true;
          // The ninja's throws stun on hit from t7 (raid 13). The only projectiles in that
          // fight are his, so the rule needs no owner check.
          const throwStun = this.duel?.throwStunMs ?? 0;
          if (throwStun > 0 && p.alive) p.stunMs = Math.max(p.stunMs, throwStun);
          this.projectileImpactsThisTick++;
          this.lastProjectileImpactSprite = pr.sprite;
          pr.done = true;
          break;
        }
      }
      if (pr.done) continue;
      // A ballistic throw fizzles (misses) once it reaches the ground.
      if (pr.y >= GROUND_Y) pr.done = true;
      // A GRAVITY-FREE bolt (the alien laser) never comes down, so the ground test can
      // never retire one that missed. Fizzle it at the lane edges instead.
      else if (pr.gravity === 0 && (pr.x < -80 || pr.x > FIELD_W + 80)) pr.done = true;
    }
    // Compact in place (keep the readonly array reference stable).
    let w = 0;
    for (let r = 0; r < this.projectiles.length; r++) {
      if (!this.projectiles[r].done) this.projectiles[w++] = this.projectiles[r];
    }
    this.projectiles.length = w;
  }

  /** Whether the player side won (all enemies dead). Meaningful once finished. */
  get playerWon(): boolean {
    return !this.anyAlive(this.enemies);
  }

  /** Ms left on the FIGHT clock — the one that ends the battle. Drives the HUD countdown,
   *  and is simulated time, never wall clock: a stuttering frame rate must not be able to
   *  shorten a fight the server will replay at a fixed 50 ms a tick. */
  timeRemainingMs(): number {
    // Once Do or Die starts the countdown is its own minute, not the spent clock's 0:00.
    return Math.max(0, (this.doOrDie ? this.fightClockMs : this.timeLimitMs) - this.elapsed);
  }

  /** Arm DO OR DIE: `ms` of overtime after the clock, clamped so the whole fight stays inside
   *  RAID_MAX_TIME_LIMIT_MS (the replay's ceiling). Set once, by buildFight, before the first
   *  step; it is pinned config, not state, so snapshots do not carry it. */
  armDoOrDie(ms: number): void {
    const room = RAID_MAX_TIME_LIMIT_MS - this.timeLimitMs;
    this._doOrDieMs = Math.max(0, Math.min(room, Math.round(Number.isFinite(ms) ? ms : 0)));
  }

  /** The overtime this fight carries (0 on every fight but Halloween's). */
  get doOrDieMs(): number {
    return this._doOrDieMs;
  }

  /** The clock has run out and the fight is in its Do or Die overtime. */
  get doOrDie(): boolean {
    return this._doOrDieMs > 0 && this.elapsed >= this.timeLimitMs;
  }

  /** When the fight actually stops: the clock plus any Do or Die overtime. */
  get fightClockMs(): number {
    return this.timeLimitMs + this._doOrDieMs;
  }

  /** Ms left before the boss enrages (0 once enraged / no boss). For the HUD timer. */
  roundRemainingMs(): number {
    return this.boss ? Math.max(0, this.roundLeft) : 0;
  }

  /** Has the boss enraged (round timer expired)? Drives the HUD's ENRAGED banner. */
  get enraged(): boolean {
    return this._enraged;
  }

  /** Snapshot the result in the shape the reward pipeline expects.
   *
   *  Boundless Vitality (v90) is settled HERE, after the fight is over: a zombie with it
   *  falls and stays down for the rest of the battle like any other, then is reported as
   *  a survivor instead of a loss. Every settlement reads this one list — invasions,
   *  elite and dual fights, Halloween nights, Epic Boss — so it is never buried, gets its
   *  veterancy and counts toward the win's survivor share. */
  outcome(): RaidOutcome {
    const standsUp = (u: SimUnit) => u.alive || getsBackUp(u.abilities);
    return {
      win: this.playerWon,
      rounds: this.attacksLanded,
      survivors: this.players.filter(standsUp).map((u) => u.id),
      losses: this.players.filter((u) => !standsUp(u)).map((u) => u.id),
      // A pixel zombie broken open is a RESCUE, not a kill — it was one of yours. Counting
      // it would put a rescue in the "Enemies Beaten" line on the results panel.
      enemiesBeaten: this.enemies.filter((e) => !e.alive && !e.isTurned).length,
      playerDamage: this.playerDamage,
      escaped: this.escaped,
      outOfTime: this.outOfTime,
      healersOnly: this.healersOnlyEnd,
      feats: {
        abilityKills: this.feats.abilityKills.map((kill) => ({ ...kill })),
        resurrections: this.feats.resurrections.map((rez) => ({ ...rez })),
      },
    };
  }
}
